#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
zinc_graphgps_grit_paper_metrics.py

Alpha-weighted global-permutation positional/symbolic specialisation metrics for
graph transformers, adapted from Urrutia et al., "Decoupling Positional and
Symbolic Attention Behavior in Transformers", applied to pretrained official
GraphGPS (GPS+RWSE), GRIT (RRWP), Graphormer, CSA, and v19 ZINC checkpoints.

Channels and metrics
--------------------
Graph transformers expose multiple semantically distinct input channels:
  - x          : node-level symbolic features (atom identity).
  - PE         : explicit structural-encoding tensor (RWSE for GPS+RWSE, RRWP
                 for GRIT+RRWP).
  - edges      : edge_index (and bond features in edge_attr).

The paper's positional/symbolic dichotomy is generated by ONE permutation sigma
acting on a single channel. We compute TWO theoretically-aligned (invariance,
equivariance) score pairs, each driven by a within-graph node permutation that
acts on a single channel and holds all others fixed:

  Pair 1 (x-only permutation; the paper's pair):
    positional_score (invariance)   = head ignores atom identity
    symbolic_score   (equivariance) = head depends only on atom identity

  Pair 2 (PE-only permutation):
    pe_invariance   (invariance)    = head ignores the structural encoding
    pe_equivariance (equivariance)  = head depends only on the structural
                                      encoding (in GRIT, additionally
                                      requires bond-attr blindness because
                                      the encoder mixes bond + RRWP)

Both pairs satisfy the same exclusion principle (Theorem 1): a head can have
both scores high in one pair only via approximately uniform attention. The
clean entropy heatmap is the diagnostic for that case.

Plus one structural-symbolic entanglement diagnostic driven by the JOINT x+PE
permutation under the SAME sigma, which tests additivity of the logit:

  entanglement_score (in [0, 1]):
    For an additively-decomposable head L(x, PE) = f(x) + g(PE), the
    four-cell ANOVA-style interaction vanishes:
        Z_both - Z_clean == (Z_x - Z_clean) + (Z_pe - Z_clean).
    We score 0.5*(1 - cos(...)) on row-centred logits over valid pair slots:
    0 = additive, 0.5 = orthogonal joint effect, 1 = anti-correlated.
    Filter using positional_score / pe_invariance to discard heads whose
    individual perturbation responses are below noise.

Edge-only and bond-attr-only permutations were considered but are deliberately
not included: they affect GraphGPS global MHA only indirectly (via the
local-message-passing branch and the input encoder) and GRIT directly (via
the additive edge bias), so the cross-architecture interpretation is
asymmetric.

For each (layer, head) we also compute clean attention entropy in [0, 1],
normalised per query row by log of the number of valid keys.

The core scores use global within-graph node permutations. Each permutation is
an actual forward pass on a channel-permuted graph input. Scores are computed
per graph, head, and query, alpha-weighted by the amount of attention probability
mass moved by that permutation, and then averaged over valid queries. The default
comparison space is post-softmax attention, and the score is raw cosine
similarity in that attention space.

Centered variants of the x-only and PE-only scores use the same forward passes,
transported references, and alpha weights, but compare mean-subtracted
post-softmax attention rows with raw cosine. These scores are not shifted into
[0, 1]; diffuse/background attention maps to approximately zero.

Mixed centered metrics use the joint x+PE forward pass to measure non-additive
attention-residual interaction and joint equivariance excess over the best
single-channel explanation.

Outputs
-------
- CSVs: per-row and per-(model, layer, head, metric) summaries.
- Heatmaps for the core attention raw-cosine metrics plus sanity/diagnostic metrics.
- Plane scatters: x-perm plane (paper analogue) and PE-perm plane.
- Channel-sensitivity scatter: x-sensitivity vs PE-sensitivity per head.
- Layer-wise mean +/- std curves over all configured models.

Usage in Colab
--------------
    !python zinc_graphgps_grit_paper_metrics.py
"""

