# -----------------------------------------------------------------------------
# Warning suppression and runtime compatibility patches
# -----------------------------------------------------------------------------


def suppress_known_runtime_warnings() -> None:
    warnings.filterwarnings(
        "ignore", message=r"TypedStorage is deprecated.*", category=UserWarning
    )
    warnings.filterwarnings(
        "ignore", message=r".*invalid escape sequence.*", category=SyntaxWarning
    )
    filters = [
        "ignore:TypedStorage is deprecated:UserWarning",
        "ignore:invalid escape sequence:SyntaxWarning",
    ]
    existing = os.environ.get("PYTHONWARNINGS", "")
    parts = [x for x in existing.split(",") if x]
    for filt in filters:
        if filt not in parts:
            parts.append(filt)
    os.environ["PYTHONWARNINGS"] = ",".join(parts)


suppress_known_runtime_warnings()


def apply_runtime_compat_patches() -> None:
    """Fixes for common Colab/PyTorch/PyG version skew. Inference-only."""
    orig_load = getattr(torch, "_paper_metrics_orig_load", None)
    if orig_load is None:
        torch._paper_metrics_orig_load = torch.load  # type: ignore[attr-defined]
        orig_load = torch.load

        def _compat_torch_load(*args, **kwargs):
            kwargs.setdefault("weights_only", False)
            return orig_load(*args, **kwargs)

        torch.load = _compat_torch_load  # type: ignore[assignment]

    try:
        import pkgutil
        if not hasattr(pkgutil, "ImpImporter"):
            class _CompatImpImporter:
                pass
            pkgutil.ImpImporter = _CompatImpImporter  # type: ignore[attr-defined]
    except Exception:
        pass

    try:
        import importlib.machinery
        if not hasattr(importlib.machinery.FileFinder, "find_module"):
            def _compat_find_module(self, fullname, path=None):
                spec = self.find_spec(fullname)
                return None if spec is None else spec.loader
            importlib.machinery.FileFinder.find_module = _compat_find_module  # type: ignore[attr-defined]
    except Exception:
        pass

    try:
        import inspect
        import sklearn.metrics as _sk_metrics
        sig = inspect.signature(_sk_metrics.mean_squared_error)
        if "squared" not in sig.parameters:
            _orig_mse = _sk_metrics.mean_squared_error
            def _compat_mse(y_true, y_pred, *, sample_weight=None,
                            multioutput="uniform_average", squared=True):
                out = _orig_mse(y_true, y_pred, sample_weight=sample_weight,
                                multioutput=multioutput)
                return out if squared else np.sqrt(out)
            _sk_metrics.mean_squared_error = _compat_mse
    except Exception:
        pass


