@dataclass
class ModelSpec:
    name: str
    family: str  # "graphgps" or "grit"
    repo_dir: str
    repo_url: str
    commit: str
    cfg_relpath: str
    run_root: str
    data_dir: str
    ckpt_path: Optional[str] = None
    name_tag: str = ""


@dataclass
class RunConfig:
    split: str = "val"
    out_dir: str = "/content/drive/MyDrive/zinc_graphgps_grit_paper_metrics_v2"
    batch_size: int = 32
    metric_batches: int = 1
    num_perms: int = 128
    metric_alpha_tau: float = 0.1
    metric_space: str = "attention"
    seed: int = 123
    num_workers: int = 0
    device: str = "cuda" if torch.cuda.is_available() else "cpu"
    auto_mount_drive: bool = True
    auto_clone_repos: bool = True
    skip_install: bool = False
    force_install: bool = False
    pyg_version: str = "2.2.0"
    verbose_every: int = 1
    run_causal_ablations: bool = False
    causal_split: Optional[str] = None
    # Fast defaults: Colab main() runs causal tests by default, so keep the
    # causal pass useful but not prohibitively expensive. Override these flags
    # for final/full runs.
    causal_batches: int = 4
    causal_topk: str = "1,2,4"
    causal_random_trials: int = 24
    causal_bootstrap_samples: int = 300
    causal_permutation_samples: int = 1024
    causal_subset_quantile: float = 0.80
    causal_interventions: str = "head_output_zero,bias_zero,struct_value_zero"
    causal_single_head: bool = False
    causal_seed: Optional[int] = None
    # Stashed by parse_args for the standalone-model loaders (not part of the
    # graphgym config flow). Underscore-prefixed because these are read by
