def parse_args() -> RunConfig:
    p = argparse.ArgumentParser(
        description="Paper-faithful positional/symbolic specialisation metrics "
                    "for ZINC graph-transformer checkpoints."
    )
    p.add_argument("--out-dir", type=str, default=RunConfig.out_dir)
    p.add_argument("--split", type=str, choices=["train", "val", "test"], default="val")
    p.add_argument("--batch-size", type=int, default=32)
    p.add_argument("--metric-batches", type=int, default=1)
    p.add_argument("--num-perms", type=int, default=128)
    p.add_argument("--metric-alpha-tau", type=float, default=0.1)
    p.add_argument("--metric-space", type=str, choices=["logits", "attention"], default="attention")
    p.add_argument("--seed", type=int, default=123)
    p.add_argument("--num-workers", type=int, default=0)
    p.add_argument("--device", type=str, default=RunConfig.device)
    p.add_argument("--auto-clone-repos", action="store_true", default=True)
    p.add_argument("--no-auto-clone-repos", dest="auto_clone_repos", action="store_false")
    p.add_argument("--no-auto-mount-drive", dest="auto_mount_drive", action="store_false")
    p.add_argument("--skip-install", action="store_true")
    p.add_argument("--force-install", action="store_true")
    p.add_argument("--pyg-version", type=str, default="2.2.0")
    p.add_argument("--verbose-every", type=int, default=1)
    causal_default = in_colab()
    p.add_argument("--run-causal-ablations", action="store_true",
                   default=causal_default,
                   help="Run metric-guided causal head ablations after collecting metrics. "
                        "Defaults on in Colab, off outside Colab.")
    p.add_argument("--no-run-causal-ablations", dest="run_causal_ablations",
                   action="store_false",
                   help="Disable causal head ablations, even in Colab.")
    p.add_argument("--causal-split", type=str, choices=["train", "val", "test"],
                   default=None,
                   help="Split used for causal ablation evaluation. Defaults to --split.")
    p.add_argument("--causal-batches", type=int, default=RunConfig.causal_batches,
                   help="Maximum batches for causal ablation evaluation.")
    p.add_argument("--causal-topk", type=str, default=RunConfig.causal_topk,
                   help="Comma-separated top-k values for targeted head groups.")
    p.add_argument("--causal-random-trials", type=int,
                   default=RunConfig.causal_random_trials,
                   help="Random global and layer-matched null trials per targeted group.")
    p.add_argument("--causal-bootstrap-samples", type=int,
                   default=RunConfig.causal_bootstrap_samples,
                   help="Bootstrap samples for causal effect confidence intervals.")
    p.add_argument("--causal-permutation-samples", type=int,
                   default=RunConfig.causal_permutation_samples,
                   help="Sign-flip permutation samples for paired excess p-values.")
    p.add_argument("--causal-subset-quantile", type=float, default=0.80,
                   help="Metric-row quantile used for graph-subset causal summaries.")
    p.add_argument("--causal-interventions", type=str,
                   default=RunConfig.causal_interventions,
                   help="Comma-separated interventions to run.")
    p.add_argument("--causal-single-head", dest="causal_single_head",
                   action="store_true", default=RunConfig.causal_single_head,
                   help="Run the expensive all-single-head causal sweep.")
    p.add_argument("--no-causal-single-head", dest="causal_single_head",
                   action="store_false",
                   help="Skip all single-head ablations and metric/causal scatter plots.")
    p.add_argument("--causal-seed", type=int, default=None,
                   help="Optional RNG seed for causal random nulls; defaults to --seed + 1009.")
    p.add_argument("--causal-full", action="store_true",
                   help="Convenience preset for slower final causal runs: "
                        "batches=16, topk=1,2,4,8, random_trials=128, "
                        "bootstrap=1000, signflip=4096, all interventions, "
                        "single-head sweep enabled.")

    p.add_argument("--graphgps-repo-dir", type=str, default=GRAPHGPS_REPO_DIR)
    p.add_argument("--graphgps-run-root", type=str, default=GRAPHGPS_RUN_ROOT)
    p.add_argument("--graphgps-data-dir", type=str, default=GRAPHGPS_DATA_DIR)
    p.add_argument("--graphgps-ckpt", type=str, default=GRAPHGPS_CKPT)
    p.add_argument("--grit-repo-dir", type=str, default=GRIT_REPO_DIR)
    p.add_argument("--grit-run-root", type=str, default=GRIT_RUN_ROOT)
    p.add_argument("--grit-data-dir", type=str, default=GRIT_DATA_DIR)
    p.add_argument("--grit-ckpt", type=str, default=GRIT_CKPT)
    p.add_argument("--graphormer-run-root", type=str, default=GRAPHORMER_RUN_ROOT)
    p.add_argument("--graphormer-data-dir", type=str, default=GRAPHORMER_DATA_DIR)
    p.add_argument("--graphormer-cache-dir", type=str, default=GRAPHORMER_CACHE_DIR)
    p.add_argument("--graphormer-ckpt", type=str, default=GRAPHORMER_CKPT)
    p.add_argument("--csa-run-root", type=str, default=CSA_RUN_ROOT)
    p.add_argument("--csa-data-dir", type=str, default=CSA_DATA_DIR)
    p.add_argument("--csa-cache-path", type=str, default=CSA_CACHE_PATH)
    p.add_argument("--csa-ckpt", type=str, default=CSA_CKPT)
    p.add_argument("--v19-run-root", type=str, default=V19_RUN_ROOT)
    p.add_argument("--v19-data-dir", type=str, default=V19_DATA_DIR)
    p.add_argument("--v19-ckpt", type=str, default=V19_CKPT)

    args, unknown = p.parse_known_args()
    if unknown:
        print(f"[args] Ignoring kernel args: {unknown}")
    if args.causal_full:
        args.causal_batches = 16
        args.causal_topk = "1,2,4,8"
        args.causal_random_trials = 128
        args.causal_bootstrap_samples = 1000
        args.causal_permutation_samples = 4096
        args.causal_interventions = "head_output_zero,bias_zero,content_zero,struct_value_zero"
        args.causal_single_head = True
    cfg = RunConfig(
        split=args.split, out_dir=args.out_dir, batch_size=args.batch_size,
        metric_batches=args.metric_batches, num_perms=args.num_perms,
        metric_alpha_tau=args.metric_alpha_tau, metric_space=args.metric_space,
        seed=args.seed, num_workers=args.num_workers, device=args.device,
        auto_mount_drive=args.auto_mount_drive,
        auto_clone_repos=args.auto_clone_repos, skip_install=args.skip_install,
        force_install=args.force_install, pyg_version=args.pyg_version,
        verbose_every=args.verbose_every,
        run_causal_ablations=args.run_causal_ablations,
        causal_split=args.causal_split,
        causal_batches=args.causal_batches,
        causal_topk=args.causal_topk,
        causal_random_trials=args.causal_random_trials,
        causal_bootstrap_samples=args.causal_bootstrap_samples,
        causal_permutation_samples=args.causal_permutation_samples,
        causal_subset_quantile=args.causal_subset_quantile,
        causal_interventions=args.causal_interventions,
        causal_single_head=args.causal_single_head,
        causal_seed=args.causal_seed,
    )
    cfg.models = [
        ModelSpec(name="v19", family="v19",
                  repo_dir=V19_REPO_DIR, repo_url=V19_REPO,
                  commit=V19_COMMIT, cfg_relpath=V19_CFG,
                  run_root=args.v19_run_root, data_dir=args.v19_data_dir,
                  ckpt_path=args.v19_ckpt,
                  name_tag="LatentPairMemory.ValueActive"),
        ModelSpec(name="graphgps_gps_rwse", family="graphgps",
                  repo_dir=args.graphgps_repo_dir, repo_url=GRAPHGPS_REPO,
                  commit=GRAPHGPS_COMMIT, cfg_relpath=GRAPHGPS_CFG,
                  run_root=args.graphgps_run_root, data_dir=args.graphgps_data_dir,
                  ckpt_path=args.graphgps_ckpt,
                  name_tag="ColabDrive.official.GPSwRWSE"),
        ModelSpec(name="grit_rrwp", family="grit",
                  repo_dir=args.grit_repo_dir, repo_url=GRIT_REPO,
                  commit=GRIT_COMMIT, cfg_relpath=GRIT_CFG,
                  run_root=args.grit_run_root, data_dir=args.grit_data_dir,
                  ckpt_path=args.grit_ckpt,
                  name_tag="ColabDrive.official.GRITwRRWP"),
        ModelSpec(name="graphormer_slim", family="graphormer",
                  repo_dir=GRAPHORMER_REPO_DIR, repo_url=GRAPHORMER_REPO,
                  commit=GRAPHORMER_COMMIT, cfg_relpath=GRAPHORMER_CFG,
                  run_root=args.graphormer_run_root,
                  data_dir=args.graphormer_data_dir,
                  ckpt_path=args.graphormer_ckpt,
                  name_tag="Standalone.GraphormerSLIM"),
        ModelSpec(name="csa_sym", family="csa",
                  repo_dir=CSA_REPO_DIR, repo_url=CSA_REPO,
                  commit=CSA_COMMIT, cfg_relpath=CSA_CFG,
                  run_root=args.csa_run_root, data_dir=args.csa_data_dir,
                  ckpt_path=args.csa_ckpt,
                  name_tag="StaticAnchor.SymBiasValue"),
    ]
    # Stash extras for downstream loaders.
    cfg._graphormer_cache_dir = args.graphormer_cache_dir
    cfg._csa_cache_path = args.csa_cache_path
    return cfg


# -----------------------------------------------------------------------------
# Small utilities
# -----------------------------------------------------------------------------


def safe_mkdir(path) -> Path:
    p = Path(path)
    p.mkdir(parents=True, exist_ok=True)
    return p


def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def safe_torch_load(path, map_location=None):
    try:
        return torch.load(path, map_location=map_location, weights_only=False)
    except TypeError:
        return torch.load(path, map_location=map_location)


def _is_pyg_zinc_processed_file(path: Any) -> bool:
    text = str(path)
    return (
        text.endswith("/processed/train.pt")
        or text.endswith("/processed/val.pt")
        or text.endswith("/processed/test.pt")
        or text.endswith("\\processed\\train.pt")
        or text.endswith("\\processed\\val.pt")
        or text.endswith("\\processed\\test.pt")
    )


def load_pyg_zinc_dataset(root: str | Path, split: str):
    """Load PyG ZINC across old/new processed-cache tuple formats.

    Some Drive caches were written by newer PyG versions as
    ``(data, slices, data_cls)`` while older GraphGPS-era PyG code unpacks only
    ``(data, slices)`` inside ``torch_geometric.datasets.ZINC.__init__``. The
    model checkpoints were trained with the older GraphGym stack, so keep that
    stack but make processed-cache reads backwards compatible.
    """
    from torch_geometric.datasets import ZINC

    original_load = torch.load

    def compat_load(path, *args, **kwargs):
        out = original_load(path, *args, **kwargs)
        if _is_pyg_zinc_processed_file(path) and isinstance(out, tuple) and len(out) >= 3:
            data, slices, data_cls = out[:3]
            if isinstance(data, dict) and hasattr(data_cls, "from_dict"):
                data = data_cls.from_dict(data)
            return data, slices
        return out

    torch.load = compat_load  # type: ignore[assignment]
    try:
        return ZINC(root=str(root), subset=True, split=str(split))
    finally:
        torch.load = original_load  # type: ignore[assignment]


def in_colab() -> bool:
    try:
        import google.colab  # type: ignore  # noqa: F401
        return True
    except Exception:
        return False


def mount_drive_if_needed(enable: bool = True) -> None:
    if not enable or not in_colab():
        return
    from google.colab import drive  # type: ignore
    print("[drive] Mounting Google Drive at /content/drive")
    drive.mount("/content/drive", force_remount=False)


def run_cmd(cmd, cwd=None, check: bool = True) -> subprocess.CompletedProcess:
    print("[cmd]", " ".join(map(str, cmd)))
    proc = subprocess.run(list(map(str, cmd)),
                          cwd=str(cwd) if cwd else None, text=True, check=False)
    if check and proc.returncode != 0:
        raise RuntimeError(
            f"Command failed (code {proc.returncode}): {' '.join(map(str, cmd))}"
        )
    return proc


# -----------------------------------------------------------------------------
# Dependency installation
# -----------------------------------------------------------------------------


def _module_importable(name: str) -> bool:
    try:
        importlib.import_module(name)
        return True
    except Exception:
        return False


def _pip_install(args) -> None:
    run_cmd([sys.executable, "-m", "pip", "install", *args])


def _torch_pyg_wheel_url() -> str:
    tv = str(torch.__version__).split("+")[0]
    cv = getattr(torch.version, "cuda", None)
    cuda_tag = "cu" + cv.replace(".", "") if cv else "cpu"
    return f"https://data.pyg.org/whl/torch-{tv}+{cuda_tag}.html"


def ensure_runtime_dependencies(cfg: RunConfig) -> None:
    apply_runtime_compat_patches()
    if cfg.skip_install:
        print("[deps] --skip-install set; assuming dependencies are available.")
        return
    required = ["torch_geometric", "torch_scatter", "torch_sparse", "torch_cluster",
                "yacs", "pytorch_lightning", "torchmetrics", "performer_pytorch",
                "tensorboardX", "ogb", "sklearn", "networkx"]
    missing = [m for m in required if not _module_importable(m)]
    if not cfg.force_install and not missing:
        print("[deps] Required modules already importable.")
        return
    if missing:
        print(f"[deps] Missing modules: {missing}")
    run_cmd([sys.executable, "-m", "pip", "install", "--upgrade",
             "pip", "setuptools", "wheel"])
    wheel_url = _torch_pyg_wheel_url()
    print(f"[deps] PyG wheel index: {wheel_url}")
    # Modern PyG wheel indexes do not always ship torch-spline-conv
    # (e.g. torch 2.11 + CUDA 12.8), and this ZINC inference pipeline does not
    # use spline convolutions. Keep the install to the extensions required by
    # GraphGym/GRIT/GraphGPS.
    _pip_install(["pyg-lib", "torch-scatter", "torch-sparse", "torch-cluster",
                  "-f", wheel_url])
    _pip_install([f"torch-geometric=={cfg.pyg_version}"])
    _pip_install(["yacs==0.1.8", "pytorch-lightning==1.9.5",
                  "torchmetrics==0.11.4", "performer-pytorch==1.1.4",
                  "tensorboardX>=2.6,<2.7", "ogb==1.3.6", "wandb>=0.16,<0.18",
                  "pyyaml>=6.0", "scikit-learn>=1.0", "scipy>=1.9",
                  "networkx>=2.8", "pandas>=1.5", "matplotlib>=3.6",
                  "tabulate>=0.9"])
    importlib.invalidate_caches()
    apply_runtime_compat_patches()
    still_missing = [m for m in required if not _module_importable(m)]
    if still_missing:
        raise RuntimeError(
            f"Dependency install finished but these still fail to import: "
            f"{still_missing}. Restarting the Colab runtime usually fixes "
            f"post-install import-cache issues."
        )
    print("[deps] Dependency import check passed.")


# -----------------------------------------------------------------------------
# Repo and checkpoint discovery
# -----------------------------------------------------------------------------


def ensure_repo(spec: ModelSpec, auto_clone: bool) -> Path:
    repo_dir = Path(spec.repo_dir)
    if repo_dir.exists():
        if (repo_dir / ".git").exists() and spec.commit:
            try:
                run_cmd(["git", "checkout", spec.commit], cwd=repo_dir)
            except Exception as exc:
                print(f"[repo][warning] checkout {spec.commit} failed: {exc}")
        return repo_dir
    if not auto_clone:
        raise FileNotFoundError(f"Repo for {spec.name} not at {repo_dir}")
    safe_mkdir(repo_dir.parent)
    run_cmd(["git", "clone", spec.repo_url, str(repo_dir)])
    if spec.commit:
        run_cmd(["git", "checkout", spec.commit], cwd=repo_dir)
    return repo_dir


def prepend_sys_path(path: Path) -> None:
    sp = str(path.resolve())
    if sp not in sys.path:
        sys.path.insert(0, sp)


def make_graphgym_registration_idempotent(prefer_latest: bool = True) -> None:
    """Allow GraphGPS and GRIT registries to coexist in one Python process."""
    try:
        import torch_geometric.graphgym.register as gg_register
    except Exception:
        return
    if getattr(gg_register, "_paper_metrics_idempotent", False):
        return
    seen = set()

    def _safe_register_base(mapping, key, module=None):
        def _install(mod):
            if key in mapping:
                if mapping[key] is mod:
                    return mod
                if prefer_latest:
                    mapping[key] = mod
                    if key not in seen:
                        print(f"[graphgym][registry] duplicate {key!r}; using latest")
                        seen.add(key)
                    return mod
                if key not in seen:
                    print(f"[graphgym][registry] duplicate {key!r}; keeping existing")
                    seen.add(key)
                return mod
            mapping[key] = mod
            return mod
        return _install if module is None else _install(module)

    gg_register.register_base = _safe_register_base
    gg_register._paper_metrics_idempotent = True


def clear_partial_repo_imports(package_name: str) -> None:
    for name in list(sys.modules.keys()):
        if name == package_name or name.startswith(package_name + "."):
            del sys.modules[name]


def find_checkpoint(run_root, explicit=None) -> Path:
    if explicit:
        root = Path(explicit)
        if not root.exists():
            raise FileNotFoundError(f"Explicit ckpt does not exist: {root}")
        if root.is_file():
            return root
        for name in ["checkpoint_latest.pt", "latest.pt", "last.pt", "last.ckpt"]:
            p = root / name
            if p.exists() and p.is_file():
                print(f"[ckpt] Selected explicit-dir latest checkpoint: {p}")
                return p
    else:
        root = Path(run_root)
    if not root.exists():
        raise FileNotFoundError(f"Run root does not exist: {root}")
    cands = []
    for pat in ["*.ckpt", "*.pt", "*.pth"]:
        cands.extend(root.rglob(pat))
    cands = [p for p in cands if p.is_file() and "optim" not in p.name.lower()]
    if not cands:
        raise FileNotFoundError(f"No checkpoint files under {root}")

    def score(p):
        name = str(p).lower()
        prio = 0
        if "best" in name: prio += 10000
        if "last" in name or "latest" in name: prio += 5000
        ep_nums = [int(x) for x in re.findall(r"(?:epoch|ep|ckpt)[_=-]?(\d+)", name)]
        any_nums = [int(x) for x in re.findall(r"(\d+)", p.name)]
        epoch = max(ep_nums or any_nums or [0])
        return prio, epoch, p.stat().st_mtime

    cands.sort(key=score, reverse=True)
    chosen = cands[0]
    print(f"[ckpt] Selected: {chosen}")
    return chosen


def _state_dict_candidates(state):
    raw = dict(state)
    out = [raw]
    prefixes = ("model.", "module.", "_orig_mod.", "model.model.")
    for pre in prefixes:
        if any(k.startswith(pre) for k in raw):
            out.append({k[len(pre):] if k.startswith(pre) else k: v
                        for k, v in raw.items()})
    for p1 in ("module.", "_orig_mod."):
        for p2 in ("model.", "model.model."):
            pre = p1 + p2
            if any(k.startswith(pre) for k in raw):
                out.append({k[len(pre):] if k.startswith(pre) else k: v
                            for k, v in raw.items()})
    seen = set()
    uniq = []
    for c in out:
        sig = tuple(list(c.keys())[:20])
        if sig not in seen:
            uniq.append(c)
            seen.add(sig)
    return uniq


def _choose_state_dict(model, state):
    ms = model.state_dict()
    best = None
    best_score = (-1, -10**9)
    for cand in _state_dict_candidates(state):
        matches, mismatches = 0, 0
        for k, v in cand.items():
            if k in ms:
                if hasattr(v, "shape") and tuple(v.shape) == tuple(ms[k].shape):
                    matches += 1
                else:
                    mismatches += 1
        sc = (matches, -mismatches)
        if sc > best_score:
            best_score = sc
            best = cand
    if best is None or best_score[0] <= 0:
        raise RuntimeError("Could not match checkpoint to model state_dict")
    print(f"[ckpt] Matched {best_score[0]} tensors")
    return best


def _extract_state(ckpt):
    if not isinstance(ckpt, Mapping):
        return ckpt
    for key in ["model_state", "model_state_dict", "state_dict",
                "model", "net", "network"]:
        if key in ckpt and isinstance(ckpt[key], Mapping):
            return ckpt[key]
    if all(torch.is_tensor(v) or isinstance(v, torch.nn.Parameter)
           for v in ckpt.values()):
        return ckpt
    raise KeyError(f"Cannot find state_dict in {list(ckpt.keys())[:20]}")


def load_checkpoint(model, ckpt_path, device) -> Dict[str, Any]:
    ckpt = safe_torch_load(ckpt_path, map_location=device)
    state = _choose_state_dict(model, _extract_state(ckpt))
    missing, unexpected = model.load_state_dict(state, strict=False)
    if missing or unexpected:
        print("[ckpt][warning] non-strict load:")
        print("  missing   :", missing[:10], "..." if len(missing) > 10 else "")
        print("  unexpected:", unexpected[:10], "..." if len(unexpected) > 10 else "")
    meta = {"checkpoint_path": str(ckpt_path),
            "trainable_parameters": int(sum(p.numel() for p in model.parameters()
                                            if p.requires_grad))}
    if isinstance(ckpt, Mapping):
        for k in ["epoch", "best_epoch", "best_val", "best_val_mae",
                  "best_test_mae", "val_mae"]:
            if k in ckpt:
                try:
                    meta[k] = (float(ckpt[k]) if isinstance(ckpt[k], (int, float))
                               else str(ckpt[k]))
                except Exception:
                    meta[k] = str(ckpt[k])
    return meta


# -----------------------------------------------------------------------------
# GraphGym model + loader construction
# -----------------------------------------------------------------------------


def configure_graphgym(spec: ModelSpec, run_cfg: RunConfig, device: torch.device):
    repo_dir = ensure_repo(spec, run_cfg.auto_clone_repos)
    prepend_sys_path(repo_dir)
    make_graphgym_registration_idempotent(prefer_latest=True)
    if spec.family == "graphgps":
        importlib.import_module("graphgps")
    elif spec.family == "grit":
        clear_partial_repo_imports("grit")
        importlib.import_module("grit")
    else:
        raise ValueError(spec.family)

    from torch_geometric.graphgym.config import cfg, load_cfg, set_cfg
    from torch_geometric.graphgym.loader import create_loader
    from torch_geometric.graphgym.model_builder import create_model

    set_cfg(cfg)
    try:
        cfg.set_new_allowed(True)
    except Exception:
        pass

    cfg_path = repo_dir / spec.cfg_relpath
    if not cfg_path.exists():
        raise FileNotFoundError(f"Config not found for {spec.name}: {cfg_path}")

    device_str = "cuda" if device.type == "cuda" else "cpu"
    out_dir = (str(Path(spec.run_root).parents[1])
               if len(Path(spec.run_root).parents) >= 2
               else str(Path(spec.run_root).parent))
    opts = ["seed", str(run_cfg.seed),
            "dataset.dir", spec.data_dir,
            "train.batch_size", str(run_cfg.batch_size),
            "num_workers", str(run_cfg.num_workers),
            "wandb.use", "False",
            "accelerator", device_str,
            "out_dir", out_dir,
            "name_tag", spec.name_tag]
    args_ns = SimpleNamespace(cfg_file=str(cfg_path), opts=opts)
    if spec.family == "grit":
        cfg.work_dir = str(repo_dir)
    load_cfg(cfg, args_ns)
    cfg.accelerator = device_str
    cfg.seed = run_cfg.seed
    cfg.run_id = 0
    cfg.run_dir = str(spec.run_root)

    print(f"[graphgym] Building loaders/model for {spec.name} from {cfg_path}")
    loaders = create_loader()
    try:
        model = create_model(to_device=False)
    except TypeError:
        model = create_model()
    model = model.to(device)
    model.eval()
    return cfg, loaders, model


def split_loader(loaders, split: str):
    return loaders[{"train": 0, "val": 1, "test": 2}[split]]


def get_model_pred(out) -> torch.Tensor:
    if hasattr(out, "pred"):
        return out.pred.view(-1).float()
    if isinstance(out, (tuple, list)):
        for it in out:
            if torch.is_tensor(it):
                return it.view(-1).float()
            if hasattr(it, "pred"):
                return it.pred.view(-1).float()
    if torch.is_tensor(out):
        return out.view(-1).float()
    raise AttributeError("Cannot infer prediction tensor from model output")


# -----------------------------------------------------------------------------
# Standalone-model integration: GraphormerSLIM, CSA, and v19
#
# These models are not built via graphgym. Each was trained by a single
# self-contained notebook script (graphormer_ZINC_core.ipynb and
# CSA_ZINC_core.ipynb). To keep this metrics file copy-and-paste-able into one
# Colab cell, we inline the inference-only parts of each model: model class,
# config dataclass, ZINC data preprocessing + cache loader, batch collator.
#
# These families' batches are NOT PyG Data/Batch objects:
#   - Graphormer batch is a Python dict of named tensors.
#   - CSA batch is a small dataclass (StaticAnchorBatch).
#   - v19 batch is a small dataclass embedded below (V19VariantABatch).
#
# To keep the metric loop's `batch.clone().to(device)` interface intact, the
# loaders below yield instances of GraphormerBatchAdapter, CSABatchAdapter, and
# V19BatchAdapter
# (defined below) which wrap the underlying dict/dataclass and expose
# .clone(), .to(device), .num_graphs, .num_nodes, .num_edges, .counts.
#
# The two cache files written by the training notebooks are reused as-is:
#   - Graphormer per-split records: {data_dir}/zinc_graphormer_cache/
#                                   zinc_subset_graphormer_{split}_mh{K}.pt
#   - CSA precomputed all-splits  : {data_dir}/static_anchor_cache/
#                                   zinc_subset_static_anchor_K12_D5_v1.pt
# If those caches are missing, we recompute them from PyG ZINC on the fly so a
# fresh runtime works without re-running the training notebooks.
# -----------------------------------------------------------------------------


# =============================================================================
# Graphormer: config dataclass, model class (hoisted out of the notebook's
# _define_torch_modules closure), preprocessing, cache, batch adapter.
# =============================================================================


@dataclass
class GraphormerConfig:
    # GraphormerSLIM/ZINC sizes (must match training-time config).
    num_layers: int = 12
    hidden_dim: int = 80
    ffn_dim: int = 80
    num_heads: int = 8
    dropout: float = 0.0
    attention_dropout: float = 0.1
    embedding_dropout: float = 0.0
    activation_dropout: float = 0.1
    num_atom_types: int = 29
    num_edge_types: int = 6
    num_in_degree: int = 6
    num_out_degree: int = 6
    num_spatial: int = 64
    num_edge_dis: int = 128
    multi_hop_max_dist: int = 5
    spatial_pos_max: int = 1024
    encoder_normalize_before: bool = True
    graph_pooling: str = "graph_token"
    num_classes: int = 1

    @property
    def head_dim(self) -> int:
        assert self.hidden_dim % self.num_heads == 0
        return self.hidden_dim // self.num_heads


class GraphormerMHA(nn.Module):
    """Multi-head self-attention with additive per-head graph bias.

    Hoisted from the training notebook's `_define_torch_modules` closure so it
    is identifiable by class name from the AttentionProbeManager. Numerically
    identical to the training-time module: the only behavioural difference is
    the captured pre-softmax logit tensor (consumed by the probe).
    """

    def __init__(self, dim: int, num_heads: int, attn_dropout: float,
                 out_dropout: float) -> None:
        super().__init__()
        assert dim % num_heads == 0
        self.dim = dim
        self.num_heads = num_heads
        self.head_dim = dim // num_heads
        self.scaling = self.head_dim ** -0.5
        self.q_proj = nn.Linear(dim, dim)
        self.k_proj = nn.Linear(dim, dim)
        self.v_proj = nn.Linear(dim, dim)
        self.out_proj = nn.Linear(dim, dim)
        self.attn_dropout = nn.Dropout(attn_dropout)
        self.out_dropout = nn.Dropout(out_dropout)

    def forward(self, x, attn_bias):
        bsz, seq_len, dim = x.shape
        q = self.q_proj(x).view(bsz, seq_len, self.num_heads, self.head_dim).transpose(1, 2)
        k = self.k_proj(x).view(bsz, seq_len, self.num_heads, self.head_dim).transpose(1, 2)
        v = self.v_proj(x).view(bsz, seq_len, self.num_heads, self.head_dim).transpose(1, 2)
        scores = torch.matmul(q, k.transpose(-2, -1)) * self.scaling
        scores = scores + attn_bias
        attn = torch.softmax(scores.float(), dim=-1).to(scores.dtype)
        attn = self.attn_dropout(attn)
        out = torch.matmul(attn, v).transpose(1, 2).contiguous().view(bsz, seq_len, dim)
        out = self.out_proj(out)
        return self.out_dropout(out)


class GraphormerEncoderLayer(nn.Module):
    def __init__(self, cfg: GraphormerConfig) -> None:
        super().__init__()
        self.self_attn = GraphormerMHA(cfg.hidden_dim, cfg.num_heads,
                                       cfg.attention_dropout, cfg.dropout)
        self.self_attn_layer_norm = nn.LayerNorm(cfg.hidden_dim)
        self.fc1 = nn.Linear(cfg.hidden_dim, cfg.ffn_dim)
        self.fc2 = nn.Linear(cfg.ffn_dim, cfg.hidden_dim)
        self.final_layer_norm = nn.LayerNorm(cfg.hidden_dim)
        self.dropout = nn.Dropout(cfg.dropout)
        self.activation_dropout = nn.Dropout(cfg.activation_dropout)

    def forward(self, x, attn_bias):
        residual = x
        x = self.self_attn(x, attn_bias)
        x = residual + x
        x = self.self_attn_layer_norm(x)
        residual = x
        x = self.fc1(x)
        x = F.gelu(x)
        x = self.activation_dropout(x)
        x = self.fc2(x)
        x = self.dropout(x)
        x = residual + x
        x = self.final_layer_norm(x)
        return x


class StandaloneGraphormer(nn.Module):
    """GraphormerSLIM/ZINC model, hoisted out of the notebook closure.

    Forward expects a dict with keys: x, in_degree, out_degree, spatial_pos,
    edge_input, attn_bias, node_mask, y. (y is unused in inference but is part
    of the collated batch.)
    """

    def __init__(self, cfg: GraphormerConfig) -> None:
        super().__init__()
        self.cfg = cfg
        h = cfg.num_heads
        d = cfg.hidden_dim
        self.atom_encoder = nn.Embedding(cfg.num_atom_types + 1, d, padding_idx=0)
        self.in_degree_encoder = nn.Embedding(cfg.num_in_degree, d, padding_idx=0)
        self.out_degree_encoder = nn.Embedding(cfg.num_out_degree, d, padding_idx=0)
        self.graph_token = nn.Embedding(1, d)
        self.spatial_pos_encoder = nn.Embedding(cfg.num_spatial, h, padding_idx=0)
        self.edge_encoder = nn.Embedding(cfg.num_edge_types + 1, h, padding_idx=0)
        self.edge_dis_encoder = nn.Embedding(cfg.num_edge_dis * h * h, 1)
        self.graph_token_virtual_distance = nn.Embedding(1, h)
        self.emb_layer_norm = nn.LayerNorm(d) if cfg.encoder_normalize_before else None
        self.emb_dropout = nn.Dropout(cfg.embedding_dropout)
        self.layers = nn.ModuleList(
            [GraphormerEncoderLayer(cfg) for _ in range(cfg.num_layers)]
        )
        self.lm_head_transform_weight = nn.Linear(d, d)
        self.layer_norm = nn.LayerNorm(d)
        self.embed_out = nn.Linear(d, cfg.num_classes, bias=False)
        self.lm_output_learned_bias = nn.Parameter(torch.zeros(1))

    def build_attn_bias(self, batch):
        spatial_pos = batch["spatial_pos"]
        edge_input = batch["edge_input"]
        attn_bias = batch["attn_bias"]
        x = batch["x"]
        bsz, n = x.size()[:2]
        h = self.cfg.num_heads

        graph_attn_bias = attn_bias.clone().unsqueeze(1).repeat(1, h, 1, 1)
        spatial_pos_bias = self.spatial_pos_encoder(spatial_pos).permute(0, 3, 1, 2)
        graph_attn_bias[:, :, 1:, 1:] = graph_attn_bias[:, :, 1:, 1:] + spatial_pos_bias

        t = self.graph_token_virtual_distance.weight.view(1, h, 1)
        graph_attn_bias[:, :, 1:, 0] = graph_attn_bias[:, :, 1:, 0] + t
        graph_attn_bias[:, :, 0, :] = graph_attn_bias[:, :, 0, :] + t

        spatial_pos_ = spatial_pos.clone()
        spatial_pos_[spatial_pos_ == 0] = 1
        spatial_pos_ = torch.where(spatial_pos_ > 1, spatial_pos_ - 1, spatial_pos_)
        if self.cfg.multi_hop_max_dist > 0:
            spatial_pos_ = spatial_pos_.clamp(0, self.cfg.multi_hop_max_dist)
            edge_input = edge_input[:, :, :, : self.cfg.multi_hop_max_dist, :]

        edge_input = self.edge_encoder(edge_input).mean(-2)
        max_dist = edge_input.size(-2)
        edge_input_flat = edge_input.permute(3, 0, 1, 2, 4).reshape(max_dist, -1, h)
        edge_dis_weight = self.edge_dis_encoder.weight.reshape(-1, h, h)[:max_dist, :, :]
        edge_input_flat = torch.bmm(edge_input_flat, edge_dis_weight)
        edge_input = edge_input_flat.reshape(max_dist, bsz, n, n, h).permute(1, 2, 3, 0, 4)
        edge_input = (edge_input.sum(-2) / spatial_pos_.float().unsqueeze(-1)).permute(0, 3, 1, 2)
        graph_attn_bias[:, :, 1:, 1:] = graph_attn_bias[:, :, 1:, 1:] + edge_input

        graph_attn_bias = graph_attn_bias + attn_bias.unsqueeze(1)
        return graph_attn_bias

    def graph_node_feature(self, batch):
        x = batch["x"]
        in_degree = batch["in_degree"]
        out_degree = batch["out_degree"]
        bsz = x.size(0)
        node_feature = self.atom_encoder(x).sum(dim=-2)
        node_feature = node_feature + self.in_degree_encoder(in_degree) + self.out_degree_encoder(out_degree)
        graph_token_feature = self.graph_token.weight.unsqueeze(0).repeat(bsz, 1, 1)
        return torch.cat([graph_token_feature, node_feature], dim=1)

    def output_projection(self, h):
        z = self.layer_norm(F.gelu(self.lm_head_transform_weight(h)))
        z = self.embed_out(z)
        z = z + self.lm_output_learned_bias
        return z

    def forward(self, batch):
        h = self.graph_node_feature(batch)
        if self.emb_layer_norm is not None:
            h = self.emb_layer_norm(h)
        h = self.emb_dropout(h)
        attn_bias = self.build_attn_bias(batch)
        for layer in self.layers:
            h = layer(h, attn_bias)
        if self.cfg.graph_pooling == "graph_token":
            logits = self.output_projection(h)
            return logits[:, 0, :]
        node_mask = batch["node_mask"]
        node_h = h[:, 1:, :] * node_mask.unsqueeze(-1).to(h.dtype)
        if self.cfg.graph_pooling == "sum":
            graph_repr = node_h.sum(dim=1)
        elif self.cfg.graph_pooling == "mean":
            denom = node_mask.sum(dim=1, keepdim=True).clamp(min=1).to(h.dtype)
            graph_repr = node_h.sum(dim=1) / denom
        else:
            raise ValueError(f"Unknown graph_pooling={self.cfg.graph_pooling!r}")
        return self.output_projection(graph_repr)


# -----------------------------------------------------------------------------
# Graphormer data: cache load + (fallback) recompute from PyG ZINC.
# Re-implements the notebook's preprocessing exactly for cache compatibility.
# -----------------------------------------------------------------------------

def _graphormer_convert_to_single_emb_1d(x):
    return x.long() + 1


def _graphormer_edge_lookup(edge_index, edge_attr):
    lookup: Dict[Tuple[int, int], int] = {}
    ei = edge_index.cpu().tolist()
    ea = edge_attr.view(edge_attr.size(0), -1)[:, 0].cpu().tolist()
    for u, v, e in zip(ei[0], ei[1], ea):
        lookup[(int(u), int(v))] = int(e)
    return lookup


def _graphormer_preprocess_one(data, multi_hop_max_dist: int = 5):
    from collections import deque

    n = int(data.num_nodes)
    x_raw = data.x.view(n, -1)[:, 0].long().cpu()
    x = _graphormer_convert_to_single_emb_1d(x_raw)
    y = data.y.view(-1).float().cpu()
    edge_index = data.edge_index.long().cpu()
    edge_attr = (data.edge_attr.long().cpu()
                 if getattr(data, "edge_attr", None) is not None
                 else torch.zeros(edge_index.size(1), 1, dtype=torch.long))

    adj: List[List[Tuple[int, int]]] = [[] for _ in range(n)]
    lookup = _graphormer_edge_lookup(edge_index, edge_attr)
    for (u, v), e in lookup.items():
        adj[u].append((v, int(e) + 2))

    degree = torch.tensor([len(adj[i]) for i in range(n)], dtype=torch.long)
    spatial_pos = torch.zeros(n, n, dtype=torch.long)
    edge_input = torch.zeros(n, n, multi_hop_max_dist, 1, dtype=torch.long)
    attn_bias = torch.zeros(n + 1, n + 1, dtype=torch.float)

    for src in range(n):
        dist = [-1] * n
        parent = [-1] * n
        parent_edge = [-1] * n
        dist[src] = 0
        q = deque([src])
        while q:
            u = q.popleft()
            for v, e in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    parent_edge[v] = e
                    q.append(v)
        for dst in range(n):
            d = dist[dst]
            if d < 0:
                continue
            spatial_pos[src, dst] = d
            if 0 < d <= multi_hop_max_dist:
                rev: List[int] = []
                cur = dst
                while cur != src and cur != -1:
                    rev.append(int(parent_edge[cur]))
                    cur = parent[cur]
                path = list(reversed(rev))
                for k, e in enumerate(path[:multi_hop_max_dist]):
                    edge_input[src, dst, k, 0] = e

    return {
        "x": x.view(n, 1),
        "y": y,
        "degree": degree,
        "spatial_pos": spatial_pos,
        "edge_input": edge_input,
        "attn_bias": attn_bias,
        "num_nodes": n,
    }


def _graphormer_load_or_build_split(split: str, data_root: Path,
                                    cache_dir: Path, cfg: GraphormerConfig):
    cache_file = (cache_dir
                  / f"zinc_subset_graphormer_{split}_mh{cfg.multi_hop_max_dist}.pt")
    if cache_file.exists():
        print(f"[graphormer:data] Loading cache: {cache_file}")
        return safe_torch_load(cache_file)
    print(f"[graphormer:data] Cache miss; building {split} from PyG ZINC")
    safe_mkdir(cache_dir)
    safe_mkdir(data_root)
    ds = load_pyg_zinc_dataset(data_root, split)
    records = [_graphormer_preprocess_one(d, multi_hop_max_dist=cfg.multi_hop_max_dist)
               for d in ds]
    torch.save(records, cache_file)
    print(f"[graphormer:data] Wrote cache: {cache_file}")
    return records


def _graphormer_collate(records, cfg: GraphormerConfig):
    bsz = len(records)
    max_n = max(int(r["num_nodes"]) for r in records)
    max_dist = cfg.multi_hop_max_dist

    x = torch.zeros(bsz, max_n, 1, dtype=torch.long)
    in_degree = torch.zeros(bsz, max_n, dtype=torch.long)
    out_degree = torch.zeros(bsz, max_n, dtype=torch.long)
    spatial_pos = torch.zeros(bsz, max_n, max_n, dtype=torch.long)
    edge_input = torch.zeros(bsz, max_n, max_n, max_dist, 1, dtype=torch.long)
    attn_bias = torch.full((bsz, max_n + 1, max_n + 1), float("-inf"),
                           dtype=torch.float)
    node_mask = torch.zeros(bsz, max_n, dtype=torch.bool)
    y = torch.zeros(bsz, cfg.num_classes, dtype=torch.float)

    for i, r in enumerate(records):
        n = int(r["num_nodes"])
        xi = torch.as_tensor(r["x"], dtype=torch.long) + 1
        x[i, :n, :] = xi
        deg = torch.as_tensor(r["degree"], dtype=torch.long) + 1
        in_degree[i, :n] = deg
        out_degree[i, :n] = deg
        sp_raw = torch.as_tensor(r["spatial_pos"], dtype=torch.long)
        sp = sp_raw + 1
        spatial_pos[i, :n, :n] = sp
        ei = torch.as_tensor(r["edge_input"], dtype=torch.long) + 1
        edge_input[i, :n, :n, :, :] = ei
        ab = torch.as_tensor(r["attn_bias"], dtype=torch.float).clone()
        ab[1:, 1:][sp_raw >= cfg.spatial_pos_max] = float("-inf")
        attn_bias[i, : n + 1, : n + 1] = ab
        if n + 1 < max_n + 1:
            attn_bias[i, n + 1 :, : n + 1] = 0.0
        node_mask[i, :n] = True
        yy = torch.as_tensor(r["y"], dtype=torch.float).view(-1)
        y[i, : min(cfg.num_classes, yy.numel())] = yy[: cfg.num_classes]

    return {
        "x": x, "in_degree": in_degree, "out_degree": out_degree,
        "spatial_pos": spatial_pos, "edge_input": edge_input,
        "attn_bias": attn_bias, "node_mask": node_mask, "y": y,
    }


class _GraphormerRecordDataset:
    def __init__(self, records):
        self.records = records

    def __len__(self):
        return len(self.records)

    def __getitem__(self, i):
        return self.records[i]


class GraphormerBatchAdapter:
    """Wraps a Graphormer dict batch with PyG-Batch-like methods so the metric
    loop doesn't need to special-case clone/to/num_graphs/num_nodes/num_edges.

    Edge count is computed lazily from spatial_pos (a value of 2 means
    "adjacent at distance 1"; collator shifts SPD by +1). We use this only for
    logging; metrics don't depend on it.
    """

    __slots__ = ("d", "_atom_ids_pre_shift")

    def __init__(self, d: Dict[str, torch.Tensor]):
        self.d = d
        self._atom_ids_pre_shift = None

    def __getitem__(self, key):
        return self.d[key]

    def __contains__(self, key):
        return key in self.d

    def keys(self):
        return self.d.keys()

    def clone(self):
        new_d = {k: (v.clone() if torch.is_tensor(v) else v)
                 for k, v in self.d.items()}
        return GraphormerBatchAdapter(new_d)

    def to(self, device, non_blocking: bool = True):
        new_d = {k: (v.to(device, non_blocking=non_blocking)
                     if torch.is_tensor(v) else v)
                 for k, v in self.d.items()}
        return GraphormerBatchAdapter(new_d)

    @property
    def num_graphs(self) -> int:
        return int(self.d["x"].size(0))

    @property
    def num_nodes(self) -> int:
        return int(self.d["node_mask"].sum().item())

    @property
    def num_edges(self) -> int:
        # SPD == 2 after collator's +1 shift corresponds to graph-adjacent pairs
        # (raw SPD == 1).
        sp = self.d["spatial_pos"]
        return int((sp == 2).sum().item())

    @property
    def counts(self) -> torch.Tensor:
        return self.d["node_mask"].sum(dim=1).long()


def configure_graphormer(spec: ModelSpec, run_cfg: RunConfig,
                         device: torch.device):
    """Build a Graphormer model, restore the trained checkpoint's config,
    construct train/val/test loaders from the cached records, return
    (graphormer_cfg, loaders, model) mirroring configure_graphgym's contract.
    """
    from torch.utils.data import DataLoader

    ckpt_path = spec.ckpt_path
    if not ckpt_path or not Path(ckpt_path).exists():
        raise FileNotFoundError(
            f"Graphormer checkpoint not found: {ckpt_path}. "
            f"Update --graphormer-ckpt or rerun training."
        )
    raw = safe_torch_load(ckpt_path, map_location="cpu")
    cfg_dict = raw.get("graphormer_config", {})
    gcfg = GraphormerConfig(**{k: v for k, v in cfg_dict.items()
                               if k in GraphormerConfig.__dataclass_fields__})

    model = StandaloneGraphormer(gcfg).to(device).eval()

    cache_dir = Path(getattr(run_cfg, "_graphormer_cache_dir",
                             GRAPHORMER_CACHE_DIR))
    data_root = Path(spec.data_dir)
    safe_mkdir(cache_dir)
    safe_mkdir(data_root)

    collate = lambda recs: _graphormer_collate(recs, gcfg)
    splits = {}
    for split in ("train", "val", "test"):
        recs = _graphormer_load_or_build_split(split, data_root, cache_dir, gcfg)
        ds = _GraphormerRecordDataset(recs)
        loader = DataLoader(
            ds, batch_size=run_cfg.batch_size, shuffle=False,
            collate_fn=collate, num_workers=run_cfg.num_workers,
            pin_memory=(device.type == "cuda"),
        )
        splits[split] = _AdapterLoader(loader, GraphormerBatchAdapter)
    loaders = [splits["train"], splits["val"], splits["test"]]

    print(f"[graphormer] Model built: layers={gcfg.num_layers}, "
          f"heads={gcfg.num_heads}, hidden={gcfg.hidden_dim}")
    return gcfg, loaders, model


# =============================================================================
# CSA (Static-Anchor Symmetric): constants, batch dataclass, model classes,
# preprocessing, cache, batch adapter.
# =============================================================================


CSA_NUM_ATOM_TYPES = 28
CSA_NUM_BOND_TYPES = 3
CSA_D_MODEL = 64
CSA_N_HEADS = 8
CSA_N_LAYERS = 10
CSA_D_HEAD = CSA_D_MODEL // CSA_N_HEADS
CSA_K_WALK = 12
CSA_D_MAX_SPD = 5
CSA_P_SYM = (CSA_D_MAX_SPD + 1) + CSA_K_WALK + CSA_NUM_BOND_TYPES
CSA_P_PAIR = CSA_P_SYM
CSA_BIAS_INPUT_DIM = CSA_P_SYM
CSA_VALUE_INPUT_DIM = CSA_P_SYM
CSA_FFN_MULT = 2
CSA_ATTN_DROPOUT = 0.2
CSA_RESID_DROPOUT = 0.0


@dataclass
class StaticAnchorBatch:
    x: torch.Tensor
    edge_index: torch.Tensor
    edge_attr: torch.Tensor
    y: torch.Tensor
    rwse: torch.Tensor
    pair_xi: torch.Tensor
    degree: torch.Tensor
    batch_index: torch.Tensor
    node_pos: torch.Tensor
    node_mask: torch.Tensor
    pair_mask: torch.Tensor
    num_graphs: int
    max_nodes: int

    def to(self, device, non_blocking: bool = True):
        fields = {}
        for name, value in self.__dict__.items():
            if torch.is_tensor(value):
                fields[name] = value.to(device, non_blocking=non_blocking)
            else:
                fields[name] = value
        return StaticAnchorBatch(**fields)

    def clone(self):
        fields = {}
        for name, value in self.__dict__.items():
            fields[name] = value.clone() if torch.is_tensor(value) else value
        return StaticAnchorBatch(**fields)


def _csa_flat_to_dense(x, batch: StaticAnchorBatch):
    out = x.new_zeros((batch.num_graphs, batch.max_nodes, x.size(-1)))
    out[batch.batch_index, batch.node_pos] = x
    return out


def _csa_dense_to_flat(x_dense, batch: StaticAnchorBatch):
    return x_dense[batch.node_mask]


class StaticAnchorLayer(nn.Module):
    """One CSA transformer layer. Numerically identical to the notebook's
    StaticAnchorLayer; lifted here so the AttentionProbeManager can identify
    it by class name and capture pre-softmax logits.
    """

    def __init__(self, use_symmetric_value_add: bool = True):
        super().__init__()
        self.use_symmetric_value_add = use_symmetric_value_add
        self.num_heads = CSA_N_HEADS  # used by AttentionProbeManager
        self.pre_attn_bn = nn.BatchNorm1d(CSA_D_MODEL)
        self.pre_ffn_bn = nn.BatchNorm1d(CSA_D_MODEL)

        self.q_proj = nn.Linear(CSA_D_MODEL, CSA_D_MODEL)
        self.k_proj = nn.Linear(CSA_D_MODEL, CSA_D_MODEL)
        self.v_proj = nn.Linear(CSA_D_MODEL, CSA_D_MODEL)
        self.o_proj = nn.Linear(CSA_D_MODEL, CSA_D_MODEL)

        self.bias_weight = nn.Parameter(torch.empty(CSA_N_HEADS, CSA_BIAS_INPUT_DIM))
        nn.init.normal_(self.bias_weight, mean=0.0, std=0.02)
        if use_symmetric_value_add:
            self.value_weight = nn.Parameter(
                torch.empty(CSA_N_HEADS, CSA_D_HEAD, CSA_VALUE_INPUT_DIM)
            )
            nn.init.normal_(self.value_weight, mean=0.0, std=0.02)
        else:
            self.register_parameter("value_weight", None)

        self.bias_gate = nn.Parameter(torch.ones(CSA_N_HEADS))
        self.theta1 = nn.Parameter(torch.ones(CSA_D_MODEL))
        self.theta2 = nn.Parameter(torch.zeros(CSA_D_MODEL))

        self.attn_dropout = nn.Dropout(CSA_ATTN_DROPOUT)
        self.resid_dropout = nn.Dropout(CSA_RESID_DROPOUT)
        self.ffn = nn.Sequential(
            nn.Linear(CSA_D_MODEL, CSA_FFN_MULT * CSA_D_MODEL),
            nn.GELU(),
            nn.Dropout(CSA_RESID_DROPOUT),
            nn.Linear(CSA_FFN_MULT * CSA_D_MODEL, CSA_D_MODEL),
            nn.Dropout(CSA_RESID_DROPOUT),
        )

    def forward(self, h_flat, batch: StaticAnchorBatch):
        h_in_flat = h_flat
        h_norm_flat = self.pre_attn_bn(h_flat)
        h_norm = _csa_flat_to_dense(h_norm_flat, batch)

        B, N, _ = h_norm.shape
        q = self.q_proj(h_norm).view(B, N, CSA_N_HEADS, CSA_D_HEAD).transpose(1, 2)
        k = self.k_proj(h_norm).view(B, N, CSA_N_HEADS, CSA_D_HEAD).transpose(1, 2)
        v = self.v_proj(h_norm).view(B, N, CSA_N_HEADS, CSA_D_HEAD).transpose(1, 2)

        logits = torch.einsum("bhid,bhjd->bhij", q, k) * (CSA_D_HEAD ** -0.5)
        xi_sym = batch.pair_xi.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
        bias = torch.einsum("bijp,hp->bhij", xi_sym, self.bias_weight)
        bias = bias * self.bias_gate.view(1, CSA_N_HEADS, 1, 1)
        logits = logits + bias

        key_mask = batch.node_mask[:, None, None, :]
        logits = logits.masked_fill(~key_mask, float("-inf"))

        alpha = torch.softmax(logits, dim=-1)
        alpha = torch.where(torch.isfinite(alpha), alpha, torch.zeros_like(alpha))
        alpha = self.attn_dropout(alpha)

        out = torch.matmul(alpha, v)
        if self.use_symmetric_value_add:
            value_pair = torch.einsum("bijp,hdp->bhijd", xi_sym, self.value_weight)
            out = out + torch.einsum("bhij,bhijd->bhid", alpha, value_pair)

        out = out.transpose(1, 2).contiguous().view(B, N, CSA_D_MODEL)
        out = self.o_proj(out)
        out = out.masked_fill(~batch.node_mask.unsqueeze(-1), 0.0)
        out_flat = _csa_dense_to_flat(out, batch)

        degree_log = torch.log1p(batch.degree).view(-1, 1)
        scaled = (out_flat * self.theta1.view(1, -1)
                  + degree_log * out_flat * self.theta2.view(1, -1))
        h_half = h_in_flat + self.resid_dropout(scaled)
        h_ffn = self.ffn(self.pre_ffn_bn(h_half))
        return h_half + h_ffn


class StaticAnchorZincModel(nn.Module):
    def __init__(self, use_symmetric_value_add: bool = True):
        super().__init__()
        self.use_symmetric_value_add = use_symmetric_value_add
        self.atom_emb = nn.Embedding(CSA_NUM_ATOM_TYPES, CSA_D_MODEL)
        self.bond_emb = nn.Embedding(CSA_NUM_BOND_TYPES, CSA_D_MODEL)
        self.rwse_proj = nn.Linear(CSA_K_WALK, CSA_D_MODEL)
        self.layers = nn.ModuleList([
            StaticAnchorLayer(use_symmetric_value_add=use_symmetric_value_add)
            for _ in range(CSA_N_LAYERS)
        ])
        self.final_bn = nn.BatchNorm1d(CSA_D_MODEL)
        self.readout = nn.Sequential(
            nn.Linear(CSA_D_MODEL, 2 * CSA_D_MODEL),
            nn.GELU(),
            nn.Linear(2 * CSA_D_MODEL, 1),
        )

    def forward(self, batch: StaticAnchorBatch):
        h = self.atom_emb(batch.x)
        edge_msg = self.bond_emb(batch.edge_attr)
        bond_sum = h.new_zeros(h.shape)
        if batch.edge_index.numel() > 0:
            dst = batch.edge_index[1]
            bond_sum.index_add_(0, dst, edge_msg)
        h = h + bond_sum + self.rwse_proj(batch.rwse)
        for layer in self.layers:
            h = layer(h, batch)
        h = self.final_bn(h)
        pooled = h.new_zeros((batch.num_graphs, CSA_D_MODEL))
        pooled.index_add_(0, batch.batch_index, h)
        return self.readout(pooled).view(-1)


# -----------------------------------------------------------------------------
# CSA data: cache load + (fallback) recompute from PyG ZINC.
# -----------------------------------------------------------------------------


def _csa_normalize_edge_attr(edge_attr):
    ea = edge_attr.view(-1).long()
    if ea.numel() == 0:
        return ea
    mn, mx = int(ea.min().item()), int(ea.max().item())
    if mn >= 1 and mx <= CSA_NUM_BOND_TYPES:
        ea = ea - 1
    return ea


def _csa_bfs_spd_classes(adj_bool, dmax: int):
    from collections import deque
    n = int(adj_bool.size(0))
    dist = torch.full((n, n), dmax, dtype=torch.long)
    neighbors = [torch.nonzero(adj_bool[i], as_tuple=False).view(-1).tolist()
                 for i in range(n)]
    for s in range(n):
        dist[s, s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            du = int(dist[s, u].item())
            if du >= dmax:
                continue
            for v in neighbors[u]:
                if dist[s, v] == dmax and v != s:
                    dist[s, v] = min(du + 1, dmax)
                    q.append(v)
    return dist


def _csa_compute_pair_features(data):
    x = data.x.view(-1).long()
    edge_index = data.edge_index.long()
    edge_attr = _csa_normalize_edge_attr(data.edge_attr)

    n = int(data.num_nodes)
    A = torch.zeros((n, n), dtype=torch.float32)
    if edge_index.numel() > 0:
        src, dst = edge_index
        A[src, dst] = 1.0
    A = torch.maximum(A, A.t())
    A.fill_diagonal_(0.0)

    degree = A.sum(dim=1)
    W = torch.zeros_like(A)
    nz = degree > 0
    W[nz] = A[nz] / degree[nz].unsqueeze(1)

    powers = []
    P = W.clone()
    for _ in range(CSA_K_WALK):
        powers.append(P.clone())
        P = P @ W

    rwse = torch.stack([Pk.diagonal() for Pk in powers], dim=-1).float()
    walk_sum = torch.stack([Pk + Pk.t() for Pk in powers], dim=-1).float()
    spd_cls = _csa_bfs_spd_classes(A > 0, CSA_D_MAX_SPD)
    spd_oh = F.one_hot(spd_cls.clamp(max=CSA_D_MAX_SPD),
                       num_classes=CSA_D_MAX_SPD + 1).float()
    bond_oh = torch.zeros((n, n, CSA_NUM_BOND_TYPES), dtype=torch.float32)
    if edge_index.numel() > 0:
        src, dst = edge_index
        bond_oh[src, dst, edge_attr] = 1.0
    pair_xi = torch.cat([spd_oh, walk_sum, bond_oh], dim=-1).float()

    return {
        "x": x.cpu(),
        "edge_index": edge_index.cpu(),
        "edge_attr": edge_attr.cpu(),
        "y": data.y.view(1).float().cpu(),
        "rwse": rwse.cpu(),
        "pair_xi": pair_xi.cpu(),
        "degree": degree.float().cpu(),
    }


def _csa_load_or_build_splits(cache_path: Path, data_dir: Path):
    if cache_path.exists():
        print(f"[csa:data] Loading cache: {cache_path}")
        d = safe_torch_load(cache_path)
        return d["splits"], d["meta"]
    print(f"[csa:data] Cache miss; building from PyG ZINC")
    safe_mkdir(cache_path.parent)
    root = data_dir / "ZINC"
    safe_mkdir(root)
    train = load_pyg_zinc_dataset(root, "train")
    val = load_pyg_zinc_dataset(root, "val")
    test = load_pyg_zinc_dataset(root, "test")
    splits = {
        "train": [_csa_compute_pair_features(d) for d in train],
        "val":   [_csa_compute_pair_features(d) for d in val],
        "test":  [_csa_compute_pair_features(d) for d in test],
    }
    meta = {"num_atom_types": CSA_NUM_ATOM_TYPES, "num_bond_types": CSA_NUM_BOND_TYPES,
            "k_walk": CSA_K_WALK, "d_max_spd": CSA_D_MAX_SPD,
            "p_sym": CSA_P_SYM, "p_pair": CSA_P_PAIR,
            "sizes": {k: len(v) for k, v in splits.items()}}
    torch.save({"splits": splits, "meta": meta}, cache_path)
    print(f"[csa:data] Wrote cache: {cache_path}")
    return splits, meta


def _csa_collate(graphs):
    batch_size = len(graphs)
    counts = [int(g["x"].numel()) for g in graphs]
    max_nodes = max(counts)
    total_nodes = sum(counts)

    xs, edge_indices, edge_attrs, ys, rwse_list, degree_list = [], [], [], [], [], []
    batch_index = torch.empty(total_nodes, dtype=torch.long)
    node_pos = torch.empty(total_nodes, dtype=torch.long)
    pair_xi = torch.zeros((batch_size, max_nodes, max_nodes, CSA_P_PAIR),
                          dtype=torch.float32)
    node_mask = torch.zeros((batch_size, max_nodes), dtype=torch.bool)
    pair_mask = torch.zeros((batch_size, max_nodes, max_nodes), dtype=torch.bool)

    node_offset = 0
    for b, g in enumerate(graphs):
        n = counts[b]
        xs.append(g["x"])
        ys.append(g["y"])
        rwse_list.append(g["rwse"])
        degree_list.append(g["degree"])
        ei = g["edge_index"] + node_offset
        edge_indices.append(ei)
        edge_attrs.append(g["edge_attr"])
        batch_index[node_offset:node_offset + n] = b
        node_pos[node_offset:node_offset + n] = torch.arange(n, dtype=torch.long)
        pair_xi[b, :n, :n] = g["pair_xi"]
        node_mask[b, :n] = True
        pair_mask[b, :n, :n] = True
        node_offset += n

    edge_index = (torch.cat(edge_indices, dim=1) if edge_indices
                  else torch.empty((2, 0), dtype=torch.long))
    edge_attr = (torch.cat(edge_attrs, dim=0) if edge_attrs
                 else torch.empty((0,), dtype=torch.long))
    return StaticAnchorBatch(
        x=torch.cat(xs, dim=0).long(),
        edge_index=edge_index.long(),
        edge_attr=edge_attr.long(),
        y=torch.cat(ys, dim=0).float(),
        rwse=torch.cat(rwse_list, dim=0).float(),
        pair_xi=pair_xi.float(),
        degree=torch.cat(degree_list, dim=0).float(),
        batch_index=batch_index,
        node_pos=node_pos,
        node_mask=node_mask,
        pair_mask=pair_mask,
        num_graphs=batch_size,
        max_nodes=max_nodes,
    )


class _CSATensorDataset:
    def __init__(self, graphs):
        self.graphs = graphs

    def __len__(self):
        return len(self.graphs)

    def __getitem__(self, i):
        return self.graphs[i]


class CSABatchAdapter:
    """Thin wrapper around StaticAnchorBatch so the metric loop can call
    .clone(), .to(device), and read num_graphs / num_nodes / num_edges
    uniformly with PyG batches.
    """

    __slots__ = ("b",)

    def __init__(self, b: StaticAnchorBatch):
        self.b = b

    def clone(self):
        return CSABatchAdapter(self.b.clone())

    def to(self, device, non_blocking: bool = True):
        return CSABatchAdapter(self.b.to(device, non_blocking=non_blocking))

    @property
    def num_graphs(self) -> int:
        return int(self.b.num_graphs)

    @property
    def num_nodes(self) -> int:
        return int(self.b.x.numel())

    @property
    def num_edges(self) -> int:
        return int(self.b.edge_index.size(1))

    @property
    def counts(self) -> torch.Tensor:
        return self.b.node_mask.sum(dim=1).long()


def configure_csa(spec: ModelSpec, run_cfg: RunConfig, device: torch.device):
    from torch.utils.data import DataLoader

    ckpt_path = spec.ckpt_path
    if not ckpt_path or not Path(ckpt_path).exists():
        raise FileNotFoundError(
            f"CSA checkpoint not found: {ckpt_path}. "
            f"Update --csa-ckpt or rerun training."
        )
    raw = safe_torch_load(ckpt_path, map_location="cpu")
    cfg_dict = raw.get("config", {}) or {}
    use_sva = bool(cfg_dict.get("symmetric_value_add", True))

    model = StaticAnchorZincModel(use_symmetric_value_add=use_sva).to(device).eval()

    cache_path = Path(getattr(run_cfg, "_csa_cache_path", CSA_CACHE_PATH))
    data_dir = Path(spec.data_dir)
    splits, _meta = _csa_load_or_build_splits(cache_path, data_dir)

    loaders = []
    for split in ("train", "val", "test"):
        ds = _CSATensorDataset(splits[split])
        loader = DataLoader(
            ds, batch_size=run_cfg.batch_size, shuffle=False,
            collate_fn=_csa_collate, num_workers=run_cfg.num_workers,
            pin_memory=(device.type == "cuda"),
        )
        loaders.append(_AdapterLoader(loader, CSABatchAdapter))

    print(f"[csa] Model built: layers={CSA_N_LAYERS}, heads={CSA_N_HEADS}, "
          f"hidden={CSA_D_MODEL}, value_add={use_sva}")
    return None, loaders, model


# =============================================================================
# v19 (LatentPairMemory.ValueActive): self-contained model + preprocessing.
# =============================================================================


V19_NUM_ATOM_TYPES = 28
V19_NUM_BOND_TYPES = 3
V19_D_MODEL = 64
V19_N_HEADS = 8
V19_N_LAYERS = 10
V19_D_HEAD = V19_D_MODEL // V19_N_HEADS
V19_K_WALK = 12
V19_D_MAX_SPD = 5
V19_RING_MIN_SIZE = 3
V19_RING_MAX_SIZE = 8
V19_P_RING_SIZES = V19_RING_MAX_SIZE - V19_RING_MIN_SIZE + 1
V19_P_RING_PAIR = 2 * V19_P_RING_SIZES
V19_P_SYM = (V19_D_MAX_SPD + 1) + V19_K_WALK + V19_NUM_BOND_TYPES
V19_P_PAIR = V19_P_RING_PAIR + V19_P_SYM
V19_P_LATENT_PAIR = 32
V19_BIAS_INPUT_DIM = V19_P_PAIR + V19_P_LATENT_PAIR
V19_VALUE_INPUT_DIM = V19_P_PAIR + V19_P_LATENT_PAIR
V19_DYNAMIC_GATE_INIT = 5e-2
V19_PAIR_UPDATE_RANK = 16
V19_PAIR_UPDATE_SCALE_INIT = 5e-2
V19_PAIR_OUT_INIT_STD = 1e-3
V19_PAIR_WRITE_GATE_INIT = 0.7
V19_RMS_NORM_EPS = 1e-6
V19_FFN_MULT = 2
V19_ATTN_DROPOUT = 0.2
V19_RESID_DROPOUT = 0.0


def _v19_logit_from_prob(p: float) -> float:
    p = min(max(float(p), 1e-6), 1.0 - 1e-6)
    return math.log(p / (1.0 - p))


def _v19_softplus_inverse(x: float) -> float:
    return math.log(math.expm1(float(x)))


def _v19_normalize_edge_attr(edge_attr):
    ea = edge_attr.view(-1).long()
    if ea.numel() == 0:
        return ea
    mn, mx = int(ea.min().item()), int(ea.max().item())
    if mn >= 1 and mx <= V19_NUM_BOND_TYPES:
        ea = ea - 1
    if int(ea.min().item()) < 0 or int(ea.max().item()) >= V19_NUM_BOND_TYPES:
        raise ValueError(
            f"v19 expected bond types 0..{V19_NUM_BOND_TYPES - 1} or "
            f"1..{V19_NUM_BOND_TYPES}; got min={int(ea.min())}, max={int(ea.max())}."
        )
    return ea


def _v19_bfs_spd_classes(adj_bool, dmax: int):
    from collections import deque

    n = int(adj_bool.size(0))
    dist = torch.full((n, n), dmax, dtype=torch.long)
    neighbors = [
        torch.nonzero(adj_bool[i], as_tuple=False).view(-1).tolist()
        for i in range(n)
    ]
    for s in range(n):
        dist[s, s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            du = int(dist[s, u].item())
            if du >= dmax:
                continue
            for v in neighbors[u]:
                if dist[s, v] == dmax and v != s:
                    dist[s, v] = min(du + 1, dmax)
                    q.append(v)
    return dist


def _v19_compute_ring_pair_features(adj_bool,
                                    min_size: int = V19_RING_MIN_SIZE,
                                    max_size: int = V19_RING_MAX_SIZE):
    n = int(adj_bool.size(0))
    num_sizes = max_size - min_size + 1
    same_ring = torch.zeros((n, n, num_sizes), dtype=torch.float32)
    edge_in_ring = torch.zeros((n, n, num_sizes), dtype=torch.float32)
    neighbors = [
        torch.nonzero(adj_bool[i], as_tuple=False).view(-1).tolist()
        for i in range(n)
    ]
    seen_cycles = set()

    def is_chordless(path):
        m = len(path)
        if len(set(path)) != m:
            return False
        for a in range(m):
            u = path[a]
            for b in range(a + 1, m):
                if b == a + 1 or (a == 0 and b == m - 1):
                    continue
                if bool(adj_bool[u, path[b]]):
                    return False
        return True

    def mark_cycle(path):
        m = len(path)
        if m < min_size or m > max_size or not is_chordless(path):
            return
        edge_key = []
        for i in range(m):
            u, v = path[i], path[(i + 1) % m]
            edge_key.append((u, v) if u < v else (v, u))
        key = tuple(sorted(edge_key))
        if key in seen_cycles:
            return
        seen_cycles.add(key)
        c = m - min_size
        for u in path:
            for v in path:
                same_ring[u, v, c] = 1.0
        for i in range(m):
            u, v = path[i], path[(i + 1) % m]
            edge_in_ring[u, v, c] = 1.0
            edge_in_ring[v, u, c] = 1.0

    def dfs(start, current, path, visited):
        if len(path) > max_size:
            return
        for nxt in neighbors[current]:
            if nxt == start:
                mark_cycle(path)
            elif nxt > start and nxt not in visited and len(path) < max_size:
                visited.add(nxt)
                path.append(nxt)
                dfs(start, nxt, path, visited)
                path.pop()
                visited.remove(nxt)

    for start in range(n):
        dfs(start, start, [start], {start})
    return torch.cat([same_ring, edge_in_ring], dim=-1)


def _v19_compute_features(data) -> Dict[str, torch.Tensor]:
    x = data.x.view(-1).long()
    if int(x.min()) < 0 or int(x.max()) >= V19_NUM_ATOM_TYPES:
        raise ValueError(
            f"v19 atom type out of expected 0..{V19_NUM_ATOM_TYPES - 1}: "
            f"max={int(x.max())}"
        )
    edge_index = data.edge_index.long()
    edge_attr = _v19_normalize_edge_attr(data.edge_attr)
    n = int(data.num_nodes)
    A = torch.zeros((n, n), dtype=torch.float32)
    if edge_index.numel() > 0:
        src, dst = edge_index
        A[src, dst] = 1.0
    A = torch.maximum(A, A.t())
    A.fill_diagonal_(0.0)
    degree = A.sum(dim=1)
    W = torch.zeros_like(A)
    nz = degree > 0
    W[nz] = A[nz] / degree[nz].unsqueeze(1)
    powers = []
    P = W.clone()
    for _ in range(V19_K_WALK):
        powers.append(P.clone())
        P = P @ W
    rwse = torch.stack([Pk.diagonal() for Pk in powers], dim=-1).float()
    walk_sum = torch.stack([Pk + Pk.t() for Pk in powers], dim=-1).float()
    ring_pair = _v19_compute_ring_pair_features(A > 0)
    spd_cls = _v19_bfs_spd_classes(A > 0, V19_D_MAX_SPD)
    spd_oh = F.one_hot(
        spd_cls.clamp(max=V19_D_MAX_SPD),
        num_classes=V19_D_MAX_SPD + 1,
    ).float()
    bond_oh = torch.zeros((n, n, V19_NUM_BOND_TYPES), dtype=torch.float32)
    if edge_index.numel() > 0:
        src, dst = edge_index
        bond_oh[src, dst, edge_attr] = 1.0
        bond_oh[dst, src, edge_attr] = 1.0
    sym = torch.cat([spd_oh, walk_sum, bond_oh], dim=-1)
    pair_xi = torch.cat([ring_pair, sym], dim=-1).float()
    assert pair_xi.shape == (n, n, V19_P_PAIR)
    return {
        "x": x.cpu(),
        "edge_index": edge_index.cpu(),
        "edge_attr": edge_attr.cpu(),
        "y": data.y.view(1).float().cpu(),
        "rwse": rwse.cpu(),
        "pair_xi": pair_xi.cpu(),
        "degree": degree.float().cpu(),
    }


def _v19_cache_path(data_dir: Path) -> Path:
    return (data_dir / "variant_a_cache"
            / f"zinc_subset_ringpair_K{V19_K_WALK}_D{V19_D_MAX_SPD}_R"
              f"{V19_RING_MIN_SIZE}-{V19_RING_MAX_SIZE}_v1.pt")


def _v19_load_or_build_splits(cache_path: Path, data_dir: Path):
    if cache_path.exists():
        print(f"[v19:data] Loading cache: {cache_path}")
        bundle = safe_torch_load(cache_path, map_location="cpu")
        return bundle["splits"], bundle.get("meta", {})
    print(f"[v19:data] Cache miss; building ZINC pair features at {cache_path}")
    safe_mkdir(cache_path.parent)
    safe_mkdir(data_dir)
    raw = {
        "train": load_pyg_zinc_dataset(data_dir, "train"),
        "val": load_pyg_zinc_dataset(data_dir, "val"),
        "test": load_pyg_zinc_dataset(data_dir, "test"),
    }
    splits = {}
    t0 = time.time()
    for split_name, ds in raw.items():
        out = []
        for i, graph in enumerate(ds, start=1):
            out.append(_v19_compute_features(graph))
            if i % 500 == 0 or i == len(ds):
                print(f"[v19:data] {split_name}: {i:>5d}/{len(ds)} "
                      f"({time.time() - t0:.1f}s)")
        splits[split_name] = out
    meta = {
        "dataset": "PyG-ZINC/subset",
        "num_atom_types": V19_NUM_ATOM_TYPES,
        "num_bond_types": V19_NUM_BOND_TYPES,
        "K_walk": V19_K_WALK,
        "D_max_spd": V19_D_MAX_SPD,
        "ring_min_size": V19_RING_MIN_SIZE,
        "ring_max_size": V19_RING_MAX_SIZE,
        "p_ring_pair": V19_P_RING_PAIR,
        "p_sym": V19_P_SYM,
        "p_pair": V19_P_PAIR,
        "created_time": time.asctime(),
    }
    torch.save({"splits": splits, "meta": meta}, cache_path)
    return splits, meta


class V19TensorGraphDataset:
    def __init__(self, graphs):
        self.graphs = graphs

    def __len__(self):
        return len(self.graphs)

    def __getitem__(self, i):
        return self.graphs[i]


@dataclass
class V19VariantABatch:
    x: torch.Tensor
    edge_index: torch.Tensor
    edge_attr: torch.Tensor
    y: torch.Tensor
    rwse: torch.Tensor
    pair_xi: torch.Tensor
    degree: torch.Tensor
    degree_log: torch.Tensor
    batch_index: torch.Tensor
    node_pos: torch.Tensor
    node_mask: torch.Tensor
    pair_mask: torch.Tensor
    num_graphs: int
    max_nodes: int

    def to(self, device, non_blocking: bool = True):
        fields = {}
        for name, value in self.__dict__.items():
            if torch.is_tensor(value):
                fields[name] = value.to(device, non_blocking=non_blocking)
            else:
                fields[name] = value
        return V19VariantABatch(**fields)

    def clone(self):
        fields = {
            name: (value.clone() if torch.is_tensor(value) else value)
            for name, value in self.__dict__.items()
        }
        return V19VariantABatch(**fields)


def _v19_collate(graphs) -> V19VariantABatch:
    batch_size = len(graphs)
    counts = [int(g["x"].numel()) for g in graphs]
    max_nodes = max(counts)
    total_nodes = sum(counts)
    xs, edge_indices, edge_attrs, ys, rwse_list, degree_list = [], [], [], [], [], []
    batch_index = torch.empty(total_nodes, dtype=torch.long)
    node_pos = torch.empty(total_nodes, dtype=torch.long)
    pair_xi = torch.zeros((batch_size, max_nodes, max_nodes, V19_P_PAIR),
                          dtype=torch.float32)
    node_mask = torch.zeros((batch_size, max_nodes), dtype=torch.bool)
    pair_mask = torch.zeros((batch_size, max_nodes, max_nodes), dtype=torch.bool)
    node_offset = 0
    for b, g in enumerate(graphs):
        n = counts[b]
        xs.append(g["x"])
        ys.append(g["y"])
        rwse_list.append(g["rwse"])
        degree_list.append(g["degree"])
        edge_indices.append(g["edge_index"] + node_offset)
        edge_attrs.append(g["edge_attr"])
        batch_index[node_offset:node_offset + n] = b
        node_pos[node_offset:node_offset + n] = torch.arange(n, dtype=torch.long)
        pair_xi[b, :n, :n] = g["pair_xi"]
        node_mask[b, :n] = True
        pair_mask[b, :n, :n] = True
        node_offset += n
    edge_index = (torch.cat(edge_indices, dim=1) if edge_indices
                  else torch.empty((2, 0), dtype=torch.long))
    edge_attr = (torch.cat(edge_attrs, dim=0) if edge_attrs
                 else torch.empty((0,), dtype=torch.long))
    degree = torch.cat(degree_list, dim=0).float()
    return V19VariantABatch(
        x=torch.cat(xs, dim=0).long(),
        edge_index=edge_index.long(),
        edge_attr=edge_attr.long(),
        y=torch.cat(ys, dim=0).float(),
        rwse=torch.cat(rwse_list, dim=0).float(),
        pair_xi=pair_xi.float(),
        degree=degree,
        degree_log=torch.log1p(degree),
        batch_index=batch_index,
        node_pos=node_pos,
        node_mask=node_mask,
        pair_mask=pair_mask,
        num_graphs=batch_size,
        max_nodes=max_nodes,
    )


def _v19_flat_to_dense(x, batch: V19VariantABatch):
    out = x.new_zeros((batch.num_graphs, batch.max_nodes, x.size(-1)))
    out[batch.batch_index, batch.node_pos] = x
    return out


def _v19_dense_to_flat(x_dense, batch: V19VariantABatch):
    return x_dense[batch.node_mask]


def _v19_mask_pair_state(pair_state, pair_mask):
    return pair_state.masked_fill(~pair_mask.unsqueeze(-1), 0.0)


class V19LastDimRMSNorm(nn.Module):
    def __init__(self, dim: int, eps: float = V19_RMS_NORM_EPS):
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(dim))

    def forward(self, x):
        x = x * torch.rsqrt(x.pow(2).mean(dim=-1, keepdim=True) + self.eps)
        return x * self.weight


class V19VariantALayer(nn.Module):
    def __init__(self, use_value_add: bool = True,
                 pair_update_rank: int = V19_PAIR_UPDATE_RANK):
        super().__init__()
        self.projection_mode = "normalized_latent_pair_memory"
        self.use_value_add = use_value_add
        self.pair_update_rank = int(pair_update_rank)
        if self.pair_update_rank <= 0:
            raise ValueError(f"pair_update_rank must be positive, got {self.pair_update_rank}")
        self.num_heads = V19_N_HEADS
        self.pre_attn_bn = nn.BatchNorm1d(V19_D_MODEL)
        self.pre_ffn_bn = nn.BatchNorm1d(V19_D_MODEL)
        self.q_proj = nn.Linear(V19_D_MODEL, V19_D_MODEL)
        self.k_proj = nn.Linear(V19_D_MODEL, V19_D_MODEL)
        self.v_proj = nn.Linear(V19_D_MODEL, V19_D_MODEL)
        self.o_proj = nn.Linear(V19_D_MODEL, V19_D_MODEL)
        self.bias_weight = nn.Parameter(torch.empty(V19_N_HEADS, V19_BIAS_INPUT_DIM))
        self.value_weight = nn.Parameter(
            torch.empty(V19_N_HEADS, V19_D_HEAD, V19_VALUE_INPUT_DIM)
        )
        self.dynamic_bias_logit = nn.Parameter(
            torch.full((1,), _v19_logit_from_prob(V19_DYNAMIC_GATE_INIT))
        )
        self.dynamic_value_logit = nn.Parameter(
            torch.full((1,), _v19_logit_from_prob(V19_DYNAMIC_GATE_INIT))
        )
        nn.init.normal_(self.bias_weight, mean=0.0, std=0.02)
        nn.init.normal_(self.value_weight, mean=0.0, std=0.02)
        self.bias_gate = nn.Parameter(torch.ones(V19_N_HEADS))
        self.theta1 = nn.Parameter(torch.ones(V19_D_MODEL))
        self.theta2 = nn.Parameter(torch.zeros(V19_D_MODEL))
        self.attn_dropout = nn.Dropout(V19_ATTN_DROPOUT)
        self.resid_dropout = nn.Dropout(V19_RESID_DROPOUT)
        self.ffn = nn.Sequential(
            nn.Linear(V19_D_MODEL, V19_FFN_MULT * V19_D_MODEL),
            nn.GELU(),
            nn.Dropout(V19_RESID_DROPOUT),
            nn.Linear(V19_FFN_MULT * V19_D_MODEL, V19_D_MODEL),
            nn.Dropout(V19_RESID_DROPOUT),
        )
        r = self.pair_update_rank
        self.pair_read_norm = V19LastDimRMSNorm(V19_P_LATENT_PAIR)
        self.pair_write_state_norm = V19LastDimRMSNorm(V19_P_LATENT_PAIR)
        self.pair_proposal_norm = V19LastDimRMSNorm(V19_P_LATENT_PAIR)
        self.h_pair_norm = V19LastDimRMSNorm(V19_D_MODEL)
        self.pair_u_proj = nn.Linear(V19_D_MODEL, r, bias=False)
        self.pair_v_proj = nn.Linear(V19_D_MODEL, r, bias=False)
        self.pair_u_norm = V19LastDimRMSNorm(r)
        self.pair_v_norm = V19LastDimRMSNorm(r)
        self.pair_out = nn.Linear(r * r, V19_P_LATENT_PAIR)
        self.pair_write_gate = nn.Linear(V19_P_LATENT_PAIR + V19_P_PAIR, 1)
        self.pair_update_log_scale = nn.Parameter(
            torch.full((1,), _v19_softplus_inverse(V19_PAIR_UPDATE_SCALE_INIT))
        )
        nn.init.normal_(self.pair_out.weight, mean=0.0, std=V19_PAIR_OUT_INIT_STD)
        nn.init.zeros_(self.pair_out.bias)
        nn.init.zeros_(self.pair_write_gate.weight)
        nn.init.constant_(self.pair_write_gate.bias,
                          _v19_logit_from_prob(V19_PAIR_WRITE_GATE_INIT))

    def dynamic_bias_gate(self):
        return torch.sigmoid(self.dynamic_bias_logit)

    def dynamic_value_gate(self):
        return torch.sigmoid(self.dynamic_value_logit)

    def pair_update_scale(self):
        return F.softplus(self.pair_update_log_scale)

    def latent_pair_read(self, z_pair, xi_pair, pair_mask):
        z_read = self.pair_read_norm(z_pair)
        return (
            xi_pair,
            z_read,
            self.dynamic_bias_gate() * z_read,
            self.dynamic_value_gate() * z_read,
        )

    def forward(self, h_flat, z_pair, batch: V19VariantABatch,
                collect_diag: bool = False):
        h_in_flat = h_flat
        h_norm_flat = self.pre_attn_bn(h_flat)
        h_norm = _v19_flat_to_dense(h_norm_flat, batch)
        B, N, _ = h_norm.shape
        q = self.q_proj(h_norm).view(B, N, V19_N_HEADS, V19_D_HEAD).transpose(1, 2)
        k = self.k_proj(h_norm).view(B, N, V19_N_HEADS, V19_D_HEAD).transpose(1, 2)
        v = self.v_proj(h_norm).view(B, N, V19_N_HEADS, V19_D_HEAD).transpose(1, 2)
        xi_pair, _z_read, bias_dynamic_pair, value_dynamic_pair = (
            self.latent_pair_read(z_pair, batch.pair_xi, batch.pair_mask)
        )
        logits_base = torch.matmul(q, k.transpose(-2, -1)) * (V19_D_HEAD ** -0.5)
        bias_in = torch.cat([xi_pair, bias_dynamic_pair], dim=-1)
        bias = torch.einsum("bijp,hp->bhij", bias_in, self.bias_weight)
        bias = bias * self.bias_gate.view(1, V19_N_HEADS, 1, 1)
        logits = (logits_base + bias).masked_fill(
            ~batch.node_mask[:, None, None, :], float("-inf")
        )
        alpha_clean = torch.softmax(logits, dim=-1)
        alpha_clean = torch.where(
            torch.isfinite(alpha_clean), alpha_clean, torch.zeros_like(alpha_clean)
        )
        alpha_drop = alpha_clean if not self.training else self.attn_dropout(alpha_clean)
        out_base_clean = torch.matmul(alpha_clean, v)
        out_base = out_base_clean if not self.training else torch.matmul(alpha_drop, v)
        out_clean = out_base_clean
        out = out_base
        if self.use_value_add:
            value_in = torch.cat([xi_pair, value_dynamic_pair], dim=-1)
            value_avg_clean = torch.einsum("bhij,bijp->bhip", alpha_clean, value_in)
            value_avg_drop = (
                value_avg_clean if not self.training
                else torch.einsum("bhij,bijp->bhip", alpha_drop, value_in)
            )
            value_contrib_clean = torch.einsum(
                "bhip,hdp->bhid", value_avg_clean, self.value_weight
            )
            value_contrib = (
                value_contrib_clean if not self.training
                else torch.einsum("bhip,hdp->bhid", value_avg_drop, self.value_weight)
            )
            out_clean = out_clean + value_contrib_clean
            out = out + value_contrib
        out_clean = out_clean.transpose(1, 2).contiguous().view(B, N, V19_D_MODEL)
        out_clean = self.o_proj(out_clean)
        out_clean = out_clean.masked_fill(~batch.node_mask.unsqueeze(-1), 0.0)
        out_clean_flat = _v19_dense_to_flat(out_clean, batch)
        out = out.transpose(1, 2).contiguous().view(B, N, V19_D_MODEL)
        out = self.o_proj(out)
        out = out.masked_fill(~batch.node_mask.unsqueeze(-1), 0.0)
        out_flat = _v19_dense_to_flat(out, batch)
        degree_log = batch.degree_log.view(-1, 1)
        scaled = (out_flat * self.theta1.view(1, -1)
                  + degree_log * out_flat * self.theta2.view(1, -1))
        h_half = h_in_flat + self.resid_dropout(scaled)
        scaled_clean = (out_clean_flat * self.theta1.view(1, -1)
                        + degree_log * out_clean_flat * self.theta2.view(1, -1))
        h_pair_post = h_in_flat + scaled_clean
        h_ffn = self.ffn(self.pre_ffn_bn(h_half))
        h_out = h_half + h_ffn
        h_post = _v19_flat_to_dense(h_pair_post, batch)
        h_post = self.h_pair_norm(h_post).masked_fill(
            ~batch.node_mask.unsqueeze(-1), 0.0
        )
        u = self.pair_u_norm(self.pair_u_proj(h_post))
        vv = self.pair_v_norm(self.pair_v_proj(h_post))
        outer = (u[:, :, None, :, None] * vv[:, None, :, None, :]).flatten(start_dim=-2)
        proposal = self.pair_out(outer) * (self.pair_update_rank ** -0.5)
        proposal = self.pair_proposal_norm(proposal)
        proposal = proposal.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
        z_gate_state = self.pair_write_state_norm(
            z_pair.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
        )
        z_gate_state = z_gate_state.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
        write_gate = torch.sigmoid(
            self.pair_write_gate(torch.cat([z_gate_state, xi_pair], dim=-1))
        )
        write_gate = write_gate.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
        z_next = z_pair + self.pair_update_scale() * write_gate * proposal
        return h_out, _v19_mask_pair_state(z_next, batch.pair_mask)


class V19VariantAZincModel(nn.Module):
    def __init__(self, use_value_add: bool = True,
                 pair_update_rank: int = V19_PAIR_UPDATE_RANK):
        super().__init__()
        self.projection_mode = "normalized_latent_pair_memory"
        self.use_value_add = use_value_add
        self.pair_update_rank = int(pair_update_rank)
        self.atom_emb = nn.Embedding(V19_NUM_ATOM_TYPES, V19_D_MODEL)
        self.bond_emb = nn.Embedding(V19_NUM_BOND_TYPES, V19_D_MODEL)
        self.rwse_proj = nn.Linear(V19_K_WALK, V19_D_MODEL)
        self.layers = nn.ModuleList([
            V19VariantALayer(use_value_add=use_value_add,
                             pair_update_rank=self.pair_update_rank)
            for _ in range(V19_N_LAYERS)
        ])
        self.final_bn = nn.BatchNorm1d(V19_D_MODEL)
        self.readout = nn.Sequential(
            nn.Linear(V19_D_MODEL, 2 * V19_D_MODEL),
            nn.GELU(),
            nn.Linear(2 * V19_D_MODEL, 1),
        )

    def forward(self, batch: V19VariantABatch, collect_diag: bool = False):
        h = self.atom_emb(batch.x)
        edge_msg = self.bond_emb(batch.edge_attr)
        bond_sum = h.new_zeros(h.shape)
        if batch.edge_index.numel() > 0:
            bond_sum.index_add_(0, batch.edge_index[1], edge_msg)
        h = h + bond_sum + self.rwse_proj(batch.rwse)
        z_pair = batch.pair_xi.new_zeros(batch.pair_xi.shape[:-1]
                                         + (V19_P_LATENT_PAIR,))
        for layer in self.layers:
            h, z_pair = layer(h, z_pair, batch, collect_diag=collect_diag)
        h = self.final_bn(h)
        pooled = h.new_zeros((batch.num_graphs, V19_D_MODEL))
        pooled.index_add_(0, batch.batch_index, h)
        return self.readout(pooled).view(-1)


class V19BatchAdapter:
    """Wraps a v19 VariantABatch with the metric-loop adapter API."""

    __slots__ = ("b",)

    def __init__(self, b):
        self.b = b

    def clone(self):
        return V19BatchAdapter(self.b.clone())

    def to(self, device, non_blocking: bool = True):
        return V19BatchAdapter(self.b.to(device))

    @property
    def num_graphs(self) -> int:
        return int(self.b.num_graphs)

    @property
    def num_nodes(self) -> int:
        return int(self.b.x.numel())

    @property
    def num_edges(self) -> int:
        return int(self.b.edge_index.size(1))

    @property
    def counts(self) -> torch.Tensor:
        return self.b.node_mask.sum(dim=1).long()


def configure_v19(spec: ModelSpec, run_cfg: RunConfig, device: torch.device):
    from torch.utils.data import DataLoader

    ckpt_path = find_checkpoint(spec.run_root, spec.ckpt_path)
    raw = safe_torch_load(ckpt_path, map_location="cpu")
    cfg_dict = raw.get("config", {}) if isinstance(raw, Mapping) else {}
    args_dict = raw.get("args", {}) if isinstance(raw, Mapping) else {}
    cfg_dict = cfg_dict or {}
    args_dict = args_dict or {}
    use_value_add = bool(
        cfg_dict.get(
            "value_add",
            cfg_dict.get("use_value_add", not bool(args_dict.get("disable_value_add", False))),
        )
    )
    pair_update_rank = int(
        cfg_dict.get(
            "pair_update_rank",
            args_dict.get("pair_update_rank", V19_PAIR_UPDATE_RANK),
        )
    )
    model = V19VariantAZincModel(
        use_value_add=use_value_add,
        pair_update_rank=pair_update_rank,
    ).to(device).eval()

    data_dir = Path(spec.data_dir)
    splits, meta = _v19_load_or_build_splits(_v19_cache_path(data_dir), data_dir)
    loaders = []
    for split in ("train", "val", "test"):
        ds = V19TensorGraphDataset(splits[split])
        loader = DataLoader(
            ds, batch_size=run_cfg.batch_size, shuffle=False,
            collate_fn=_v19_collate, num_workers=run_cfg.num_workers,
            pin_memory=(device.type == "cuda"),
        )
        loaders.append(_AdapterLoader(loader, V19BatchAdapter))

    print(f"[v19] Model built: layers={V19_N_LAYERS}, "
          f"heads={V19_N_HEADS}, hidden={V19_D_MODEL}, "
          f"value_add={use_value_add}, pair_update_rank={pair_update_rank}")
    return meta, loaders, model


# =============================================================================
# Shared adapter-loader wrapper and configure_model dispatch.
# =============================================================================


class _AdapterLoader:
    """Iterable that wraps each yielded batch from a torch DataLoader in
    the given adapter class. Lets `for batch in loader` keep the existing
    `.clone().to(device)` call pattern.
    """

    def __init__(self, loader, adapter_cls):
        self._loader = loader
        self._adapter_cls = adapter_cls

    def __iter__(self):
        for b in self._loader:
            yield self._adapter_cls(b)

    def __len__(self):
        return len(self._loader)


def configure_model(spec: ModelSpec, run_cfg: RunConfig, device: torch.device):
    """Dispatch on family. graphgps/grit go through graphgym, graphormer/csa
    use their own standalone builders. Returns (cfg_obj, loaders, model) where
    `cfg_obj` is family-specific and `loaders` is a length-3 list of
    train/val/test loaders that yield batch adapters with a uniform interface.
    """
    if spec.family in ("graphgps", "grit"):
        return configure_graphgym(spec, run_cfg, device)
    if spec.family == "graphormer":
        return configure_graphormer(spec, run_cfg, device)
    if spec.family == "csa":
        return configure_csa(spec, run_cfg, device)
    if spec.family == "v19":
        return configure_v19(spec, run_cfg, device)
    raise ValueError(f"Unknown family: {spec.family}")


def unwrap_model_batch(batch):
    """Return the native batch object expected by each standalone model.

    The metric loop uses adapters for uniform clone/to/counts handling, but the
    standalone models were trained against their native batch containers.
    """
    if isinstance(batch, GraphormerBatchAdapter):
        return batch.d
    if isinstance(batch, CSABatchAdapter):
        return batch.b
    if isinstance(batch, V19BatchAdapter):
        return batch.b
    return batch


# -----------------------------------------------------------------------------
# Attention probe (logit-collecting)
# -----------------------------------------------------------------------------


def node_positions_from_batch(batch_vec):
    if batch_vec.numel() == 0:
        return batch_vec.new_zeros(0)
    counts = torch.bincount(batch_vec)
    starts = torch.cumsum(counts, dim=0) - counts
    return torch.arange(batch_vec.numel(), device=batch_vec.device) - starts[batch_vec]


def dense_node_mask(batch_vec):
    counts = torch.bincount(batch_vec)
    B = int(counts.numel())
    N = int(counts.max().item()) if B else 0
    mask = torch.zeros((B, N), dtype=torch.bool, device=batch_vec.device)
    for b, n in enumerate(counts.tolist()):
        mask[b, :int(n)] = True
    return mask


def dense_logits_from_sparse_edges(edge_index, edge_logits, batch_vec):
    """[B, H, N, N] dense logits: row=destination/query, col=source/key."""
    node_mask = dense_node_mask(batch_vec)
    B, N = node_mask.shape
    H = int(edge_logits.size(1))
    logits = edge_logits.new_full((B, H, N, N), float("-inf"))
    edge_mask = torch.zeros((B, 1, N, N), dtype=torch.bool,
                            device=edge_logits.device)
    if edge_index.numel() == 0:
        return logits, node_mask, edge_mask
    src, dst = edge_index
    pos = node_positions_from_batch(batch_vec)
    eb = batch_vec[dst]
    row = pos[dst]
    col = pos[src]
    vals = edge_logits.squeeze(-1) if edge_logits.dim() == 3 else edge_logits
    logits[eb, :, row, col] = vals
    edge_mask[eb, 0, row, col] = True
    return logits, node_mask, edge_mask


def dense_value_output_from_flat_heads(node_values, batch_vec):
    """[B, H, N, D] dense per-head node outputs from flat [nodes, H, D]."""
    node_mask = dense_node_mask(batch_vec)
    B, N = node_mask.shape
    H = int(node_values.size(1))
    D = int(node_values.size(2))
    out = node_values.new_zeros((B, H, N, D))
    if node_values.numel() == 0:
        return out, node_mask
    pos = node_positions_from_batch(batch_vec)
    out[batch_vec, :, pos, :] = node_values
    return out, node_mask


def pyg_softmax_for_grit(src, index, num_nodes=None):
    from torch_geometric.utils.num_nodes import maybe_num_nodes
    from torch_scatter import scatter_add, scatter_max
    num_nodes = maybe_num_nodes(index, num_nodes)
    out = src - scatter_max(src, index, dim=0, dim_size=num_nodes)[0][index]
    out = out.exp()
    out = out / (scatter_add(out, index, dim=0, dim_size=num_nodes)[index] + 1e-16)
    return out


def detach_to_cpu_tree(x):
    """Detach probe outputs and move them off CUDA immediately.

    Alpha-weighted metrics intentionally keep many permuted forward outputs
    alive until all permutation weights for a batch are known. Keeping those
    tensors on GPU is unnecessary and can dominate memory for GRIT/Graphormer/
    CSA, especially after adding value-transport counterfactuals.
    """
    if torch.is_tensor(x):
        return x.detach().cpu()
    if isinstance(x, dict):
        return {k: detach_to_cpu_tree(v) for k, v in x.items()}
    if isinstance(x, list):
        return [detach_to_cpu_tree(v) for v in x]
    if isinstance(x, tuple):
        return tuple(detach_to_cpu_tree(v) for v in x)
    return x


class AttentionProbeManager:
    """Patch attention modules to capture pre-softmax logits."""

    def __init__(self, model: nn.Module, family: str):
        self.model = model
        self.family = family
        self.handles: List[Tuple[nn.Module, Any]] = []
        self.layer_modules: List[nn.Module] = []
        self.caches: List[Dict[str, Any]] = []
        self.current_ablation_plan: Optional[Dict[str, Any]] = None
        self._patch()

    def _patch(self) -> None:
        if self.family == "graphgps":
            self._patch_graphgps()
        elif self.family == "grit":
            self._patch_grit()
        elif self.family == "graphormer":
            self._patch_graphormer()
        elif self.family == "csa":
            self._patch_csa()
        elif self.family == "v19":
            self._patch_v19()
        else:
            raise ValueError(self.family)
        if not self.layer_modules:
            raise RuntimeError(f"No supported attention modules for {self.family}")
        print(f"[probe] Patched {len(self.layer_modules)} attention modules "
              f"for {self.family}")

    def close(self) -> None:
        for module, original in self.handles:
            module.forward = original
        self.handles.clear()

    @property
    def num_layers(self) -> int:
        return len(self.layer_modules)

    @property
    def num_heads_by_layer(self) -> Dict[int, int]:
        out = {}
        for i, m in enumerate(self.layer_modules):
            h = getattr(m, "num_heads", None)
            if h is None and hasattr(m, "attention"):
                h = getattr(m.attention, "num_heads", None)
            if h is None:
                raise RuntimeError(f"Could not infer #heads for layer {i}")
            out[i] = int(h)
        return out

    def _ablation_intervention(self) -> str:
        plan = self.current_ablation_plan or {}
        return str(plan.get("intervention", "none"))

    def _ablation_heads_for_layer(self, layer_idx: int, num_heads: int,
                                  device=None) -> Optional[torch.Tensor]:
        plan = self.current_ablation_plan or {}
        by_layer = plan.get("ablate_global_heads", {}) or {}
        heads = by_layer.get(layer_idx)
        if heads is None:
            heads = by_layer.get(str(layer_idx), [])
        heads = [int(h) for h in heads if 0 <= int(h) < int(num_heads)]
        if not heads:
            return None
        mask = torch.zeros(int(num_heads), dtype=torch.bool, device=device)
        mask[torch.as_tensor(heads, dtype=torch.long, device=device)] = True
        return mask

    def _dense_head_mask(self, layer_idx: int, num_heads: int, tensor: torch.Tensor,
                         rank: int = 4) -> Optional[torch.Tensor]:
        mask = self._ablation_heads_for_layer(layer_idx, num_heads, tensor.device)
        if mask is None:
            return None
        shape = [1] * rank
        shape[1] = int(num_heads)
        return mask.view(*shape)

    def _flat_head_mask(self, layer_idx: int, num_heads: int,
                        tensor: torch.Tensor) -> Optional[torch.Tensor]:
        mask = self._ablation_heads_for_layer(layer_idx, num_heads, tensor.device)
        if mask is None:
            return None
        return mask.view(1, int(num_heads), 1)

    def _patch_graphgps(self) -> None:
        for module in self.model.modules():
            if isinstance(module, nn.MultiheadAttention):
                idx = len(self.layer_modules)
                module._probe_layer_idx = idx  # type: ignore[attr-defined]
                self.layer_modules.append(module)
                original = module.forward
                manager = self

                def patched(mha_self, query, key, value, key_padding_mask=None,
                            need_weights=True, attn_mask=None,
                            average_attn_weights=True, is_causal=False, **kw):
                    if not getattr(mha_self, "batch_first", False):
                        raise RuntimeError("Probe expects batch_first=True MHA")
                    if query is not key or query is not value:
                        return original(query, key, value,
                                        key_padding_mask=key_padding_mask,
                                        need_weights=need_weights,
                                        attn_mask=attn_mask,
                                        average_attn_weights=average_attn_weights,
                                        is_causal=is_causal, **kw)
                    x = query
                    B, N, E = x.shape
                    H = int(mha_self.num_heads)
                    Dh = E // H
                    qkv = F.linear(x, mha_self.in_proj_weight, mha_self.in_proj_bias)
                    q, k, v = qkv.split(E, dim=-1)
                    q = q.view(B, N, H, Dh).transpose(1, 2)
                    k = k.view(B, N, H, Dh).transpose(1, 2)
                    v = v.view(B, N, H, Dh).transpose(1, 2)
                    logits = torch.matmul(q, k.transpose(-1, -2)) * (float(Dh) ** -0.5)
                    if attn_mask is not None:
                        am = attn_mask.to(device=logits.device, dtype=logits.dtype)
                        if am.dim() == 2:
                            logits = logits + am.view(1, 1, N, N)
                        elif am.dim() == 3:
                            logits = logits + am.view(B, H, N, N)
                        else:
                            logits = logits + am
                    if key_padding_mask is not None:
                        kpm = key_padding_mask.to(device=logits.device,
                                                  dtype=torch.bool)
                        logits = logits.masked_fill(kpm[:, None, None, :],
                                                    float("-inf"))
                        node_mask = ~kpm
                    else:
                        node_mask = torch.ones((B, N), dtype=torch.bool,
                                               device=logits.device)
                    attn = torch.softmax(logits, dim=-1)
                    if mha_self.dropout and mha_self.training:
                        attn = F.dropout(attn, p=float(mha_self.dropout),
                                         training=True)
                    head_out = torch.matmul(attn, v)
                    head_mask = manager._dense_head_mask(
                        int(mha_self._probe_layer_idx), H, head_out
                    )
                    if (head_mask is not None
                            and manager._ablation_intervention() == "head_output_zero"):
                        head_out = head_out.masked_fill(head_mask, 0.0)
                    concat = head_out.transpose(1, 2).contiguous().view(B, N, E)
                    out = mha_self.out_proj(concat)
                    out = out.masked_fill(~node_mask.unsqueeze(-1), 0.0)
                    manager.caches.append({
                        "layer": int(mha_self._probe_layer_idx),
                        "logits": logits.detach(),
                        "node_mask": node_mask.detach(),
                        "logit_mask": (node_mask[:, None, :, None]
                                       & node_mask[:, None, None, :]).detach(),
                        "value_output": head_out.detach(),
                    })
                    if need_weights:
                        w = attn if not average_attn_weights else attn.mean(dim=1)
                        return out, w.detach()
                    return out, None

                self.handles.append((module, original))
                module.forward = MethodType(patched, module)

    def _patch_graphormer(self) -> None:
        """Patch each Graphormer MHA block to capture pre-softmax logits.

        Graphormer's attention seq runs over [graph_token, n real nodes,
        padding...]. We cache only the [1:, 1:] block over real-node positions
        so the resulting [B, H, N, N] tensor lines up with other model families
        for cross-architecture comparison. Padded keys/queries are excluded
        via a logit_mask derived from batch["node_mask"].
        """
        for module in self.model.modules():
            if not isinstance(module, GraphormerMHA):
                continue
            idx = len(self.layer_modules)
            module._probe_layer_idx = idx  # type: ignore[attr-defined]
            self.layer_modules.append(module)
            original = module.forward
            manager = self

            def patched(mha_self, x, attn_bias):
                bsz, seq_len, dim = x.shape
                H = int(mha_self.num_heads)
                Dh = int(mha_self.head_dim)
                q = mha_self.q_proj(x).view(bsz, seq_len, H, Dh).transpose(1, 2)
                k = mha_self.k_proj(x).view(bsz, seq_len, H, Dh).transpose(1, 2)
                v = mha_self.v_proj(x).view(bsz, seq_len, H, Dh).transpose(1, 2)
                content_scores = torch.matmul(q, k.transpose(-2, -1)) * mha_self.scaling
                finite_bias = torch.isfinite(attn_bias)
                effective_content = content_scores
                effective_bias = attn_bias
                head_mask = manager._dense_head_mask(
                    int(mha_self._probe_layer_idx), H, content_scores
                )
                intervention = manager._ablation_intervention()
                if head_mask is not None and intervention == "bias_zero":
                    effective_bias = torch.where(
                        head_mask & finite_bias,
                        torch.zeros_like(attn_bias),
                        attn_bias,
                    )
                elif head_mask is not None and intervention == "content_zero":
                    effective_content = torch.where(
                        head_mask,
                        torch.zeros_like(content_scores),
                        content_scores,
                    )
                scores = effective_content + effective_bias
                # scores: [B, H, seq, seq] with seq = N_max + 1 (token at 0).
                attn = torch.softmax(scores.float(), dim=-1).to(scores.dtype)
                attn = mha_self.attn_dropout(attn)
                head_out = torch.matmul(attn, v)
                if head_mask is not None and intervention == "head_output_zero":
                    head_out = head_out.masked_fill(head_mask, 0.0)
                no_bias_scores = torch.where(
                    finite_bias,
                    content_scores,
                    torch.full_like(content_scores, float("-inf")),
                )
                attn_no_bias = torch.softmax(no_bias_scores.float(), dim=-1).to(scores.dtype)
                attn_no_bias = torch.where(
                    torch.isfinite(attn_no_bias), attn_no_bias, torch.zeros_like(attn_no_bias)
                )
                head_out_no_bias = torch.matmul(attn_no_bias, v)
                out = head_out.transpose(1, 2).contiguous().view(
                    bsz, seq_len, dim
                )
                out = mha_self.out_proj(out)
                out = mha_self.out_dropout(out)

                # Strip graph token row/col and build logit_mask from finite
                # entries of the bias (padded positions get -inf from
                # collator's attn_bias and never appear as valid keys).
                node_block = scores[:, :, 1:, 1:]
                finite = torch.isfinite(node_block).all(dim=1, keepdim=True)
                # finite is [B, 1, N, N] after the all-over-heads reduction.
                manager.caches.append({
                    "layer": int(mha_self._probe_layer_idx),
                    "logits": node_block.detach(),
                    "content_logits": content_scores[:, :, 1:, 1:].detach(),
                    "bias_logits": attn_bias[:, :, 1:, 1:].detach(),
                    # node_mask: any row in finite mask that has at least one
                    # valid key.
                    "node_mask": finite.squeeze(1).any(dim=-1).detach(),
                    "logit_mask": finite.detach(),
                    "value_output": head_out[:, :, 1:, :].detach(),
                    "value_output_no_bias_attn": head_out_no_bias[:, :, 1:, :].detach(),
                    "value_output_no_struct_value": head_out[:, :, 1:, :].detach(),
                    "value_output_no_struct_all": head_out_no_bias[:, :, 1:, :].detach(),
                })
                return out

            self.handles.append((module, original))
            module.forward = MethodType(patched, module)

    def _patch_csa(self) -> None:
        """Patch each CSA StaticAnchorLayer to capture pre-softmax logits.

        CSA logits are already dense [B, H, N, N] with -inf at padded keys;
        the layer's node_mask gives valid query/key positions directly.
        """
        for module in self.model.modules():
            if not isinstance(module, StaticAnchorLayer):
                continue
            idx = len(self.layer_modules)
            module._probe_layer_idx = idx  # type: ignore[attr-defined]
            self.layer_modules.append(module)
            original = module.forward
            manager = self

            def patched(layer_self, h_flat, batch):
                h_in_flat = h_flat
                h_norm_flat = layer_self.pre_attn_bn(h_flat)
                h_norm = _csa_flat_to_dense(h_norm_flat, batch)

                B, N, _ = h_norm.shape
                q = layer_self.q_proj(h_norm).view(B, N, CSA_N_HEADS, CSA_D_HEAD).transpose(1, 2)
                k = layer_self.k_proj(h_norm).view(B, N, CSA_N_HEADS, CSA_D_HEAD).transpose(1, 2)
                v = layer_self.v_proj(h_norm).view(B, N, CSA_N_HEADS, CSA_D_HEAD).transpose(1, 2)

                content_logits = torch.einsum("bhid,bhjd->bhij", q, k) * (CSA_D_HEAD ** -0.5)
                xi_sym = batch.pair_xi.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
                bias = torch.einsum("bijp,hp->bhij", xi_sym, layer_self.bias_weight)
                bias = bias * layer_self.bias_gate.view(1, CSA_N_HEADS, 1, 1)
                head_mask = manager._dense_head_mask(
                    int(layer_self._probe_layer_idx), CSA_N_HEADS, content_logits
                )
                intervention = manager._ablation_intervention()
                effective_content = content_logits
                effective_bias = bias
                if head_mask is not None and intervention == "bias_zero":
                    effective_bias = torch.where(head_mask, torch.zeros_like(bias), bias)
                elif head_mask is not None and intervention == "content_zero":
                    effective_content = torch.where(
                        head_mask, torch.zeros_like(content_logits), content_logits
                    )
                logits = effective_content + effective_bias

                key_mask = batch.node_mask[:, None, None, :]
                logits_masked = logits.masked_fill(~key_mask, float("-inf"))

                alpha = torch.softmax(logits_masked, dim=-1)
                alpha = torch.where(torch.isfinite(alpha), alpha, torch.zeros_like(alpha))
                alpha = layer_self.attn_dropout(alpha)
                content_logits_masked = content_logits.masked_fill(~key_mask, float("-inf"))
                alpha_no_bias = torch.softmax(content_logits_masked, dim=-1)
                alpha_no_bias = torch.where(
                    torch.isfinite(alpha_no_bias), alpha_no_bias, torch.zeros_like(alpha_no_bias)
                )

                out = torch.matmul(alpha, v)
                out_no_struct_value = out
                out_no_bias_attn = torch.matmul(alpha_no_bias, v)
                out_no_struct_all = out_no_bias_attn
                if layer_self.use_symmetric_value_add:
                    value_pair = torch.einsum("bijp,hdp->bhijd", xi_sym, layer_self.value_weight)
                    value_contrib = torch.einsum("bhij,bhijd->bhid", alpha, value_pair)
                    if head_mask is not None and intervention == "struct_value_zero":
                        value_contrib = value_contrib.masked_fill(head_mask, 0.0)
                    out = out + value_contrib
                    out_no_bias_attn = out_no_bias_attn + torch.einsum(
                        "bhij,bhijd->bhid", alpha_no_bias, value_pair
                    )
                if head_mask is not None and intervention == "head_output_zero":
                    out = out.masked_fill(head_mask, 0.0)
                value_output = out

                out = out.transpose(1, 2).contiguous().view(B, N, CSA_D_MODEL)
                out = layer_self.o_proj(out)
                out = out.masked_fill(~batch.node_mask.unsqueeze(-1), 0.0)
                out_flat = _csa_dense_to_flat(out, batch)

                degree_log = torch.log1p(batch.degree).view(-1, 1)
                scaled = (out_flat * layer_self.theta1.view(1, -1)
                          + degree_log * out_flat * layer_self.theta2.view(1, -1))
                h_half = h_in_flat + layer_self.resid_dropout(scaled)
                h_ffn = layer_self.ffn(layer_self.pre_ffn_bn(h_half))
                h_out = h_half + h_ffn

                node_mask = batch.node_mask
                logit_mask = (node_mask[:, None, :, None]
                              & node_mask[:, None, None, :])
                manager.caches.append({
                    "layer": int(layer_self._probe_layer_idx),
                    "logits": logits_masked.detach(),
                    "content_logits": content_logits.detach(),
                    "bias_logits": bias.detach(),
                    "node_mask": node_mask.detach(),
                    "logit_mask": logit_mask.detach(),
                    "value_output": value_output.detach(),
                    "value_output_no_bias_attn": out_no_bias_attn.detach(),
                    "value_output_no_struct_value": out_no_struct_value.detach(),
                    "value_output_no_struct_all": out_no_struct_all.detach(),
                })
                return h_out

            self.handles.append((module, original))
            module.forward = MethodType(patched, module)

    def _patch_v19(self) -> None:
        """Patch v19 VariantALayer blocks to capture dense latent-pair attention.

        v19 has CSA-like dense attention plus a learned latent pair memory. The
        cached structural bias/value counterfactuals ablate the entire pair read
        [fixed xi^0, dynamic z] so they are comparable to CSA/Graphormer/GRIT as
        "structural transport" diagnostics.
        """
        for module in self.model.modules():
            if not isinstance(module, V19VariantALayer):
                continue
            if not all(hasattr(module, a) for a in ["q_proj", "k_proj", "v_proj",
                                                    "bias_weight", "pair_u_proj"]):
                continue
            idx = len(self.layer_modules)
            module._probe_layer_idx = idx  # type: ignore[attr-defined]
            module.num_heads = V19_N_HEADS  # type: ignore[attr-defined]
            self.layer_modules.append(module)
            original = module.forward
            manager = self

            def patched(layer_self, h_flat, z_pair, batch, collect_diag: bool = False):
                H = V19_N_HEADS
                Dh = V19_D_HEAD
                Dm = V19_D_MODEL

                h_in_flat = h_flat
                h_norm_flat = layer_self.pre_attn_bn(h_flat)
                h_norm = _v19_flat_to_dense(h_norm_flat, batch)

                B, N, _ = h_norm.shape
                q = layer_self.q_proj(h_norm).view(B, N, H, Dh).transpose(1, 2)
                k = layer_self.k_proj(h_norm).view(B, N, H, Dh).transpose(1, 2)
                val = layer_self.v_proj(h_norm).view(B, N, H, Dh).transpose(1, 2)

                xi_pair, _z_read, bias_dynamic_pair, value_dynamic_pair = (
                    layer_self.latent_pair_read(z_pair, batch.pair_xi, batch.pair_mask)
                )
                content_logits = torch.matmul(q, k.transpose(-2, -1)) * (Dh ** -0.5)
                bias_in = torch.cat([xi_pair, bias_dynamic_pair], dim=-1)
                bias = torch.einsum("bijp,hp->bhij", bias_in, layer_self.bias_weight)
                bias = bias * layer_self.bias_gate.view(1, H, 1, 1)
                head_mask = manager._dense_head_mask(
                    int(layer_self._probe_layer_idx), H, content_logits
                )
                intervention = manager._ablation_intervention()
                effective_content = content_logits
                effective_bias = bias
                if head_mask is not None and intervention == "bias_zero":
                    effective_bias = torch.where(head_mask, torch.zeros_like(bias), bias)
                elif head_mask is not None and intervention == "content_zero":
                    effective_content = torch.where(
                        head_mask, torch.zeros_like(content_logits), content_logits
                    )
                logits_full = effective_content + effective_bias

                key_mask = batch.node_mask[:, None, None, :]
                logits_masked = logits_full.masked_fill(~key_mask, float("-inf"))
                alpha_clean = torch.softmax(logits_masked, dim=-1)
                alpha_clean = torch.where(
                    torch.isfinite(alpha_clean), alpha_clean, torch.zeros_like(alpha_clean)
                )
                alpha_drop = (alpha_clean if not layer_self.training
                              else layer_self.attn_dropout(alpha_clean))

                content_logits_masked = content_logits.masked_fill(~key_mask, float("-inf"))
                alpha_no_bias = torch.softmax(content_logits_masked, dim=-1)
                alpha_no_bias = torch.where(
                    torch.isfinite(alpha_no_bias), alpha_no_bias, torch.zeros_like(alpha_no_bias)
                )
                out_base_clean = torch.matmul(alpha_clean, val)
                out_base = (out_base_clean if not layer_self.training
                            else torch.matmul(alpha_drop, val))
                out_clean = out_base_clean
                out = out_base
                out_no_struct_value = out_base_clean
                out_no_bias_attn = torch.matmul(alpha_no_bias, val)
                out_no_struct_all = out_no_bias_attn

                if layer_self.use_value_add:
                    value_in = torch.cat([xi_pair, value_dynamic_pair], dim=-1)
                    value_avg_clean = torch.einsum("bhij,bijp->bhip", alpha_clean, value_in)
                    value_avg_drop = (
                        value_avg_clean if not layer_self.training
                        else torch.einsum("bhij,bijp->bhip", alpha_drop, value_in)
                    )
                    value_contrib_clean = torch.einsum(
                        "bhip,hdp->bhid", value_avg_clean, layer_self.value_weight
                    )
                    value_contrib = (
                        value_contrib_clean if not layer_self.training
                        else torch.einsum("bhip,hdp->bhid", value_avg_drop, layer_self.value_weight)
                    )
                    if head_mask is not None and intervention == "struct_value_zero":
                        value_contrib_clean = value_contrib_clean.masked_fill(head_mask, 0.0)
                        value_contrib = value_contrib.masked_fill(head_mask, 0.0)
                    value_avg_no_bias = torch.einsum("bhij,bijp->bhip", alpha_no_bias, value_in)
                    value_contrib_no_bias = torch.einsum(
                        "bhip,hdp->bhid", value_avg_no_bias, layer_self.value_weight
                    )
                    out_clean = out_clean + value_contrib_clean
                    out = out + value_contrib
                    out_no_bias_attn = out_no_bias_attn + value_contrib_no_bias

                if head_mask is not None and intervention == "head_output_zero":
                    out_clean = out_clean.masked_fill(head_mask, 0.0)
                    out = out.masked_fill(head_mask, 0.0)
                value_output = out_clean

                out_clean_proj = out_clean.transpose(1, 2).contiguous().view(B, N, Dm)
                out_clean_proj = layer_self.o_proj(out_clean_proj)
                out_clean_proj = out_clean_proj.masked_fill(~batch.node_mask.unsqueeze(-1), 0.0)
                out_clean_flat = _v19_dense_to_flat(out_clean_proj, batch)

                out_proj = out.transpose(1, 2).contiguous().view(B, N, Dm)
                out_proj = layer_self.o_proj(out_proj)
                out_proj = out_proj.masked_fill(~batch.node_mask.unsqueeze(-1), 0.0)
                out_flat = _v19_dense_to_flat(out_proj, batch)

                degree_log = batch.degree_log.view(-1, 1)
                scaled = (out_flat * layer_self.theta1.view(1, -1)
                          + degree_log * out_flat * layer_self.theta2.view(1, -1))
                h_half = h_in_flat + layer_self.resid_dropout(scaled)
                scaled_clean = (
                    out_clean_flat * layer_self.theta1.view(1, -1)
                    + degree_log * out_clean_flat * layer_self.theta2.view(1, -1)
                )
                h_pair_post = h_in_flat + scaled_clean
                h_ffn = layer_self.ffn(layer_self.pre_ffn_bn(h_half))
                h_out = h_half + h_ffn

                h_post = _v19_flat_to_dense(h_pair_post, batch)
                h_post = layer_self.h_pair_norm(h_post).masked_fill(
                    ~batch.node_mask.unsqueeze(-1), 0.0
                )
                u = layer_self.pair_u_norm(layer_self.pair_u_proj(h_post))
                vv = layer_self.pair_v_norm(layer_self.pair_v_proj(h_post))
                outer = (u[:, :, None, :, None] * vv[:, None, :, None, :]).flatten(
                    start_dim=-2
                )
                proposal = layer_self.pair_out(outer) * (
                    layer_self.pair_update_rank ** -0.5
                )
                proposal = layer_self.pair_proposal_norm(proposal)
                proposal = proposal.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)

                z_gate_state = layer_self.pair_write_state_norm(
                    z_pair.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
                )
                z_gate_state = z_gate_state.masked_fill(
                    ~batch.pair_mask.unsqueeze(-1), 0.0
                )
                write_gate = torch.sigmoid(
                    layer_self.pair_write_gate(torch.cat([z_gate_state, xi_pair], dim=-1))
                )
                write_gate = write_gate.masked_fill(~batch.pair_mask.unsqueeze(-1), 0.0)
                z_next = z_pair + layer_self.pair_update_scale() * write_gate * proposal
                z_next = _v19_mask_pair_state(z_next, batch.pair_mask)

                node_mask = batch.node_mask
                logit_mask = (node_mask[:, None, :, None]
                              & node_mask[:, None, None, :])
                manager.caches.append({
                    "layer": int(layer_self._probe_layer_idx),
                    "logits": logits_masked.detach(),
                    "content_logits": content_logits.detach(),
                    "bias_logits": bias.detach(),
                    "node_mask": node_mask.detach(),
                    "logit_mask": logit_mask.detach(),
                    "value_output": value_output.detach(),
                    "value_output_no_bias_attn": out_no_bias_attn.detach(),
                    "value_output_no_struct_value": out_no_struct_value.detach(),
                    "value_output_no_struct_all": out_no_struct_all.detach(),
                })
                return h_out, z_next

            self.handles.append((module, original))
            module.forward = MethodType(patched, module)

    def _patch_grit(self) -> None:
        for module in self.model.modules():
            cls = module.__class__.__name__
            has_grit_attrs = all(hasattr(module, a)
                                 for a in ["Q", "K", "V", "E", "Aw"])
            if "AttentionLayerGrit" in cls or (has_grit_attrs
                                               and hasattr(module, "edge_enhance")):
                idx = len(self.layer_modules)
                module._probe_layer_idx = idx  # type: ignore[attr-defined]
                self.layer_modules.append(module)
                original = module.forward
                manager = self

                def patched(attn_self, batch):
                    from torch_scatter import scatter
                    import opt_einsum as oe

                    Q_h = attn_self.Q(batch.x)
                    K_h = attn_self.K(batch.x)
                    V_h = attn_self.V(batch.x)
                    if batch.get("edge_attr", None) is not None:
                        batch.E = attn_self.E(batch.edge_attr)
                    else:
                        batch.E = None
                    H = int(attn_self.num_heads)
                    Dh = int(attn_self.out_dim)
                    batch.Q_h = Q_h.view(-1, H, Dh)
                    batch.K_h = K_h.view(-1, H, Dh)
                    batch.V_h = V_h.view(-1, H, Dh)

                    src = batch.K_h[batch.edge_index[0]]
                    dest = batch.Q_h[batch.edge_index[1]]
                    content_score_vec = src + dest
                    score_vec = content_score_vec
                    if batch.get("E", None) is not None:
                        batch.E = batch.E.view(-1, H, Dh * 2)
                        E_w, E_b = batch.E[:, :, :Dh], batch.E[:, :, Dh:]
                        score_vec = score_vec * E_w
                        score_vec = (torch.sqrt(torch.relu(score_vec))
                                     - torch.sqrt(torch.relu(-score_vec)))
                        score_vec = score_vec + E_b
                    content_score_vec = attn_self.act(content_score_vec)
                    score_vec = attn_self.act(score_vec)
                    e_t = score_vec
                    if batch.get("E", None) is not None:
                        batch.wE = score_vec.flatten(1)

                    raw_content = oe.contract(
                        "ehd,dhc->ehc", content_score_vec, attn_self.Aw,
                        backend="torch"
                    )
                    raw = oe.contract("ehd,dhc->ehc", score_vec, attn_self.Aw,
                                      backend="torch")
                    if getattr(attn_self, "clamp", None) is not None:
                        raw_content = torch.clamp(
                            raw_content, min=-float(attn_self.clamp),
                            max=float(attn_self.clamp)
                        )
                        raw = torch.clamp(raw, min=-float(attn_self.clamp),
                                          max=float(attn_self.clamp))

                    head_mask = manager._flat_head_mask(
                        int(attn_self._probe_layer_idx), H, raw
                    )
                    intervention = manager._ablation_intervention()
                    raw_effective = raw
                    if head_mask is not None and intervention == "bias_zero":
                        raw_effective = torch.where(head_mask, raw_content, raw)
                    elif head_mask is not None and intervention == "content_zero":
                        raw_effective = torch.where(head_mask, raw - raw_content, raw)

                    score = pyg_softmax_for_grit(raw_effective, batch.edge_index[1],
                                                 num_nodes=batch.num_nodes)
                    score = attn_self.dropout(score)
                    score_no_bias = pyg_softmax_for_grit(
                        raw_content, batch.edge_index[1], num_nodes=batch.num_nodes
                    )
                    score_no_bias = attn_self.dropout(score_no_bias)
                    batch.attn = score
                    msg = batch.V_h[batch.edge_index[0]] * score
                    wV_no_struct_value = torch.zeros_like(batch.V_h)
                    scatter(msg, batch.edge_index[1], dim=0, out=wV_no_struct_value,
                            reduce="add")
                    msg_no_bias = batch.V_h[batch.edge_index[0]] * score_no_bias
                    wV_no_struct_all = torch.zeros_like(batch.V_h)
                    scatter(msg_no_bias, batch.edge_index[1], dim=0,
                            out=wV_no_struct_all, reduce="add")
                    batch.wV = wV_no_struct_value.clone()
                    wV_no_bias_attn = wV_no_struct_all.clone()

                    if (getattr(attn_self, "edge_enhance", False)
                            and batch.get("E", None) is not None):
                        rowV = scatter(e_t * score, batch.edge_index[1], dim=0,
                                       dim_size=batch.num_nodes, reduce="add")
                        rowV = oe.contract("nhd,dhc->nhc", rowV,
                                           attn_self.VeRow, backend="torch")
                        if head_mask is not None and intervention == "struct_value_zero":
                            rowV = rowV.masked_fill(head_mask, 0.0)
                        batch.wV = batch.wV + rowV
                        rowV_no_bias = scatter(
                            e_t * score_no_bias, batch.edge_index[1], dim=0,
                            dim_size=batch.num_nodes, reduce="add"
                        )
                        rowV_no_bias = oe.contract(
                            "nhd,dhc->nhc", rowV_no_bias,
                            attn_self.VeRow, backend="torch"
                        )
                        wV_no_bias_attn = wV_no_bias_attn + rowV_no_bias

                    if head_mask is not None and intervention == "head_output_zero":
                        batch.wV = batch.wV.masked_fill(head_mask, 0.0)

                    dense_logits, node_mask, edge_mask = (
                        dense_logits_from_sparse_edges(batch.edge_index, raw_effective,
                                                       batch.batch)
                    )
                    dense_content, _, _ = dense_logits_from_sparse_edges(
                        batch.edge_index, raw_content, batch.batch
                    )
                    dense_bias, _, _ = dense_logits_from_sparse_edges(
                        batch.edge_index, raw - raw_content, batch.batch
                    )
                    dense_value, _ = dense_value_output_from_flat_heads(
                        batch.wV, batch.batch
                    )
                    dense_no_bias_value, _ = dense_value_output_from_flat_heads(
                        wV_no_bias_attn, batch.batch
                    )
                    dense_no_struct_value, _ = dense_value_output_from_flat_heads(
                        wV_no_struct_value, batch.batch
                    )
                    dense_no_struct_all, _ = dense_value_output_from_flat_heads(
                        wV_no_struct_all, batch.batch
                    )
                    manager.caches.append({
                        "layer": int(attn_self._probe_layer_idx),
                        "logits": dense_logits.detach(),
                        "content_logits": dense_content.detach(),
                        "bias_logits": dense_bias.detach(),
                        "node_mask": node_mask.detach(),
                        "logit_mask": edge_mask.detach(),
                        "value_output": dense_value.detach(),
                        "value_output_no_bias_attn": dense_no_bias_value.detach(),
                        "value_output_no_struct_value": dense_no_struct_value.detach(),
                        "value_output_no_struct_all": dense_no_struct_all.detach(),
                    })
                    return batch.wV, batch.get("wE", None)

                self.handles.append((module, original))
                module.forward = MethodType(patched, module)

    @torch.no_grad()
    def forward_collect(self, batch, ablation_plan: Optional[Dict[str, Any]] = None,
                        collect_layers: bool = True) -> Dict[str, Any]:
        self.caches = []
        self.current_ablation_plan = ablation_plan
        try:
            out = self.model(unwrap_model_batch(batch))
            pred = get_model_pred(out).detach().cpu()
            layers = sorted(self.caches, key=lambda d: int(d["layer"]))
            if len(layers) != len(self.layer_modules):
                raise RuntimeError(
                    f"Collected {len(layers)} caches but expected "
                    f"{len(self.layer_modules)}"
                )
            if not collect_layers:
                return {"pred": pred, "layers": []}
            layers_cpu = detach_to_cpu_tree(layers)
            return {"pred": pred, "layers": layers_cpu}
        finally:
            self.current_ablation_plan = None
            self.caches = []


# -----------------------------------------------------------------------------
# Channel-targeted permutations
#
# Each variant permutes ONE input channel by a within-graph node permutation
# sigma, holding all other channels fixed:
#   - x-only        : permute node features `x` (atom identity).
#                     Tests dependence on symbolic content.
#                     Applies cleanly to all configured families.
#   - input-PE-only : permute the STRUCTURAL features that are concatenated /
#                     added to nodes at the INPUT encoder. The exact scope is
#                     model-specific:
#                       graphgps : node-level structural-encoding tensors
#                                  (pestat_RWSE, EigVecs, ...) on Data.
#                       grit     : `rrwp_val` (per-pair). NB: in GRIT this also
#                                  flows into the attention bias via E_w/E_b,
#                                  so the input-PE-perm is not isolated from
#                                  attention-level structural information.
#                                  This caveat is intrinsic to GRIT's design.
#                       graphormer : `in_degree` + `out_degree` (centrality
#                                  added at input). Permuting `spatial_pos`,
#                                  `edge_input`, `attn_bias` would conflate
#                                  with the attention-level bias and is NOT
#                                  included in this metric.
#                       csa      : `rwse` only (RWSE diagonal injected at
#                                  input via rwse_proj). `pair_xi` is the
#                                  attention-level structural bias and is NOT
#                                  permuted here.
#
# For each variant, the (invariance, equivariance) score pair is well-defined
# under the same exclusion principle as the paper (Theorem 1).
#
# Reframing note: in the input-PE interpretation, graphormer/csa scores
# reflect sensitivity to node-level centrality / RWSE only -- not the
# attention-level structural bias which is the dominant structural pathway in
# those architectures. Expect lower pe_equivariance for those models.
# -----------------------------------------------------------------------------


# Names of node-level structural-encoding tensors that PyG/GraphGym configs
# attach to each Data. We permute every entry that is present and node-shaped.
GPS_NODE_PE_KEYS = (
    "pestat_RWSE", "EigVecs", "EigVals", "LapPE", "RWSE",
    "pestat_LapPE", "pestat_HKdiagSE", "pestat_ElstaticPE",
)


def _gather_dense_node_axis(t: torch.Tensor, perm_pos: torch.Tensor) -> torch.Tensor:
    """Permute a dense tensor along its second axis (node axis) per graph.

    t: [B, N, ...] where the second dim is the per-graph node axis.
    perm_pos: [B, N] with perm_pos[b, k_new] = k_old.
    Padded positions get index 0 (perm_pos default); they are zero-masked or
    -inf-masked downstream so the value gathered there is irrelevant.
    """
    B, N = perm_pos.shape
    extra = t.dim() - 2
    idx = perm_pos.view(B, N, *([1] * extra)).expand_as(t)
    return torch.gather(t, dim=1, index=idx)


def _gather_dense_pair_axes(t: torch.Tensor, perm_pos: torch.Tensor) -> torch.Tensor:
    """Permute a dense pair tensor along its second AND third axes per graph.

    t: [B, N, N, ...]. perm_pos: [B, N] with perm_pos[b, k_new] = k_old.
    """
    B, N = perm_pos.shape
    extra = t.dim() - 3
    # Row gather.
    idx_r = perm_pos.view(B, N, 1, *([1] * extra)).expand_as(t)
    t1 = torch.gather(t, dim=1, index=idx_r)
    # Column gather.
    idx_c = perm_pos.view(B, 1, N, *([1] * extra)).expand_as(t1)
    return torch.gather(t1, dim=2, index=idx_c)


def make_node_permutation_bundle(batch_cpu, generator=None):
    """Within-graph node permutation. Supports PyG Batch, GraphormerBatchAdapter
    and CSABatchAdapter. Returns dict with perm_flat (flat-index gather for
    flat layouts) and perm_pos [B, max_nodes] (per-graph position permutation
    for dense layouts).
    """
    if isinstance(batch_cpu, (GraphormerBatchAdapter, CSABatchAdapter, V19BatchAdapter)):
        counts = batch_cpu.counts.cpu().long()
        B = int(counts.numel())
        max_nodes = int(counts.max().item()) if B else 0
        Ntot = int(counts.sum().item())
        ptr = torch.cat([torch.zeros(1, dtype=torch.long),
                         torch.cumsum(counts, dim=0)])
    else:
        # PyG Batch.
        batch_vec = batch_cpu.batch.cpu()
        if hasattr(batch_cpu, "ptr"):
            ptr = batch_cpu.ptr.cpu()
        else:
            counts_pyg = torch.bincount(batch_vec)
            ptr = torch.cat([torch.zeros(1, dtype=torch.long),
                             torch.cumsum(counts_pyg, dim=0)])
        B = int(ptr.numel() - 1)
        counts = (ptr[1:] - ptr[:-1]).long()
        max_nodes = int(counts.max().item())
        Ntot = int(ptr[-1].item())

    perm_flat = torch.arange(Ntot, dtype=torch.long)
    perm_pos = torch.zeros((B, max_nodes), dtype=torch.long)
    valid = torch.zeros((B, max_nodes), dtype=torch.bool)
    for b in range(B):
        start = int(ptr[b].item())
        n = int(counts[b].item())
        p = torch.randperm(n, generator=generator)
        perm_flat[start + torch.arange(n)] = start + p
        perm_pos[b, :n] = p
        valid[b, :n] = True
    return {"perm_flat": perm_flat, "perm_pos": perm_pos,
            "valid": valid, "ptr": ptr, "generator": generator}


def make_x_permuted_variant(batch_cpu, perm_bundle, family=None):
    """Permute ONLY node features `x`. Everything else fixed."""
    if isinstance(batch_cpu, GraphormerBatchAdapter):
        d = batch_cpu.clone()
        # x is [B, N, 1] padded; permute along node axis per graph.
        d.d["x"] = _gather_dense_node_axis(
            batch_cpu.d["x"], perm_bundle["perm_pos"]
        )
        return d
    if isinstance(batch_cpu, CSABatchAdapter):
        d = batch_cpu.clone()
        d.b.x = batch_cpu.b.x[perm_bundle["perm_flat"]].clone()
        return d
    if isinstance(batch_cpu, V19BatchAdapter):
        d = batch_cpu.clone()
        d.b.x = batch_cpu.b.x[perm_bundle["perm_flat"]].clone()
        return d
    # PyG path (graphgps / grit).
    d = batch_cpu.clone()
    d.x = batch_cpu.x[perm_bundle["perm_flat"]].clone()
    return d


def _permute_rrwp_val(rrwp_index, rrwp_val, perm_flat, num_nodes):
    """Reassign rrwp_val rows so that pair (i,j) receives the value originally
    at pair (sigma(i), sigma(j)). Vectorised via key-hash + searchsorted.

    Convention: perm_flat[u_new] = u_old, so applying sigma at u means looking
    up the value at u_old = perm_flat[u].
    """
    s = rrwp_index[0].cpu().long()
    d = rrwp_index[1].cpu().long()
    perm = perm_flat.cpu().long()
    keys = s * int(num_nodes) + d
    sorted_keys, sort_idx = torch.sort(keys)
    new_keys = perm[s] * int(num_nodes) + perm[d]
    positions = torch.searchsorted(sorted_keys, new_keys)
    if int(positions.max().item()) >= int(sorted_keys.numel()) or not torch.equal(
        sorted_keys[positions], new_keys
    ):
        raise RuntimeError(
            "rrwp pair lookup failed: permuted pair not found in rrwp_index. "
            "This indicates rrwp_index is not a full dense pair set."
        )
    new_rows = sort_idx[positions]
    return rrwp_val[new_rows].clone().to(rrwp_val.device)


def _apply_input_pe_perm(d, perm_bundle, family):
    """Apply the input-PE permutation in-place on a cloned batch.

    Returns True if at least one structural channel was permuted; False if
    the batch carries no recognised input-PE channel (graceful skip).
    """
    perm_flat = perm_bundle["perm_flat"]
    perm_pos = perm_bundle["perm_pos"]
    if family == "graphgps":
        n = int(d.num_nodes)
        found = False
        for key in GPS_NODE_PE_KEYS:
            if hasattr(d, key):
                val = getattr(d, key)
                if torch.is_tensor(val) and val.dim() >= 1 and val.size(0) == n:
                    setattr(d, key, val[perm_flat].clone())
                    found = True
        return found
    if family == "grit":
        if hasattr(d, "rrwp_val") and hasattr(d, "rrwp_index"):
            d.rrwp_val = _permute_rrwp_val(
                d.rrwp_index, d.rrwp_val, perm_flat, d.num_nodes
            )
            return True
        return False
    if family == "graphormer":
        # Input PE = centrality (in_degree + out_degree). Both are [B, N]
        # padded; permute along node axis.
        in_d = d.d["in_degree"].unsqueeze(-1)
        out_d = d.d["out_degree"].unsqueeze(-1)
        d.d["in_degree"] = _gather_dense_node_axis(in_d, perm_pos).squeeze(-1)
        d.d["out_degree"] = _gather_dense_node_axis(out_d, perm_pos).squeeze(-1)
        return True
    if family == "csa":
        # Input PE = RWSE diagonal (flat, [N_total, K]).
        d.b.rwse = d.b.rwse[perm_flat].clone()
        return True
    if family == "v19":
        # Input PE = RWSE diagonal (flat, [N_total, K]); pair_xi is the
        # attention-level structural read and is held fixed in this metric.
        d.b.rwse = d.b.rwse[perm_flat].clone()
        return True
    return False


def make_pe_permuted_variant(batch_cpu, perm_bundle, family):
    """Permute ONLY the input-level structural-encoding channel.

    Channel scope per family is documented at the top of this section.
    Returns None if no input-PE channel is found on the batch (graceful skip).
    """
    d = batch_cpu.clone()
    found = _apply_input_pe_perm(d, perm_bundle, family)
    return d if found else None


def make_x_and_pe_permuted_variant(batch_cpu, perm_bundle, family):
    """Permute BOTH `x` and the input-PE channel by the SAME sigma.

    Used to test additivity of the logit in (x, input-PE). Returns None if no
    input-PE channel is found.
    """
    d = make_x_permuted_variant(batch_cpu, perm_bundle, family=family)
    found = _apply_input_pe_perm(d, perm_bundle, family)
    return d if found else None


def _inverse_perm_flat(perm_flat: torch.Tensor) -> torch.Tensor:
    inv = torch.empty_like(perm_flat)
    inv[perm_flat] = torch.arange(perm_flat.numel(), dtype=torch.long)
    return inv


def _pyg_batch_keys(batch) -> List[str]:
    keys: List[str] = []

    def _add_many(values):
        for value in values:
            if isinstance(value, str) and value not in keys:
                keys.append(value)

    keys_attr = getattr(batch, "keys", None)
    if callable(keys_attr):
        try:
            _add_many(list(keys_attr()))
        except Exception:
            pass
    elif keys_attr is not None:
        try:
            _add_many(list(keys_attr))
        except Exception:
            pass

    store = getattr(batch, "_store", None)
    if store is not None:
        store_keys = getattr(store, "keys", None)
        if callable(store_keys):
            try:
                _add_many(list(store_keys()))
            except Exception:
                pass

    stores = getattr(batch, "stores", None)
    if stores is not None:
        try:
            for st in stores:
                store_keys = getattr(st, "keys", None)
                if callable(store_keys):
                    _add_many(list(store_keys()))
        except Exception:
            pass

    try:
        for key, value in vars(batch).items():
            if not key.startswith("_") and torch.is_tensor(value):
                _add_many([key])
    except Exception:
        pass
    return keys


def _relabel_pyg_like_batch(batch_cpu, perm_bundle, family):
    d = batch_cpu.clone()
    perm_flat = perm_bundle["perm_flat"]
    inv_flat = _inverse_perm_flat(perm_flat)
    n = int(d.num_nodes)

    skip = {"edge_index", "edge_attr", "ptr"}
    keys = _pyg_batch_keys(d)
    for key in keys:
        if key in skip:
            continue
        val = getattr(d, key, None)
        if torch.is_tensor(val) and val.dim() >= 1 and val.size(0) == n:
            setattr(d, key, val[perm_flat].clone())

    if hasattr(d, "edge_index") and torch.is_tensor(d.edge_index):
        d.edge_index = inv_flat[d.edge_index.cpu()].to(d.edge_index.device)
    if family == "grit" and hasattr(d, "rrwp_index"):
        d.rrwp_index = inv_flat[d.rrwp_index.cpu()].to(d.rrwp_index.device)
        # rrwp_val rows stay attached to the same semantic pair; only the pair
        # indices are relabeled.
    return d


def _gather_graphormer_attn_bias(attn_bias: torch.Tensor,
                                 perm_pos: torch.Tensor) -> torch.Tensor:
    out = attn_bias.clone()
    node_block = out[:, 1:, 1:].unsqueeze(-1)
    out[:, 1:, 1:] = _gather_dense_pair_axes(node_block, perm_pos).squeeze(-1)
    node_cols = out[:, 0, 1:].unsqueeze(-1)
    node_rows = out[:, 1:, 0].unsqueeze(-1)
    out[:, 0, 1:] = _gather_dense_node_axis(node_cols, perm_pos).squeeze(-1)
    out[:, 1:, 0] = _gather_dense_node_axis(node_rows, perm_pos).squeeze(-1)
    return out


def make_relabel_variant(batch_cpu, perm_bundle, family):
    """Apply a true graph relabeling: every node-indexed and pair-indexed
    field is transported consistently. The result is isomorphic to the input.
    """
    perm_pos = perm_bundle["perm_pos"]
    if isinstance(batch_cpu, GraphormerBatchAdapter):
        d = batch_cpu.clone()
        for key in ["x", "in_degree", "out_degree"]:
            val = d.d.get(key)
            if torch.is_tensor(val):
                t = val if val.dim() > 2 else val.unsqueeze(-1)
                gathered = _gather_dense_node_axis(t, perm_pos)
                d.d[key] = gathered if val.dim() > 2 else gathered.squeeze(-1)
        for key in ["spatial_pos", "edge_input"]:
            val = d.d.get(key)
            if torch.is_tensor(val):
                t = val if val.dim() > 3 else val.unsqueeze(-1)
                gathered = _gather_dense_pair_axes(t, perm_pos)
                d.d[key] = gathered if val.dim() > 3 else gathered.squeeze(-1)
        if torch.is_tensor(d.d.get("attn_bias")):
            _reset_graphormer_attn_bias(d.d)
        return d

    if isinstance(batch_cpu, CSABatchAdapter):
        d = batch_cpu.clone()
        b = d.b
        perm_flat = perm_bundle["perm_flat"]
        inv_flat = _inverse_perm_flat(perm_flat)
        b.x = b.x[perm_flat].clone()
        b.rwse = b.rwse[perm_flat].clone()
        b.degree = b.degree[perm_flat].clone()
        b.edge_index = inv_flat[b.edge_index.cpu()].to(b.edge_index.device)
        b.pair_xi = _gather_dense_pair_axes(b.pair_xi, perm_pos).clone()
        return d

    if isinstance(batch_cpu, V19BatchAdapter):
        d = batch_cpu.clone()
        b = d.b
        perm_flat = perm_bundle["perm_flat"]
        inv_flat = _inverse_perm_flat(perm_flat)
        b.x = b.x[perm_flat].clone()
        b.rwse = b.rwse[perm_flat].clone()
        b.degree = b.degree[perm_flat].clone()
        b.degree_log = b.degree_log[perm_flat].clone()
        b.edge_index = inv_flat[b.edge_index.cpu()].to(b.edge_index.device)
        b.pair_xi = _gather_dense_pair_axes(b.pair_xi, perm_pos).clone()
        return d

    return _relabel_pyg_like_batch(batch_cpu, perm_bundle, family)


def _edge_graph_ids_from_pyg(batch_cpu):
    return batch_cpu.batch[batch_cpu.edge_index[0]].cpu()


def _edge_graph_ids_from_csa(batch_cpu: CSABatchAdapter):
    b = batch_cpu.b
    return b.batch_index[b.edge_index[0]].cpu()


def _edge_graph_ids_from_v19(batch_cpu: V19BatchAdapter):
    b = batch_cpu.b
    return b.batch_index[b.edge_index[0]].cpu()


def make_edge_label_permuted_variant(batch_cpu, perm_bundle, family):
    """Permute edge/path label channels while holding topology fixed."""
    if isinstance(batch_cpu, GraphormerBatchAdapter):
        d = batch_cpu.clone()
        edge_input = d.d.get("edge_input")
        node_mask = d.d.get("node_mask")
        if not torch.is_tensor(edge_input) or not torch.is_tensor(node_mask):
            return None
        for bidx, n in enumerate(node_mask.sum(dim=1).cpu().long().tolist()):
            n = int(n)
            if n <= 2:
                continue
            mask = torch.ones((n, n), dtype=torch.bool)
            mask.fill_diagonal_(False)
            vals = edge_input[bidx, :n, :n][mask].clone()
            if vals.size(0) > 1:
                p = torch.randperm(vals.size(0), generator=perm_bundle.get("generator"))
                edge_input[bidx, :n, :n][mask] = vals[p]
        return d

    if isinstance(batch_cpu, CSABatchAdapter):
        d = batch_cpu.clone()
        b = d.b
        if b.edge_attr.numel() == 0:
            return None
        edge_gid = _edge_graph_ids_from_csa(batch_cpu)
        bond_start = CSA_D_MAX_SPD + 1 + CSA_K_WALK
        b.pair_xi[..., bond_start:] = 0.0
        for g in range(b.num_graphs):
            idx = torch.nonzero(edge_gid == g, as_tuple=False).view(-1)
            if idx.numel() > 1:
                p = idx[torch.randperm(idx.numel(), generator=perm_bundle.get("generator"))]
                b.edge_attr[idx] = batch_cpu.b.edge_attr[p].clone()
            src, dst = b.edge_index[:, idx]
            local_src = b.node_pos[src]
            local_dst = b.node_pos[dst]
            attr = b.edge_attr[idx].long().clamp(0, CSA_NUM_BOND_TYPES - 1)
            b.pair_xi[g, local_src, local_dst, bond_start + attr] = 1.0
        return d

    if isinstance(batch_cpu, V19BatchAdapter):
        d = batch_cpu.clone()
        b = d.b
        if b.edge_attr.numel() == 0:
            return None
        edge_gid = _edge_graph_ids_from_v19(batch_cpu)
        bond_start = V19_P_RING_PAIR + (V19_D_MAX_SPD + 1) + V19_K_WALK
        b.pair_xi[..., bond_start:bond_start + V19_NUM_BOND_TYPES] = 0.0
        for g in range(b.num_graphs):
            idx = torch.nonzero(edge_gid == g, as_tuple=False).view(-1)
            if idx.numel() > 1:
                p = idx[torch.randperm(idx.numel(), generator=perm_bundle.get("generator"))]
                b.edge_attr[idx] = batch_cpu.b.edge_attr[p].clone()
            src, dst = b.edge_index[:, idx]
            local_src = b.node_pos[src]
            local_dst = b.node_pos[dst]
            attr = b.edge_attr[idx].long().clamp(0, V19_NUM_BOND_TYPES - 1)
            b.pair_xi[g, local_src, local_dst, bond_start + attr] = 1.0
        return d

    d = batch_cpu.clone()
    if not hasattr(d, "edge_attr") or d.edge_attr is None or d.edge_attr.numel() == 0:
        return None
    edge_gid = _edge_graph_ids_from_pyg(batch_cpu)
    for g in range(int(batch_cpu.num_graphs)):
        idx = torch.nonzero(edge_gid == g, as_tuple=False).view(-1)
        if idx.numel() > 1:
            p = idx[torch.randperm(idx.numel(), generator=perm_bundle.get("generator"))]
            d.edge_attr[idx] = batch_cpu.edge_attr[p].clone()
    return d


def make_pair_structure_permuted_variant(batch_cpu, perm_bundle, family):
    """Permute attention-level pair-structure channels while keeping x,
    topology, and direct edge labels fixed.
    """
    if family == "grit" and hasattr(batch_cpu, "rrwp_val"):
        d = batch_cpu.clone()
        if not (hasattr(d, "rrwp_index") and hasattr(d, "rrwp_val")):
            return None
        src = d.rrwp_index[0].cpu()
        gids = batch_cpu.batch[src].cpu()
        for g in range(int(batch_cpu.num_graphs)):
            idx = torch.nonzero(gids == g, as_tuple=False).view(-1)
            if idx.numel() > 1:
                p = idx[torch.randperm(idx.numel(), generator=perm_bundle.get("generator"))]
                d.rrwp_val[idx] = batch_cpu.rrwp_val[p].clone()
        return d

    if isinstance(batch_cpu, GraphormerBatchAdapter):
        d = batch_cpu.clone()
        sp = d.d.get("spatial_pos")
        node_mask = d.d.get("node_mask")
        if not torch.is_tensor(sp) or not torch.is_tensor(node_mask):
            return None
        for bidx, n in enumerate(node_mask.sum(dim=1).cpu().long().tolist()):
            n = int(n)
            if n <= 2:
                continue
            mask = torch.ones((n, n), dtype=torch.bool)
            mask.fill_diagonal_(False)
            vals = sp[bidx, :n, :n][mask].clone()
            if vals.numel() > 1:
                p = torch.randperm(vals.numel(), generator=perm_bundle.get("generator"))
                sp[bidx, :n, :n][mask] = vals[p]
        return d

    if isinstance(batch_cpu, CSABatchAdapter):
        d = batch_cpu.clone()
        struct_dim = CSA_D_MAX_SPD + 1 + CSA_K_WALK
        for bidx, n in enumerate(d.b.node_mask.sum(dim=1).cpu().long().tolist()):
            n = int(n)
            if n <= 2:
                continue
            mask = torch.ones((n, n), dtype=torch.bool)
            mask.fill_diagonal_(False)
            vals = d.b.pair_xi[bidx, :n, :n, :struct_dim][mask].clone()
            if vals.size(0) > 1:
                p = torch.randperm(vals.size(0), generator=perm_bundle.get("generator"))
                d.b.pair_xi[bidx, :n, :n, :struct_dim][mask] = vals[p]
        return d

    if isinstance(batch_cpu, V19BatchAdapter):
        d = batch_cpu.clone()
        # Fixed pair-structure channels exclude direct bond type; include ring,
        # shortest-path, and random-walk pair channels.
        struct_dim = V19_P_RING_PAIR + (V19_D_MAX_SPD + 1) + V19_K_WALK
        for bidx, n in enumerate(d.b.node_mask.sum(dim=1).cpu().long().tolist()):
            n = int(n)
            if n <= 2:
                continue
            mask = torch.ones((n, n), dtype=torch.bool)
            mask.fill_diagonal_(False)
            vals = d.b.pair_xi[bidx, :n, :n, :struct_dim][mask].clone()
            if vals.size(0) > 1:
                p = torch.randperm(vals.size(0), generator=perm_bundle.get("generator"))
                d.b.pair_xi[bidx, :n, :n, :struct_dim][mask] = vals[p]
        return d

    return None


def _is_connected_undirected(num_nodes: int, edges: Sequence[Tuple[int, int]]) -> bool:
    if num_nodes <= 1:
        return True
    adj = [[] for _ in range(num_nodes)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    seen = {0}
    stack = [0]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return len(seen) == num_nodes


def _extract_undirected_edges(edge_index: torch.Tensor,
                              edge_attr: Optional[torch.Tensor],
                              num_nodes: int):
    seen = {}
    for e, (u_raw, v_raw) in enumerate(edge_index.t().cpu().tolist()):
        u, v = int(u_raw), int(v_raw)
        if u == v:
            continue
        key = (u, v) if u < v else (v, u)
        if key not in seen:
            attr = None if edge_attr is None else edge_attr[e].detach().cpu().clone()
            seen[key] = attr
    edges = list(seen.keys())
    attrs = [seen[e] for e in edges]
    return edges, attrs


def _rewire_undirected_edges(num_nodes: int,
                             edges: Sequence[Tuple[int, int]],
                             attrs: Sequence[Any],
                             generator=None):
    edges = [tuple(map(int, e)) for e in edges]
    attrs = list(attrs)
    if len(edges) < 2:
        return None
    edge_set = set(edges)
    require_connected = _is_connected_undirected(num_nodes, edges)
    target = max(1, len(edges) // 2)
    swaps = 0
    attempts = max(80, target * 40)
    for _ in range(attempts):
        if swaps >= target:
            break
        pair = torch.randperm(len(edges), generator=generator)[:2].tolist()
        i, j = int(pair[0]), int(pair[1])
        a, b = edges[i]
        c, d = edges[j]
        if len({a, b, c, d}) < 4:
            continue
        if int(torch.randint(0, 2, (1,), generator=generator).item()) == 0:
            e1, e2 = tuple(sorted((a, d))), tuple(sorted((c, b)))
        else:
            e1, e2 = tuple(sorted((a, c))), tuple(sorted((b, d)))
        if e1[0] == e1[1] or e2[0] == e2[1] or e1 == e2:
            continue
        old1, old2 = edges[i], edges[j]
        if e1 in edge_set or e2 in edge_set:
            continue
        candidate = list(edges)
        candidate[i], candidate[j] = e1, e2
        if require_connected and not _is_connected_undirected(num_nodes, candidate):
            continue
        edge_set.remove(old1)
        edge_set.remove(old2)
        edge_set.add(e1)
        edge_set.add(e2)
        edges = candidate
        swaps += 1
    if swaps == 0:
        return None
    return edges, attrs, swaps


def _expand_undirected_edges(edges, attrs, device):
    rows, vals = [], []
    for (u, v), attr in zip(edges, attrs):
        rows.extend([(u, v), (v, u)])
        vals.extend([attr, attr])
    edge_index = torch.tensor(rows, dtype=torch.long, device=device).t().contiguous()
    if vals and vals[0] is not None:
        edge_attr = torch.stack([v for v in vals], dim=0).to(device)
    else:
        edge_attr = None
    return edge_index, edge_attr


def _rwse_from_edge_index(edge_index: torch.Tensor, num_nodes: int,
                          dim: int, device=None) -> torch.Tensor:
    device = device or edge_index.device
    A = torch.zeros((num_nodes, num_nodes), dtype=torch.float32, device=device)
    if edge_index.numel() > 0:
        src, dst = edge_index.to(device)
        A[src, dst] = 1.0
    A = torch.maximum(A, A.t())
    A.fill_diagonal_(0.0)
    degree = A.sum(dim=1)
    W = torch.zeros_like(A)
    nz = degree > 0
    W[nz] = A[nz] / degree[nz].unsqueeze(1)
    out = []
    P = W.clone()
    for _ in range(dim):
        out.append(P.diagonal())
        P = P @ W
    return torch.stack(out, dim=-1) if out else A.new_zeros((num_nodes, 0))


def _recompute_graphgps_rwse_or_skip(d, family: str) -> bool:
    if family != "graphgps":
        return True
    present = []
    for key in GPS_NODE_PE_KEYS:
        val = getattr(d, key, None)
        if torch.is_tensor(val) and val.dim() >= 2 and val.size(0) == d.num_nodes:
            present.append((key, val))
    if not present:
        return True
    if any("RWSE" not in key for key, _ in present):
        return False
    pieces = []
    for start, end in zip(d.ptr[:-1].cpu().tolist(), d.ptr[1:].cpu().tolist()):
        mask = ((d.edge_index[0] >= start) & (d.edge_index[0] < end)
                & (d.edge_index[1] >= start) & (d.edge_index[1] < end))
        local_ei = d.edge_index[:, mask] - int(start)
        pieces.append((int(start), int(end), local_ei))
    for key, old in present:
        dim = int(old.size(-1))
        vals = []
        for _start, _end, local_ei in pieces:
            vals.append(_rwse_from_edge_index(
                local_ei, _end - _start, dim, device=old.device
            ).to(dtype=old.dtype))
        setattr(d, key, torch.cat(vals, dim=0))
    return True


def _rewire_pyg_like_topology(batch_cpu, family, generator=None):
    if family == "grit" and (hasattr(batch_cpu, "rrwp_val")
                             or hasattr(batch_cpu, "rrwp_index")):
        return None
    d = batch_cpu.clone()
    edge_indices, edge_attrs = [], []
    total_swaps = 0
    for start, end in zip(batch_cpu.ptr[:-1].cpu().tolist(),
                          batch_cpu.ptr[1:].cpu().tolist()):
        start, end = int(start), int(end)
        mask = ((batch_cpu.edge_index[0] >= start)
                & (batch_cpu.edge_index[0] < end)
                & (batch_cpu.edge_index[1] >= start)
                & (batch_cpu.edge_index[1] < end))
        local_ei = batch_cpu.edge_index[:, mask].cpu() - start
        local_attr = (None if getattr(batch_cpu, "edge_attr", None) is None
                      else batch_cpu.edge_attr[mask].cpu())
        edges, attrs = _extract_undirected_edges(local_ei, local_attr, end - start)
        rewired = _rewire_undirected_edges(end - start, edges, attrs, generator)
        if rewired is None:
            new_ei, new_attr = local_ei.to(batch_cpu.edge_index.device), local_attr
        else:
            new_edges, new_attrs, swaps = rewired
            total_swaps += swaps
            new_ei, new_attr = _expand_undirected_edges(
                new_edges, new_attrs, batch_cpu.edge_index.device
            )
        edge_indices.append(new_ei + start)
        if new_attr is not None:
            edge_attrs.append(new_attr.to(batch_cpu.edge_attr.device))
    if total_swaps == 0:
        return None
    d.edge_index = torch.cat(edge_indices, dim=1)
    if edge_attrs:
        d.edge_attr = torch.cat(edge_attrs, dim=0).to(dtype=batch_cpu.edge_attr.dtype)
    if not _recompute_graphgps_rwse_or_skip(d, family):
        return None
    return d


def _graphormer_shortest_features(num_nodes: int, edges, attrs,
                                  max_dist: int, spatial_pos_max: int):
    from collections import deque
    adj = [[] for _ in range(num_nodes)]
    edge_code = {}
    for (u, v), attr in zip(edges, attrs):
        code = int(attr.item()) if torch.is_tensor(attr) else int(attr)
        adj[u].append(v)
        adj[v].append(u)
        edge_code[(u, v)] = code
        edge_code[(v, u)] = code
    spatial_pos = torch.zeros((num_nodes, num_nodes), dtype=torch.long)
    edge_input = torch.zeros((num_nodes, num_nodes, max_dist, 1), dtype=torch.long)
    for src in range(num_nodes):
        dist = [-1] * num_nodes
        parent = [-1] * num_nodes
        dist[src] = 0
        q = deque([src])
        while q:
            u = q.popleft()
            if dist[u] >= max_dist:
                continue
            for v in adj[u]:
                if dist[v] < 0:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
        for dst in range(num_nodes):
            if dist[dst] < 0:
                continue
            spatial_pos[src, dst] = int(dist[dst]) + 1
            if src == dst or dist[dst] <= 0:
                continue
            path = []
            cur = dst
            while cur != src and cur >= 0:
                prev = parent[cur]
                path.append(edge_code.get((prev, cur), 0))
                cur = prev
            for k, code in enumerate(reversed(path[:max_dist])):
                edge_input[src, dst, k, 0] = int(code)
    spatial_pos = torch.where(spatial_pos > spatial_pos_max,
                              torch.zeros_like(spatial_pos), spatial_pos)
    return spatial_pos, edge_input


def _reset_graphormer_attn_bias(d: Dict[str, torch.Tensor]) -> None:
    node_mask = d["node_mask"]
    B, N = node_mask.shape
    attn_bias = torch.full((B, N + 1, N + 1), float("-inf"),
                           dtype=d["attn_bias"].dtype)
    for bidx, n in enumerate(node_mask.sum(dim=1).cpu().long().tolist()):
        n = int(n)
        attn_bias[bidx, :n + 1, :n + 1] = 0.0
        if n + 1 < N + 1:
            attn_bias[bidx, n + 1:, :n + 1] = 0.0
    d["attn_bias"] = attn_bias.to(d["attn_bias"].device)


def _rewire_graphormer_topology(batch_cpu: GraphormerBatchAdapter, generator=None):
    d = batch_cpu.clone()
    cfg = getattr(batch_cpu, "_graphormer_cfg", None)
    max_dist = int(d.d["edge_input"].size(3))
    spatial_pos_max = 1024
    total_swaps = 0
    for bidx, n in enumerate(batch_cpu.counts.cpu().long().tolist()):
        n = int(n)
        sp = batch_cpu.d["spatial_pos"][bidx, :n, :n].cpu()
        ei = batch_cpu.d["edge_input"][bidx, :n, :n].cpu()
        edges, attrs = [], []
        for u in range(n):
            for v in range(u + 1, n):
                if int(sp[u, v].item()) == 2 or int(sp[v, u].item()) == 2:
                    code = ei[u, v, 0, 0]
                    if int(code.item()) == 0:
                        code = ei[v, u, 0, 0]
                    edges.append((u, v))
                    attrs.append(code.clone())
        rewired = _rewire_undirected_edges(n, edges, attrs, generator)
        if rewired is None:
            continue
        new_edges, new_attrs, swaps = rewired
        total_swaps += swaps
        new_sp, new_ei = _graphormer_shortest_features(
            n, new_edges, new_attrs, max_dist=max_dist,
            spatial_pos_max=spatial_pos_max,
        )
        d.d["spatial_pos"][bidx, :n, :n] = new_sp.to(d.d["spatial_pos"].device)
        d.d["edge_input"][bidx, :n, :n] = new_ei.to(d.d["edge_input"].device)
    if total_swaps == 0:
        return None
    _reset_graphormer_attn_bias(d.d)
    return d


def _csa_pair_features_from_local_edges(num_nodes: int, edge_index: torch.Tensor,
                                        edge_attr: torch.Tensor, device):
    A = torch.zeros((num_nodes, num_nodes), dtype=torch.float32, device=device)
    if edge_index.numel() > 0:
        src, dst = edge_index.to(device)
        A[src, dst] = 1.0
    A = torch.maximum(A, A.t())
    A.fill_diagonal_(0.0)
    degree = A.sum(dim=1)
    W = torch.zeros_like(A)
    nz = degree > 0
    W[nz] = A[nz] / degree[nz].unsqueeze(1)
    powers = []
    P = W.clone()
    for _ in range(CSA_K_WALK):
        powers.append(P.clone())
        P = P @ W
    rwse = torch.stack([Pk.diagonal() for Pk in powers], dim=-1).float()
    walk_sum = torch.stack([Pk + Pk.t() for Pk in powers], dim=-1).float()
    spd_cls = _csa_bfs_spd_classes(A.cpu() > 0, CSA_D_MAX_SPD).to(device)
    spd_oh = F.one_hot(spd_cls.clamp(max=CSA_D_MAX_SPD),
                       num_classes=CSA_D_MAX_SPD + 1).float()
    bond_oh = torch.zeros((num_nodes, num_nodes, CSA_NUM_BOND_TYPES),
                          dtype=torch.float32, device=device)
    if edge_index.numel() > 0:
        src, dst = edge_index.to(device)
        attr = edge_attr.to(device).long().clamp(0, CSA_NUM_BOND_TYPES - 1)
        bond_oh[src, dst, attr] = 1.0
    pair_xi = torch.cat([spd_oh, walk_sum, bond_oh], dim=-1).float()
    return rwse, pair_xi, degree.float()


def _rewire_csa_topology(batch_cpu: CSABatchAdapter, generator=None):
    d = batch_cpu.clone()
    b0, b = batch_cpu.b, d.b
    edge_gid = _edge_graph_ids_from_csa(batch_cpu)
    edge_indices, edge_attrs, rwse_chunks, degree_chunks = [], [], [], []
    total_swaps = 0
    for g in range(b0.num_graphs):
        node_idx = torch.nonzero(b0.batch_index.cpu() == g, as_tuple=False).view(-1)
        n = int(node_idx.numel())
        start = int(node_idx[0].item())
        eidx = torch.nonzero(edge_gid == g, as_tuple=False).view(-1)
        local_ei = b0.edge_index[:, eidx].cpu() - start
        local_attr = b0.edge_attr[eidx].cpu()
        edges, attrs = _extract_undirected_edges(local_ei, local_attr, n)
        rewired = _rewire_undirected_edges(n, edges, attrs, generator)
        if rewired is None:
            new_ei, new_attr = local_ei.to(b.edge_index.device), local_attr.to(b.edge_attr.device)
        else:
            new_edges, new_attrs, swaps = rewired
            total_swaps += swaps
            new_ei, new_attr = _expand_undirected_edges(
                new_edges, new_attrs, b.edge_index.device
            )
        rwse, pair_xi, degree = _csa_pair_features_from_local_edges(
            n, new_ei.cpu(), new_attr.cpu(), b.pair_xi.device
        )
        edge_indices.append(new_ei + start)
        edge_attrs.append(new_attr.to(b.edge_attr.device))
        rwse_chunks.append(rwse.to(b.rwse.device, dtype=b.rwse.dtype))
        degree_chunks.append(degree.to(b.degree.device, dtype=b.degree.dtype))
        b.pair_xi[g, :n, :n] = pair_xi.to(b.pair_xi.device, dtype=b.pair_xi.dtype)
    if total_swaps == 0:
        return None
    b.edge_index = torch.cat(edge_indices, dim=1)
    b.edge_attr = torch.cat(edge_attrs, dim=0).to(dtype=b.edge_attr.dtype)
    b.rwse = torch.cat(rwse_chunks, dim=0)
    b.degree = torch.cat(degree_chunks, dim=0)
    return d


def _v19_pair_features_from_local_edges(num_nodes: int, edge_index: torch.Tensor,
                                        edge_attr: torch.Tensor, device):
    A = torch.zeros((num_nodes, num_nodes), dtype=torch.float32, device=device)
    if edge_index.numel() > 0:
        src, dst = edge_index.to(device)
        A[src, dst] = 1.0
    A = torch.maximum(A, A.t())
    A.fill_diagonal_(0.0)
    degree = A.sum(dim=1)
    W = torch.zeros_like(A)
    nz = degree > 0
    W[nz] = A[nz] / degree[nz].unsqueeze(1)
    powers = []
    P = W.clone()
    for _ in range(V19_K_WALK):
        powers.append(P.clone())
        P = P @ W
    rwse = torch.stack([Pk.diagonal() for Pk in powers], dim=-1).float()
    walk_sum = torch.stack([Pk + Pk.t() for Pk in powers], dim=-1).float()
    ring_pair = _v19_compute_ring_pair_features(
        A.detach().cpu() > 0
    ).to(device=device)
    spd_cls = _v19_bfs_spd_classes(A.detach().cpu() > 0, V19_D_MAX_SPD).to(device)
    spd_oh = F.one_hot(
        spd_cls.clamp(max=V19_D_MAX_SPD),
        num_classes=V19_D_MAX_SPD + 1,
    ).float()
    bond_oh = torch.zeros((num_nodes, num_nodes, V19_NUM_BOND_TYPES),
                          dtype=torch.float32, device=device)
    if edge_index.numel() > 0:
        src, dst = edge_index.to(device)
        attr = edge_attr.to(device).long().clamp(0, V19_NUM_BOND_TYPES - 1)
        bond_oh[src, dst, attr] = 1.0
    sym = torch.cat([spd_oh, walk_sum, bond_oh], dim=-1)
    pair_xi = torch.cat([ring_pair.float(), sym], dim=-1).float()
    return rwse, pair_xi, degree.float()


def _rewire_v19_topology(batch_cpu: V19BatchAdapter, generator=None):
    d = batch_cpu.clone()
    b0, b = batch_cpu.b, d.b
    edge_gid = _edge_graph_ids_from_v19(batch_cpu)
    edge_indices, edge_attrs, rwse_chunks, degree_chunks = [], [], [], []
    total_swaps = 0
    for g in range(b0.num_graphs):
        node_idx = torch.nonzero(b0.batch_index.cpu() == g, as_tuple=False).view(-1)
        n = int(node_idx.numel())
        start = int(node_idx[0].item())
        eidx = torch.nonzero(edge_gid == g, as_tuple=False).view(-1)
        local_ei = b0.edge_index[:, eidx].cpu() - start
        local_attr = b0.edge_attr[eidx].cpu()
        edges, attrs = _extract_undirected_edges(local_ei, local_attr, n)
        rewired = _rewire_undirected_edges(n, edges, attrs, generator)
        if rewired is None:
            new_ei = local_ei.to(b.edge_index.device)
            new_attr = local_attr.to(b.edge_attr.device)
        else:
            new_edges, new_attrs, swaps = rewired
            total_swaps += swaps
            new_ei, new_attr = _expand_undirected_edges(
                new_edges, new_attrs, b.edge_index.device
            )
        rwse, pair_xi, degree = _v19_pair_features_from_local_edges(
            n, new_ei.cpu(), new_attr.cpu(), b.pair_xi.device
        )
        edge_indices.append(new_ei + start)
        edge_attrs.append(new_attr.to(b.edge_attr.device))
        rwse_chunks.append(rwse.to(b.rwse.device, dtype=b.rwse.dtype))
        degree_chunks.append(degree.to(b.degree.device, dtype=b.degree.dtype))
        b.pair_xi[g, :n, :n] = pair_xi.to(b.pair_xi.device, dtype=b.pair_xi.dtype)
    if total_swaps == 0:
        return None
    b.edge_index = torch.cat(edge_indices, dim=1)
    b.edge_attr = torch.cat(edge_attrs, dim=0).to(dtype=b.edge_attr.dtype)
    b.rwse = torch.cat(rwse_chunks, dim=0)
    b.degree = torch.cat(degree_chunks, dim=0)
    b.degree_log = torch.log1p(b.degree)
    return d


def make_degree_preserving_topology_variant(batch_cpu, perm_bundle, family):
    """Degree-preserving double-edge-swap topology counterfactual.

    Derived structural channels are recomputed where the script has an exact
    local implementation. Otherwise this returns None to avoid stale encodings.
    """
    generator = perm_bundle.get("generator")
    if isinstance(batch_cpu, GraphormerBatchAdapter):
        return _rewire_graphormer_topology(batch_cpu, generator)
    if isinstance(batch_cpu, CSABatchAdapter):
        return _rewire_csa_topology(batch_cpu, generator)
    if isinstance(batch_cpu, V19BatchAdapter):
        return _rewire_v19_topology(batch_cpu, generator)
    return _rewire_pyg_like_topology(batch_cpu, family, generator)


# -----------------------------------------------------------------------------
# Core paper-faithful metrics
# -----------------------------------------------------------------------------


def pair_mask_from_layer(layer):
    if "logit_mask" in layer and layer["logit_mask"] is not None:
        return layer["logit_mask"].to(dtype=torch.bool, device=layer["logits"].device)
    nm = layer["node_mask"]
    return nm[:, None, :, None] & nm[:, None, None, :]


def transform_pair_reference(z, perm_pos):
    """Transport pair tensor by within-graph permutation:
    (T_pi Z)[new_i, new_j] = Z[old_i, old_j], where perm_pos[b, new_i] = old_i.
    """
    B, H, N, _ = z.shape
    idx = perm_pos.to(z.device)
    row_idx = idx[:, None, :, None].expand(B, H, N, N)
    z_rows = torch.gather(z, dim=2, index=row_idx)
    col_idx = idx[:, None, None, :].expand(B, H, N, N)
    return torch.gather(z_rows, dim=3, index=col_idx)


def transform_pair_mask(mask, perm_pos, heads):
    m = mask.to(dtype=torch.bool)
    if m.size(1) == 1 and heads != 1:
        m = m.expand(-1, heads, -1, -1)
    return transform_pair_reference(m, perm_pos).to(dtype=torch.bool)


def comparison_masks(clean_layer, variant_layer, perm_pos):
    """Stable mask: pair slots valid in both clean and variant.
       Follow mask:  pair slots valid after transporting clean by sigma AND in variant.
       For x-only permutation, edge structure is unchanged so both reduce to the
       same edge support; we keep the general formulation for safety.
    """
    z_var = variant_layer["logits"]
    H = int(z_var.size(1))
    m_clean = pair_mask_from_layer(clean_layer).to(device=z_var.device, dtype=torch.bool)
    m_var = pair_mask_from_layer(variant_layer).to(device=z_var.device, dtype=torch.bool)
    if m_clean.size(1) == 1 and H != 1:
        m_clean = m_clean.expand(-1, H, -1, -1)
    if m_var.size(1) == 1 and H != 1:
        m_var = m_var.expand(-1, H, -1, -1)
    m_clean_t = transform_pair_mask(m_clean, perm_pos, H).to(device=z_var.device)
    return (m_clean & m_var), (m_clean_t & m_var)


def row_center_logits(z, mask):
    m = mask.to(device=z.device, dtype=torch.bool)
    if m.size(1) == 1 and z.size(1) != 1:
        m = m.expand(-1, z.size(1), -1, -1)
    z0 = torch.where(m, torch.nan_to_num(z, nan=0.0, posinf=0.0, neginf=0.0),
                     torch.zeros_like(z))
    denom = m.sum(dim=-1, keepdim=True).clamp_min(1).to(z.dtype)
    mean = z0.sum(dim=-1, keepdim=True) / denom
    return torch.where(m, z0 - mean, torch.zeros_like(z0))


def cosine_by_head_logits(u, v, mask):
    """Cosine across (B, N_query, N_key) for each head, on row-centred logits."""
    m = mask.to(device=u.device, dtype=torch.bool)
    if m.size(1) == 1 and u.size(1) != 1:
        m = m.expand(-1, u.size(1), -1, -1)
    u0 = row_center_logits(u, m)
    v0 = row_center_logits(v, m)
    dims = (0, 2, 3)
    num = (u0 * v0).sum(dim=dims)
    den = (torch.sqrt((u0 * u0).sum(dim=dims).clamp_min(1e-12))
           * torch.sqrt((v0 * v0).sum(dim=dims).clamp_min(1e-12)))
    return (num / den.clamp_min(1e-12)).detach().cpu()


def masked_attention_from_layer(layer):
    z = layer["logits"]
    H = int(z.size(1))
    m = pair_mask_from_layer(layer).to(device=z.device, dtype=torch.bool)
    if m.size(1) == 1 and H != 1:
        m = m.expand(-1, H, -1, -1)
    z0 = torch.nan_to_num(z, nan=0.0, posinf=0.0, neginf=0.0)
    z_masked = torch.where(m, z0, torch.full_like(z0, -1.0e9))
    valid_row = m.any(dim=-1, keepdim=True)
    z_masked = torch.where(valid_row, z_masked, torch.zeros_like(z_masked))
    a = torch.softmax(z_masked, dim=-1)
    return torch.where(m & valid_row, a, torch.zeros_like(a)), m


def centered_attention_tensor_from_layer(layer):
    attn, mask = masked_attention_from_layer(layer)
    return row_center_logits(attn, mask), mask


def metric_tensor_from_layer(layer, metric_space: str, centered: bool = False):
    if centered:
        raise ValueError(
            "Centred scores must use centered_attention_tensor_from_layer() "
            "and raw_cosine_by_query_tensor(), not shifted signed cosine."
        )
    if metric_space == "attention":
        t, m = masked_attention_from_layer(layer)
        signed = False
    elif metric_space == "logits":
        t = torch.nan_to_num(layer["logits"], nan=0.0, posinf=0.0, neginf=0.0)
        H = int(t.size(1))
        m = pair_mask_from_layer(layer).to(device=t.device, dtype=torch.bool)
        if m.size(1) == 1 and H != 1:
            m = m.expand(-1, H, -1, -1)
        signed = True
    else:
        raise ValueError(f"Unknown metric_space: {metric_space}")
    return t, m, signed


def raw_cosine_by_query_tensor(u, v, mask):
    m = mask.to(device=u.device, dtype=torch.bool)
    if m.size(1) == 1 and u.size(1) != 1:
        m = m.expand(-1, u.size(1), -1, -1)
    u0 = torch.where(m, torch.nan_to_num(u, nan=0.0, posinf=0.0, neginf=0.0),
                     torch.zeros_like(u))
    v0 = torch.where(m, torch.nan_to_num(v, nan=0.0, posinf=0.0, neginf=0.0),
                     torch.zeros_like(v))
    num = (u0 * v0).sum(dim=-1)
    den = (torch.sqrt((u0 * u0).sum(dim=-1).clamp_min(1e-12))
           * torch.sqrt((v0 * v0).sum(dim=-1).clamp_min(1e-12)))
    return torch.clamp(num / den.clamp_min(1e-12), -1.0, 1.0)


def interaction_residual_norm_by_query_tensor(clean_c, var_x_c, var_pe_c, var_both_c, mask):
    m = mask.to(device=clean_c.device, dtype=torch.bool)
    if m.size(1) == 1 and clean_c.size(1) != 1:
        m = m.expand(-1, clean_c.size(1), -1, -1)
    clean0 = torch.where(m, clean_c, torch.zeros_like(clean_c))
    x0 = torch.where(m, var_x_c, torch.zeros_like(var_x_c))
    pe0 = torch.where(m, var_pe_c, torch.zeros_like(var_pe_c))
    both0 = torch.where(m, var_both_c, torch.zeros_like(var_both_c))
    delta_x = x0 - clean0
    delta_pe = pe0 - clean0
    delta_both = both0 - clean0
    interaction = both0 - x0 - pe0 + clean0
    numerator = torch.sqrt((interaction * interaction).sum(dim=-1).clamp_min(0.0))
    denominator = (
        torch.sqrt((delta_both * delta_both).sum(dim=-1).clamp_min(0.0))
        + torch.sqrt((delta_x * delta_x).sum(dim=-1).clamp_min(0.0))
        + torch.sqrt((delta_pe * delta_pe).sum(dim=-1).clamp_min(0.0))
    )
    return torch.clamp(numerator / denominator.clamp_min(1e-12), 0.0, 1.0)


def cosine_by_query_tensor(u, v, mask, signed: bool):
    m = mask.to(device=u.device, dtype=torch.bool)
    if m.size(1) == 1 and u.size(1) != 1:
        m = m.expand(-1, u.size(1), -1, -1)
    u0 = torch.where(m, torch.nan_to_num(u, nan=0.0, posinf=0.0, neginf=0.0),
                     torch.zeros_like(u))
    v0 = torch.where(m, torch.nan_to_num(v, nan=0.0, posinf=0.0, neginf=0.0),
                     torch.zeros_like(v))
    num = (u0 * v0).sum(dim=-1)
    den = (torch.sqrt((u0 * u0).sum(dim=-1).clamp_min(1e-12))
           * torch.sqrt((v0 * v0).sum(dim=-1).clamp_min(1e-12)))
    cos = num / den.clamp_min(1e-12)
    if signed:
        return torch.clamp(0.5 * (cos + 1.0), 0.0, 1.0)
    return torch.clamp(cos, 0.0, 1.0)


def moved_attention_mass_by_query(clean_layer, perm_pos):
    attn, mask = masked_attention_from_layer(clean_layer)
    ref = transform_pair_reference(attn, perm_pos)
    H = int(attn.size(1))
    ref_mask = transform_pair_mask(mask, perm_pos, H).to(device=attn.device)
    m = mask | ref_mask
    clean0 = torch.where(m, attn, torch.zeros_like(attn))
    ref0 = torch.where(m, ref, torch.zeros_like(ref))
    return torch.clamp(0.5 * torch.abs(clean0 - ref0).sum(dim=-1), 0.0, 1.0)


def node_mask_from_layer(layer):
    if "node_mask" not in layer or layer["node_mask"] is None:
        return None
    value_output = layer.get("value_output")
    if value_output is None:
        return None
    m = layer["node_mask"].to(device=value_output.device, dtype=torch.bool)
    return m[:, None, :]


def transform_node_reference(t, perm_pos):
    """Transport node tensor by within-graph permutation:
    (T_pi X)[new_i] = X[old_i], where perm_pos[b, new_i] = old_i.
    """
    B, H, N, D = t.shape
    idx = perm_pos.to(t.device)
    node_idx = idx[:, None, :, None].expand(B, H, N, D)
    return torch.gather(t, dim=2, index=node_idx)


def transform_node_mask(mask, perm_pos, heads):
    m = mask.to(dtype=torch.bool)
    if m.size(1) == 1 and heads != 1:
        m = m.expand(-1, heads, -1)
    B, H, N = m.shape
    idx = perm_pos.to(m.device)[:, None, :].expand(B, H, N)
    return torch.gather(m, dim=2, index=idx).to(dtype=torch.bool)


def comparison_node_masks(clean_layer, variant_layer, perm_pos):
    value_output = variant_layer.get("value_output")
    if value_output is None:
        return None, None
    H = int(value_output.size(1))
    m_clean = node_mask_from_layer(clean_layer)
    m_var = node_mask_from_layer(variant_layer)
    if m_clean is None or m_var is None:
        return None, None
    m_clean = m_clean.to(device=value_output.device, dtype=torch.bool)
    m_var = m_var.to(device=value_output.device, dtype=torch.bool)
    if m_clean.size(1) == 1 and H != 1:
        m_clean = m_clean.expand(-1, H, -1)
    if m_var.size(1) == 1 and H != 1:
        m_var = m_var.expand(-1, H, -1)
    m_clean_t = transform_node_mask(m_clean, perm_pos, H).to(device=value_output.device)
    return (m_clean & m_var), (m_clean_t & m_var)


def value_score_by_query_tensor(u, v, mask):
    """Signed cosine over per-head value-output vectors, mapped to [0, 1]."""
    m = mask.to(device=u.device, dtype=torch.bool)
    if m.size(1) == 1 and u.size(1) != 1:
        m = m.expand(-1, u.size(1), -1)
    u0 = torch.where(m.unsqueeze(-1), torch.nan_to_num(u), torch.zeros_like(u))
    v0 = torch.where(m.unsqueeze(-1), torch.nan_to_num(v), torch.zeros_like(v))
    num = (u0 * v0).sum(dim=-1)
    den = (torch.sqrt((u0 * u0).sum(dim=-1).clamp_min(1e-12))
           * torch.sqrt((v0 * v0).sum(dim=-1).clamp_min(1e-12)))
    cos = torch.clamp(num / den.clamp_min(1e-12), -1.0, 1.0)
    return torch.clamp(0.5 * (cos + 1.0), 0.0, 1.0), cos


def value_cosine_by_head(u, v, mask):
    m = mask.to(device=u.device, dtype=torch.bool)
    if m.size(1) == 1 and u.size(1) != 1:
        m = m.expand(-1, u.size(1), -1)
    u0 = torch.where(m.unsqueeze(-1), torch.nan_to_num(u), torch.zeros_like(u))
    v0 = torch.where(m.unsqueeze(-1), torch.nan_to_num(v), torch.zeros_like(v))
    dims = (0, 2, 3)
    num = (u0 * v0).sum(dim=dims)
    den = (torch.sqrt((u0 * u0).sum(dim=dims).clamp_min(1e-12))
           * torch.sqrt((v0 * v0).sum(dim=dims).clamp_min(1e-12)))
    return torch.clamp(num / den.clamp_min(1e-12), -1.0, 1.0).detach().cpu()


def masked_row_centered_var_by_head(z, mask):
    m = mask.to(device=z.device, dtype=torch.bool)
    if m.size(1) == 1 and z.size(1) != 1:
        m = m.expand(-1, z.size(1), -1, -1)
    centered = row_center_logits(z, m)
    denom = m.sum(dim=(0, 2, 3)).clamp_min(1).to(centered.dtype)
    mean = (centered * m.to(centered.dtype)).sum(dim=(0, 2, 3)) / denom
    diff = torch.where(m, centered - mean.view(1, -1, 1, 1), torch.zeros_like(centered))
    return (diff * diff).sum(dim=(0, 2, 3)) / denom


def cosine_to_score01(cos):
    """Map signed cosine [-1, 1] -> [0, 1] for legacy logit diagnostics."""
    return torch.clamp(0.5 * (cos + 1.0), 0.0, 1.0)


def head_entropy_rows(model_name, clean, batch_idx):
    """Per-(layer, head) clean attention entropy.
    Entropy is normalised per query row by log(#valid keys), averaged over rows
    with at least 2 valid keys. Range is [0, 1]: 0 = one-hot, 1 = uniform.
    """
    rows = []
    for layer_idx, layer in enumerate(clean["layers"]):
        z = layer["logits"]
        H = int(z.size(1))
        m = pair_mask_from_layer(layer).to(device=z.device, dtype=torch.bool)
        if m.size(1) == 1 and H != 1:
            m = m.expand(-1, H, -1, -1)
        z0 = torch.nan_to_num(z, nan=0.0, posinf=0.0, neginf=0.0)
        z_masked = torch.where(m, z0, torch.full_like(z0, -1.0e9))
        valid_row = m.any(dim=-1, keepdim=True)
        z_masked = torch.where(valid_row, z_masked, torch.zeros_like(z_masked))
        a = torch.softmax(z_masked, dim=-1)
        a = torch.where(m & valid_row, a, torch.zeros_like(a))
        k = m.sum(dim=-1).to(a.dtype)
        valid = k > 1
        ent_raw = -(torch.where(a > 0, a * torch.log(a.clamp_min(1e-12)),
                                torch.zeros_like(a))).sum(dim=-1)
        ent_norm = torch.where(valid, ent_raw / torch.log(k.clamp_min(2.0)),
                               torch.zeros_like(ent_raw))
        valid_f = valid.to(a.dtype)
        denom = valid_f.sum(dim=(0, 2)).clamp_min(1.0)
        entropy = (ent_norm * valid_f).sum(dim=(0, 2)) / denom
        for h in range(H):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": -1,
                "layer": layer_idx, "head": h,
                "metric": M_ENTROPY,
                "score": float(entropy[h].detach().cpu()),
            })
    return rows


def transport_plane_rows(model_name, clean, variant, perm_pos,
                         batch_idx, perm_idx,
                         inv_metric: str, equi_metric: str):
    """Per-(layer, head) (invariance, equivariance) score pair under one
    channel-targeted permutation.

    Cosines are on row-centred logits, then mapped from [-1,1] to [0,1] to
    match the paper's positional/symbolic plane convention.
    """
    rows = []
    for layer_idx, (c_layer, v_layer) in enumerate(zip(clean["layers"],
                                                       variant["layers"])):
        z_clean = c_layer["logits"]
        z_var = v_layer["logits"]
        z_ref = transform_pair_reference(z_clean, perm_pos)
        stable_mask, follow_mask = comparison_masks(c_layer, v_layer, perm_pos)

        inv_cos = cosine_by_head_logits(z_var, z_clean, stable_mask)
        equi_cos = cosine_by_head_logits(z_var, z_ref, follow_mask)
        inv = cosine_to_score01(inv_cos)
        equi = cosine_to_score01(equi_cos)

        H = int(inv.numel())
        for h in range(H):
            common = {"model": model_name, "batch": batch_idx, "perm": perm_idx,
                      "layer": layer_idx, "head": h}
            rows.append({**common, "metric": inv_metric,
                         "score": float(inv[h]),
                         "raw_cos": float(inv_cos[h])})
            rows.append({**common, "metric": equi_metric,
                         "score": float(equi[h]),
                         "raw_cos": float(equi_cos[h])})
    return rows


def alpha_weighted_plane_rows(model_name, clean, variant_records,
                              batch_idx, inv_metric: str, equi_metric: str,
                              cfg, centered: bool = False):
    """Alpha-weighted global-permutation metric rows.

    Each record is one actual forward pass on a globally permuted graph input.
    For every graph/head/query, permutations are weighted by the attention mass
    they move, then query scores are averaged into per-input head scores.
    """
    rows = []
    if not variant_records:
        return rows
    if cfg.metric_alpha_tau <= 0:
        raise ValueError("--metric-alpha-tau must be positive")
    for layer_idx, c_layer in enumerate(clean["layers"]):
        if centered:
            clean_t, _clean_mask = centered_attention_tensor_from_layer(c_layer)
            signed = False
        else:
            clean_t, _clean_mask, signed = metric_tensor_from_layer(
                c_layer, cfg.metric_space, centered=False
            )
        inv_scores = []
        equi_scores = []
        moved_masses = []
        valid_queries = None
        for perm_idx, perm_pos, variant in variant_records:
            v_layer = variant["layers"][layer_idx]
            if centered:
                var_t, _ = centered_attention_tensor_from_layer(v_layer)
            else:
                var_t, _, _ = metric_tensor_from_layer(
                    v_layer, cfg.metric_space, centered=False
                )
            ref_t = transform_pair_reference(clean_t, perm_pos)
            stable_mask, follow_mask = comparison_masks(c_layer, v_layer, perm_pos)
            stable_mask = stable_mask.to(device=var_t.device, dtype=torch.bool)
            follow_mask = follow_mask.to(device=var_t.device, dtype=torch.bool)
            if centered:
                inv_scores.append(raw_cosine_by_query_tensor(var_t, clean_t, stable_mask))
                equi_scores.append(raw_cosine_by_query_tensor(var_t, ref_t, follow_mask))
            else:
                inv_scores.append(cosine_by_query_tensor(var_t, clean_t, stable_mask, signed=signed))
                equi_scores.append(cosine_by_query_tensor(var_t, ref_t, follow_mask, signed=signed))
            moved_masses.append(moved_attention_mass_by_query(c_layer, perm_pos))
            row_valid = stable_mask.any(dim=-1) | follow_mask.any(dim=-1)
            valid_queries = row_valid if valid_queries is None else (valid_queries | row_valid)

        inv_stack = torch.stack(inv_scores, dim=0)
        equi_stack = torch.stack(equi_scores, dim=0)
        moved = torch.stack(moved_masses, dim=0).to(device=inv_stack.device)
        alpha = torch.softmax(moved / float(cfg.metric_alpha_tau), dim=0)
        inv_query = (alpha * inv_stack).sum(dim=0)
        equi_query = (alpha * equi_stack).sum(dim=0)
        alpha_max = alpha.max(dim=0).values
        effective_perms = 1.0 / torch.square(alpha).sum(dim=0).clamp_min(1e-12)
        if valid_queries is None:
            continue
        valid = valid_queries.to(device=inv_query.device, dtype=torch.bool)
        denom = valid.sum(dim=-1).clamp_min(1).to(inv_query.dtype)
        inv_head = (inv_query * valid.to(inv_query.dtype)).sum(dim=-1) / denom
        equi_head = (equi_query * valid.to(equi_query.dtype)).sum(dim=-1) / denom
        moved_mean = (moved.mean(dim=0) * valid.to(moved.dtype)).sum(dim=-1) / denom
        alpha_max_mean = (alpha_max * valid.to(alpha_max.dtype)).sum(dim=-1) / denom
        effective_mean = (effective_perms * valid.to(effective_perms.dtype)).sum(dim=-1) / denom

        B, H = inv_head.shape
        for b in range(B):
            for h in range(H):
                common = {
                    "model": model_name, "batch": batch_idx, "graph_in_batch": b,
                    "perm": -1, "layer": layer_idx, "head": h,
                    "metric_space": cfg.metric_space,
                    "centered": bool(centered),
                    "alpha_tau": float(cfg.metric_alpha_tau),
                    "moved_mass_mean": float(moved_mean[b, h].detach().cpu()),
                    "alpha_max_mean": float(alpha_max_mean[b, h].detach().cpu()),
                    "effective_perms_mean": float(effective_mean[b, h].detach().cpu()),
                }
                rows.append({**common, "metric": inv_metric,
                             "score": float(inv_head[b, h].detach().cpu())})
                rows.append({**common, "metric": equi_metric,
                             "score": float(equi_head[b, h].detach().cpu())})
    return rows


def alpha_weighted_mixed_attention_rows(model_name, clean, mixed_records,
                                        batch_idx, cfg):
    """Alpha-weighted mixed symbolic+structural metrics on centered attention.

    `mixed_records` contains aligned runs for the same permutation:
    (perm_idx, perm_pos, x_variant, pe_variant, joint_x_pe_variant).
    """
    rows = []
    if not mixed_records:
        return rows
    if cfg.metric_alpha_tau <= 0:
        raise ValueError("--metric-alpha-tau must be positive")
    for layer_idx, c_layer in enumerate(clean["layers"]):
        clean_c, clean_mask = centered_attention_tensor_from_layer(c_layer)
        interaction_scores = []
        joint_excess_scores = []
        moved_masses = []
        valid_queries = None
        for _perm_idx, perm_pos, var_x, var_pe, var_both in mixed_records:
            x_layer = var_x["layers"][layer_idx]
            pe_layer = var_pe["layers"][layer_idx]
            both_layer = var_both["layers"][layer_idx]
            x_c, x_mask = centered_attention_tensor_from_layer(x_layer)
            pe_c, pe_mask = centered_attention_tensor_from_layer(pe_layer)
            both_c, both_mask = centered_attention_tensor_from_layer(both_layer)
            H = int(clean_c.size(1))
            clean_ref = transform_pair_reference(clean_c, perm_pos)
            clean_ref_mask = transform_pair_mask(clean_mask, perm_pos, H).to(device=clean_c.device)
            clean_mask_h = clean_mask.to(device=clean_c.device, dtype=torch.bool)
            if clean_mask_h.size(1) == 1 and H != 1:
                clean_mask_h = clean_mask_h.expand(-1, H, -1, -1)
            x_mask = x_mask.to(device=clean_c.device, dtype=torch.bool)
            pe_mask = pe_mask.to(device=clean_c.device, dtype=torch.bool)
            both_mask = both_mask.to(device=clean_c.device, dtype=torch.bool)
            if x_mask.size(1) == 1 and H != 1:
                x_mask = x_mask.expand(-1, H, -1, -1)
            if pe_mask.size(1) == 1 and H != 1:
                pe_mask = pe_mask.expand(-1, H, -1, -1)
            if both_mask.size(1) == 1 and H != 1:
                both_mask = both_mask.expand(-1, H, -1, -1)

            x_stable = clean_mask_h & x_mask
            x_follow = clean_ref_mask & x_mask
            pe_stable = clean_mask_h & pe_mask
            pe_follow = clean_ref_mask & pe_mask
            both_follow = clean_ref_mask & both_mask
            interaction_mask = clean_mask_h & x_mask & pe_mask & both_mask

            positional_c = raw_cosine_by_query_tensor(x_c, clean_c, x_stable)
            symbolic_c = raw_cosine_by_query_tensor(x_c, clean_ref, x_follow)
            pe_invariance_c = raw_cosine_by_query_tensor(pe_c, clean_c, pe_stable)
            pe_equivariance_c = raw_cosine_by_query_tensor(pe_c, clean_ref, pe_follow)
            joint_c = raw_cosine_by_query_tensor(both_c, clean_ref, both_follow)
            best_single_c = torch.stack(
                [positional_c, symbolic_c, pe_invariance_c, pe_equivariance_c],
                dim=0,
            ).max(dim=0).values

            interaction_scores.append(
                interaction_residual_norm_by_query_tensor(
                    clean_c, x_c, pe_c, both_c, interaction_mask
                )
            )
            joint_excess_scores.append(joint_c - best_single_c)
            moved_masses.append(moved_attention_mass_by_query(c_layer, perm_pos))
            row_valid = interaction_mask.any(dim=-1) | both_follow.any(dim=-1)
            valid_queries = row_valid if valid_queries is None else (valid_queries | row_valid)

        if valid_queries is None:
            continue
        interaction_stack = torch.stack(interaction_scores, dim=0)
        joint_excess_stack = torch.stack(joint_excess_scores, dim=0)
        moved = torch.stack(moved_masses, dim=0).to(device=interaction_stack.device)
        alpha = torch.softmax(moved / float(cfg.metric_alpha_tau), dim=0)
        interaction_query = (alpha * interaction_stack).sum(dim=0)
        joint_excess_query = (alpha * joint_excess_stack).sum(dim=0)
        alpha_max = alpha.max(dim=0).values
        effective_perms = 1.0 / torch.square(alpha).sum(dim=0).clamp_min(1e-12)
        valid = valid_queries.to(device=interaction_query.device, dtype=torch.bool)
        denom = valid.sum(dim=-1).clamp_min(1).to(interaction_query.dtype)
        interaction_head = (interaction_query * valid.to(interaction_query.dtype)).sum(dim=-1) / denom
        joint_excess_head = (
            joint_excess_query * valid.to(joint_excess_query.dtype)
        ).sum(dim=-1) / denom
        moved_mean = (moved.mean(dim=0) * valid.to(moved.dtype)).sum(dim=-1) / denom
        alpha_max_mean = (alpha_max * valid.to(alpha_max.dtype)).sum(dim=-1) / denom
        effective_mean = (effective_perms * valid.to(effective_perms.dtype)).sum(dim=-1) / denom

        B, H = interaction_head.shape
        for b in range(B):
            for h in range(H):
                common = {
                    "model": model_name, "batch": batch_idx, "graph_in_batch": b,
                    "perm": -1, "layer": layer_idx, "head": h,
                    "metric_space": "attention",
                    "centered": True,
                    "alpha_tau": float(cfg.metric_alpha_tau),
                    "moved_mass_mean": float(moved_mean[b, h].detach().cpu()),
                    "alpha_max_mean": float(alpha_max_mean[b, h].detach().cpu()),
                    "effective_perms_mean": float(effective_mean[b, h].detach().cpu()),
                }
                rows.append({
                    **common,
                    "metric": M_INTERACTION_RESIDUAL_CENTERED,
                    "score": float(interaction_head[b, h].detach().cpu()),
                })
                rows.append({
                    **common,
                    "metric": M_JOINT_EQUIVARIANCE_EXCESS_CENTERED,
                    "score": float(joint_excess_head[b, h].detach().cpu()),
                })
    return rows


def alpha_weighted_value_output_plane_rows(model_name, clean, variant_records,
                                           batch_idx, inv_metric: str,
                                           equi_metric: str, cfg):
    """Alpha-weighted invariance/equivariance scores on per-head value outputs."""
    rows = []
    if not variant_records:
        return rows
    if cfg.metric_alpha_tau <= 0:
        raise ValueError("--metric-alpha-tau must be positive")
    for layer_idx, c_layer in enumerate(clean["layers"]):
        clean_t = c_layer.get("value_output")
        if clean_t is None:
            continue
        inv_scores = []
        equi_scores = []
        moved_masses = []
        valid_queries = None
        raw_inv_scores = []
        raw_equi_scores = []
        for _perm_idx, perm_pos, variant in variant_records:
            v_layer = variant["layers"][layer_idx]
            var_t = v_layer.get("value_output")
            if var_t is None:
                continue
            ref_t = transform_node_reference(clean_t, perm_pos)
            stable_mask, follow_mask = comparison_node_masks(c_layer, v_layer, perm_pos)
            if stable_mask is None or follow_mask is None:
                continue
            stable_mask = stable_mask.to(device=var_t.device, dtype=torch.bool)
            follow_mask = follow_mask.to(device=var_t.device, dtype=torch.bool)
            inv_q, inv_raw = value_score_by_query_tensor(var_t, clean_t, stable_mask)
            equi_q, equi_raw = value_score_by_query_tensor(var_t, ref_t, follow_mask)
            inv_scores.append(inv_q)
            equi_scores.append(equi_q)
            raw_inv_scores.append(inv_raw)
            raw_equi_scores.append(equi_raw)
            moved_masses.append(moved_attention_mass_by_query(c_layer, perm_pos))
            row_valid = stable_mask | follow_mask
            valid_queries = row_valid if valid_queries is None else (valid_queries | row_valid)

        if not inv_scores or valid_queries is None:
            continue
        inv_stack = torch.stack(inv_scores, dim=0)
        equi_stack = torch.stack(equi_scores, dim=0)
        raw_inv_stack = torch.stack(raw_inv_scores, dim=0)
        raw_equi_stack = torch.stack(raw_equi_scores, dim=0)
        moved = torch.stack(moved_masses, dim=0).to(device=inv_stack.device)
        alpha = torch.softmax(moved / float(cfg.metric_alpha_tau), dim=0)
        inv_query = (alpha * inv_stack).sum(dim=0)
        equi_query = (alpha * equi_stack).sum(dim=0)
        inv_raw_query = (alpha * raw_inv_stack).sum(dim=0)
        equi_raw_query = (alpha * raw_equi_stack).sum(dim=0)
        alpha_max = alpha.max(dim=0).values
        effective_perms = 1.0 / torch.square(alpha).sum(dim=0).clamp_min(1e-12)
        valid = valid_queries.to(device=inv_query.device, dtype=torch.bool)
        denom = valid.sum(dim=-1).clamp_min(1).to(inv_query.dtype)
        inv_head = (inv_query * valid.to(inv_query.dtype)).sum(dim=-1) / denom
        equi_head = (equi_query * valid.to(equi_query.dtype)).sum(dim=-1) / denom
        inv_raw_head = (inv_raw_query * valid.to(inv_raw_query.dtype)).sum(dim=-1) / denom
        equi_raw_head = (equi_raw_query * valid.to(equi_raw_query.dtype)).sum(dim=-1) / denom
        moved_mean = (moved.mean(dim=0) * valid.to(moved.dtype)).sum(dim=-1) / denom
        alpha_max_mean = (alpha_max * valid.to(alpha_max.dtype)).sum(dim=-1) / denom
        effective_mean = (effective_perms * valid.to(effective_perms.dtype)).sum(dim=-1) / denom

        B, H = inv_head.shape
        for b in range(B):
            for h in range(H):
                common = {
                    "model": model_name, "batch": batch_idx, "graph_in_batch": b,
                    "perm": -1, "layer": layer_idx, "head": h,
                    "metric_space": "value_output",
                    "centered": False,
                    "alpha_tau": float(cfg.metric_alpha_tau),
                    "moved_mass_mean": float(moved_mean[b, h].detach().cpu()),
                    "alpha_max_mean": float(alpha_max_mean[b, h].detach().cpu()),
                    "effective_perms_mean": float(effective_mean[b, h].detach().cpu()),
                }
                rows.append({**common, "metric": inv_metric,
                             "score": float(inv_head[b, h].detach().cpu()),
                             "raw_cos": float(inv_raw_head[b, h].detach().cpu())})
                rows.append({**common, "metric": equi_metric,
                             "score": float(equi_head[b, h].detach().cpu()),
                             "raw_cos": float(equi_raw_head[b, h].detach().cpu())})
    return rows


# Metric names. Core scores use alpha-weighted global permutations.
M_POSITIONAL = "positional_score"     # node-content invariance
M_SYMBOLIC = "symbolic_score"         # node-content equivariance
M_PE_INVARIANT = "pe_invariance"      # structural-feature invariance
M_PE_EQUIVARIANT = "pe_equivariance"  # structural-feature equivariance
M_POSITIONAL_CENTERED = "positional_score_centered"
M_SYMBOLIC_CENTERED = "symbolic_score_centered"
M_PE_INVARIANT_CENTERED = "pe_invariance_centered"
M_PE_EQUIVARIANT_CENTERED = "pe_equivariance_centered"
M_INTERACTION_RESIDUAL_CENTERED = "interaction_residual_norm_centered"
M_JOINT_EQUIVARIANCE_EXCESS_CENTERED = "joint_equivariance_excess_centered"
M_POSITIONAL_VALUE = "positional_score_value_output"
M_SYMBOLIC_VALUE = "symbolic_score_value_output"
M_PE_INVARIANT_VALUE = "pe_invariance_value_output"
M_PE_EQUIVARIANT_VALUE = "pe_equivariance_value_output"
M_ENTANGLEMENT = "entanglement_score" # non-additivity of (x, PE) interaction
M_ENTANGLEMENT_VALUE = "entanglement_score_value_output"
M_ENTROPY = "entropy_norm"            # clean attention entropy in [0,1]
M_RELABEL_EQUIVARIANT = "relabel_equivariance"      # graph-isomorphism sanity check
M_RELABEL_EQUIVARIANT_VALUE = "relabel_equivariance_value_output"
M_EDGE_LABEL_SENS = "edge_label_sensitivity"        # fixed-topology edge-label perturb
M_PAIR_STRUCT_SENS = "pair_structure_sensitivity"   # pair structural channel perturb
M_TOPOLOGY_SENS = "topology_rewire_sensitivity"     # degree-preserving topology perturb
M_EDGE_LABEL_SENS_VALUE = "edge_label_sensitivity_value_output"
M_PAIR_STRUCT_SENS_VALUE = "pair_structure_sensitivity_value_output"
M_TOPOLOGY_SENS_VALUE = "topology_rewire_sensitivity_value_output"
M_LOGIT_CONTENT_VAR = "logit_content_variance"
M_LOGIT_BIAS_VAR = "logit_bias_variance"
M_LOGIT_TOTAL_VAR = "logit_total_variance"
M_LOGIT_BIAS_CONTENT_VAR_RATIO = "logit_bias_to_content_variance_ratio"
M_LOGIT_BIAS_CONTENT_VAR_LOG10 = "logit_bias_to_content_variance_log10"
M_LOGIT_BIAS_VARIANCE_FRACTION = "logit_bias_variance_fraction"
M_BIAS_ABLATION_ATTENTION_TV = "bias_ablation_attention_tv"
M_DOT_PRODUCT_ABLATION_ATTENTION_TV = "dot_product_ablation_attention_tv"
M_BIAS_VALUE_TRANSPORT_EFFECT = "bias_value_transport_effect"
M_STRUCT_VALUE_ADD_EFFECT = "struct_value_add_effect"
M_TOTAL_STRUCT_TRANSPORT_EFFECT = "total_struct_transport_effect"
M_BIAS_VALUE_TRANSPORT_RELATIVE_NORM = "bias_value_transport_relative_norm"
M_STRUCT_VALUE_ADD_RELATIVE_NORM = "struct_value_add_relative_norm"
M_TOTAL_STRUCT_TRANSPORT_RELATIVE_NORM = "total_struct_transport_relative_norm"


def cosine_to_sensitivity01(cos):
    """Map cosine agreement to a sensitivity score: 0 = unchanged, 1 = flipped."""
    return torch.clamp(0.5 * (1.0 - cos), 0.0, 1.0)


def relabel_equivariance_rows(model_name, clean, variant, perm_pos,
                              batch_idx, perm_idx,
                              metric: str = M_RELABEL_EQUIVARIANT,
                              metric_space: str = "attention"):
    """Graph-isomorphism sanity check. A correctly equivariant head should
    match the clean attention pattern transported by the relabeling.
    """
    rows = []
    for layer_idx, (c_layer, v_layer) in enumerate(zip(clean["layers"],
                                                       variant["layers"])):
        clean_t, clean_mask, signed = metric_tensor_from_layer(
            c_layer, metric_space, centered=False
        )
        var_t, var_mask, _ = metric_tensor_from_layer(
            v_layer, metric_space, centered=False
        )
        H = int(var_t.size(1))
        ref_t = transform_pair_reference(clean_t, perm_pos)
        m_ref = transform_pair_mask(clean_mask, perm_pos, H).to(device=var_t.device)
        m_var = var_mask.to(device=var_t.device, dtype=torch.bool)
        if m_var.size(1) == 1 and H != 1:
            m_var = m_var.expand(-1, H, -1, -1)
        mask = m_ref & m_var
        score_q = cosine_by_query_tensor(var_t, ref_t, mask, signed=signed)
        valid = mask.any(dim=-1)
        denom = valid.sum(dim=(0, 2)).clamp_min(1).to(score_q.dtype)
        score = (score_q * valid.to(score_q.dtype)).sum(dim=(0, 2)) / denom
        for h in range(int(score.numel())):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": perm_idx,
                "layer": layer_idx, "head": h, "metric": metric,
                "score": float(score[h].detach().cpu()),
            })
    return rows


def relabel_value_output_rows(model_name, clean, variant, perm_pos,
                              batch_idx, perm_idx,
                              metric: str = M_RELABEL_EQUIVARIANT_VALUE):
    rows = []
    for layer_idx, (c_layer, v_layer) in enumerate(zip(clean["layers"],
                                                       variant["layers"])):
        clean_t = c_layer.get("value_output")
        var_t = v_layer.get("value_output")
        if clean_t is None or var_t is None:
            continue
        H = int(var_t.size(1))
        ref_t = transform_node_reference(clean_t, perm_pos)
        clean_mask = node_mask_from_layer(c_layer)
        var_mask = node_mask_from_layer(v_layer)
        if clean_mask is None or var_mask is None:
            continue
        m_ref = transform_node_mask(clean_mask, perm_pos, H).to(device=var_t.device)
        m_var = var_mask.to(device=var_t.device, dtype=torch.bool)
        if m_var.size(1) == 1 and H != 1:
            m_var = m_var.expand(-1, H, -1)
        mask = m_ref & m_var
        score_q, raw_q = value_score_by_query_tensor(var_t, ref_t, mask)
        valid = mask.to(device=score_q.device, dtype=torch.bool)
        denom = valid.sum(dim=(0, 2)).clamp_min(1).to(score_q.dtype)
        score = (score_q * valid.to(score_q.dtype)).sum(dim=(0, 2)) / denom
        raw = (raw_q * valid.to(raw_q.dtype)).sum(dim=(0, 2)) / denom
        for h in range(int(score.numel())):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": perm_idx,
                "layer": layer_idx, "head": h, "metric": metric,
                "metric_space": "value_output",
                "score": float(score[h].detach().cpu()),
                "raw_cos": float(raw[h].detach().cpu()),
            })
    return rows


def bias_decomposition_rows(model_name, clean, batch_idx):
    """Per-head row-centred logit variance split: content QK vs explicit bias."""
    rows = []
    eps = 1e-12
    for layer_idx, layer in enumerate(clean["layers"]):
        content = layer.get("content_logits")
        bias = layer.get("bias_logits")
        if content is None or bias is None:
            continue
        total = layer["logits"]
        mask = pair_mask_from_layer(layer).to(device=total.device, dtype=torch.bool)
        content_var = masked_row_centered_var_by_head(content, mask)
        bias_var = masked_row_centered_var_by_head(bias, mask)
        total_var = masked_row_centered_var_by_head(total, mask)
        ratio = bias_var / content_var.clamp_min(eps)
        log_ratio = torch.log10(ratio.clamp_min(eps))
        frac = bias_var / (bias_var + content_var).clamp_min(eps)
        H = int(total.size(1))
        for h in range(H):
            common = {
                "model": model_name, "batch": batch_idx, "perm": -1,
                "layer": layer_idx, "head": h,
                "metric_space": "logits",
                "centered": True,
            }
            rows.append({**common, "metric": M_LOGIT_CONTENT_VAR,
                         "score": float(content_var[h].detach().cpu())})
            rows.append({**common, "metric": M_LOGIT_BIAS_VAR,
                         "score": float(bias_var[h].detach().cpu())})
            rows.append({**common, "metric": M_LOGIT_TOTAL_VAR,
                         "score": float(total_var[h].detach().cpu())})
            rows.append({**common, "metric": M_LOGIT_BIAS_CONTENT_VAR_RATIO,
                         "score": float(ratio[h].detach().cpu())})
            rows.append({**common, "metric": M_LOGIT_BIAS_CONTENT_VAR_LOG10,
                         "score": float(log_ratio[h].detach().cpu())})
            rows.append({**common, "metric": M_LOGIT_BIAS_VARIANCE_FRACTION,
                         "score": float(frac[h].detach().cpu())})
    return rows


def masked_softmax_from_logits(z, mask):
    """Softmax over valid keys for an arbitrary dense [B,H,N,N] logit tensor."""
    H = int(z.size(1))
    m = mask.to(device=z.device, dtype=torch.bool)
    if m.size(1) == 1 and H != 1:
        m = m.expand(-1, H, -1, -1)
    z0 = torch.nan_to_num(z, nan=0.0, posinf=0.0, neginf=0.0)
    z_masked = torch.where(m, z0, torch.full_like(z0, -1.0e9))
    valid_row = m.any(dim=-1, keepdim=True)
    z_masked = torch.where(valid_row, z_masked, torch.zeros_like(z_masked))
    a = torch.softmax(z_masked, dim=-1)
    return torch.where(m & valid_row, a, torch.zeros_like(a)), m


def attention_tv_by_head(a, b, mask):
    m = mask.to(device=a.device, dtype=torch.bool)
    if m.size(1) == 1 and a.size(1) != 1:
        m = m.expand(-1, a.size(1), -1, -1)
    tv_q = 0.5 * torch.abs(
        torch.where(m, a, torch.zeros_like(a))
        - torch.where(m, b, torch.zeros_like(b))
    ).sum(dim=-1)
    valid = m.any(dim=-1)
    denom = valid.sum(dim=(0, 2)).clamp_min(1).to(tv_q.dtype)
    return (tv_q * valid.to(tv_q.dtype)).sum(dim=(0, 2)) / denom


def attention_ablation_rows(model_name, clean, batch_idx):
    """Causal softmax-space effect of removing explicit bias or QK logits.

    For GraphGPS, there is no explicit attention bias. We therefore treat the
    bias tensor as zero: bias ablation has zero effect, while dot-product
    ablation compares the learned attention to uniform valid-key attention.
    """
    rows = []
    for layer_idx, layer in enumerate(clean["layers"]):
        total = layer["logits"]
        mask = pair_mask_from_layer(layer).to(device=total.device, dtype=torch.bool)
        content = layer.get("content_logits")
        bias = layer.get("bias_logits")
        if content is None:
            content = total
        if bias is None:
            bias = torch.zeros_like(total)

        full_attn, mask_h = masked_softmax_from_logits(total, mask)
        no_bias_attn, _ = masked_softmax_from_logits(content, mask_h)
        no_dot_attn, _ = masked_softmax_from_logits(bias, mask_h)
        bias_tv = attention_tv_by_head(full_attn, no_bias_attn, mask_h)
        dot_tv = attention_tv_by_head(full_attn, no_dot_attn, mask_h)
        H = int(total.size(1))
        for h in range(H):
            common = {
                "model": model_name, "batch": batch_idx, "perm": -1,
                "layer": layer_idx, "head": h,
                "metric_space": "attention",
            }
            rows.append({**common, "metric": M_BIAS_ABLATION_ATTENTION_TV,
                         "score": float(bias_tv[h].detach().cpu())})
            rows.append({**common, "metric": M_DOT_PRODUCT_ABLATION_ATTENTION_TV,
                         "score": float(dot_tv[h].detach().cpu())})
    return rows


def value_counterfactual_effect_by_head(full, counterfactual, mask):
    m = mask.to(device=full.device, dtype=torch.bool)
    if m.size(1) == 1 and full.size(1) != 1:
        m = m.expand(-1, full.size(1), -1)
    full0 = torch.where(m.unsqueeze(-1), torch.nan_to_num(full), torch.zeros_like(full))
    cf0 = torch.where(
        m.unsqueeze(-1), torch.nan_to_num(counterfactual), torch.zeros_like(counterfactual)
    )
    dims = (0, 2, 3)
    num = (full0 * cf0).sum(dim=dims)
    full_norm = torch.sqrt((full0 * full0).sum(dim=dims).clamp_min(1e-12))
    cf_norm = torch.sqrt((cf0 * cf0).sum(dim=dims).clamp_min(1e-12))
    cos = torch.clamp(num / (full_norm * cf_norm).clamp_min(1e-12), -1.0, 1.0)
    diff = full0 - cf0
    rel = torch.sqrt((diff * diff).sum(dim=dims).clamp_min(0.0)) / full_norm.clamp_min(1e-12)
    return 1.0 - cos, rel


def value_transport_counterfactual_rows(model_name, clean, batch_idx):
    """Value-output effect of explicit structural attention/value channels."""
    rows = []
    specs = [
        ("value_output_no_bias_attn",
         M_BIAS_VALUE_TRANSPORT_EFFECT,
         M_BIAS_VALUE_TRANSPORT_RELATIVE_NORM),
        ("value_output_no_struct_value",
         M_STRUCT_VALUE_ADD_EFFECT,
         M_STRUCT_VALUE_ADD_RELATIVE_NORM),
        ("value_output_no_struct_all",
         M_TOTAL_STRUCT_TRANSPORT_EFFECT,
         M_TOTAL_STRUCT_TRANSPORT_RELATIVE_NORM),
    ]
    for layer_idx, layer in enumerate(clean["layers"]):
        full = layer.get("value_output")
        if full is None:
            continue
        node_mask = node_mask_from_layer(layer)
        if node_mask is None:
            continue
        node_mask = node_mask.to(device=full.device, dtype=torch.bool)
        H = int(full.size(1))
        if node_mask.size(1) == 1 and H != 1:
            node_mask = node_mask.expand(-1, H, -1)
        for key, effect_metric, rel_metric in specs:
            counter = layer.get(key)
            if counter is None:
                continue
            effect, rel = value_counterfactual_effect_by_head(full, counter, node_mask)
            for h in range(H):
                common = {
                    "model": model_name, "batch": batch_idx, "perm": -1,
                    "layer": layer_idx, "head": h,
                    "metric_space": "value_output",
                }
                rows.append({**common, "metric": effect_metric,
                             "score": float(effect[h].detach().cpu())})
                rows.append({**common, "metric": rel_metric,
                             "score": float(rel[h].detach().cpu())})
    return rows


def sensitivity_rows(model_name, clean, variant, batch_idx, perm_idx,
                     metric: str, use_union_mask: bool = False):
    """Head-logit sensitivity to a non-symmetry counterfactual.

    Uses row-centred logits. For fixed-support channel interventions, compare
    on the intersection of valid pair slots. For topology rewires, use the
    union so changed sparse support contributes to the score.
    """
    rows = []
    for layer_idx, (c_layer, v_layer) in enumerate(zip(clean["layers"],
                                                       variant["layers"])):
        z_clean = c_layer["logits"]
        z_var = v_layer["logits"]
        H = int(z_var.size(1))
        m_clean = pair_mask_from_layer(c_layer).to(device=z_var.device,
                                                   dtype=torch.bool)
        m_var = pair_mask_from_layer(v_layer).to(device=z_var.device,
                                                 dtype=torch.bool)
        if m_clean.size(1) == 1 and H != 1:
            m_clean = m_clean.expand(-1, H, -1, -1)
        if m_var.size(1) == 1 and H != 1:
            m_var = m_var.expand(-1, H, -1, -1)
        mask = (m_clean | m_var) if use_union_mask else (m_clean & m_var)
        cos = cosine_by_head_logits(z_var, z_clean, mask)
        score = cosine_to_sensitivity01(cos)
        for h in range(int(score.numel())):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": perm_idx,
                "layer": layer_idx, "head": h, "metric": metric,
                "score": float(score[h]), "raw_cos": float(cos[h]),
            })
    return rows


def sensitivity_value_output_rows(model_name, clean, variant, batch_idx, perm_idx,
                                  metric: str, use_union_mask: bool = False):
    rows = []
    for layer_idx, (c_layer, v_layer) in enumerate(zip(clean["layers"],
                                                       variant["layers"])):
        clean_t = c_layer.get("value_output")
        var_t = v_layer.get("value_output")
        if clean_t is None or var_t is None:
            continue
        H = int(var_t.size(1))
        m_clean = node_mask_from_layer(c_layer)
        m_var = node_mask_from_layer(v_layer)
        if m_clean is None or m_var is None:
            continue
        m_clean = m_clean.to(device=var_t.device, dtype=torch.bool)
        m_var = m_var.to(device=var_t.device, dtype=torch.bool)
        if m_clean.size(1) == 1 and H != 1:
            m_clean = m_clean.expand(-1, H, -1)
        if m_var.size(1) == 1 and H != 1:
            m_var = m_var.expand(-1, H, -1)
        mask = (m_clean | m_var) if use_union_mask else (m_clean & m_var)
        cos = value_cosine_by_head(var_t, clean_t, mask)
        score = cosine_to_sensitivity01(cos)
        for h in range(int(score.numel())):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": perm_idx,
                "layer": layer_idx, "head": h, "metric": metric,
                "metric_space": "value_output",
                "score": float(score[h]), "raw_cos": float(cos[h]),
            })
    return rows


def entanglement_rows(model_name, clean, var_x, var_pe, var_both,
                      batch_idx, perm_idx):
    """Per-(layer, head) non-additivity of the logit in (x, PE).

    For a head whose logit decomposes additively as L(x, PE) = f(x) + g(PE),
    the four-cell ANOVA-style interaction Δ vanishes:

        Δ_both := Z_both - Z_clean = (Z_x - Z_clean) + (Z_pe - Z_clean)
                                   =  Δ_x + Δ_pe

    where Z_x, Z_pe, Z_both use the SAME sigma applied to x-only, PE-only,
    and both jointly. We score per head via:

        score = 0.5 * (1 - cos(Δ_both, Δ_x + Δ_pe))   in [0, 1]

    on row-centred logits over valid pair slots:

        0   = perfectly additive in (x, PE)
        0.5 = orthogonal (joint effect uncorrelated with linear sum of singles)
        1   = anti-correlated (joint flips against the additive prediction;
              extreme entanglement)

    Caveat: cosine is unreliable when both Δ_x and Δ_pe are tiny (head ignores
    both channels). Filter using positional_score / pe_invariance: a head
    near 1.0 on both is in the noise regime regardless of entanglement score.
    """
    rows = []
    for layer_idx, (c_layer, vx, vp, vb) in enumerate(zip(
        clean["layers"], var_x["layers"], var_pe["layers"], var_both["layers"]
    )):
        z_clean = c_layer["logits"]
        delta_x = vx["logits"] - z_clean
        delta_pe = vp["logits"] - z_clean
        delta_both = vb["logits"] - z_clean
        additive_pred = delta_x + delta_pe
        # The four runs share the same valid pair support because x/PE perms
        # leave edge_index and rrwp_index untouched.
        mask = pair_mask_from_layer(c_layer)
        cos = cosine_by_head_logits(delta_both, additive_pred, mask)
        score = 0.5 * (1.0 - cos)
        H = int(score.numel())
        for h in range(H):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": perm_idx,
                "layer": layer_idx, "head": h,
                "metric": M_ENTANGLEMENT,
                "score": float(score[h]),
                "raw_cos": float(cos[h]),
            })
    return rows


def entanglement_value_output_rows(model_name, clean, var_x, var_pe, var_both,
                                   batch_idx, perm_idx):
    rows = []
    for layer_idx, (c_layer, vx, vp, vb) in enumerate(zip(
        clean["layers"], var_x["layers"], var_pe["layers"], var_both["layers"]
    )):
        clean_t = c_layer.get("value_output")
        x_t = vx.get("value_output")
        pe_t = vp.get("value_output")
        both_t = vb.get("value_output")
        if clean_t is None or x_t is None or pe_t is None or both_t is None:
            continue
        delta_x = x_t - clean_t
        delta_pe = pe_t - clean_t
        delta_both = both_t - clean_t
        additive_pred = delta_x + delta_pe
        mask = node_mask_from_layer(c_layer)
        if mask is None:
            continue
        cos = value_cosine_by_head(delta_both, additive_pred, mask)
        score = 0.5 * (1.0 - cos)
        H = int(score.numel())
        for h in range(H):
            rows.append({
                "model": model_name, "batch": batch_idx, "perm": perm_idx,
                "layer": layer_idx, "head": h,
                "metric": M_ENTANGLEMENT_VALUE,
                "metric_space": "value_output",
                "score": float(score[h]),
                "raw_cos": float(cos[h]),
            })
    return rows


def _make_attention_snapshot(batch_cpu, clean, num_graphs: int = 5):
    """Capture per-graph softmaxed attention weights and atom IDs for the
    first `num_graphs` graphs in this batch. Used downstream by the
    interesting-heads visualization. Dispatches on the batch type to extract
    atom IDs.

    Returns dict with key "graphs": list of {n, atoms, attn[L, H, n, n]}.
    Attention is masked-softmax over valid keys per layer (matches what the
    metric loop's `cosine_by_head_logits` consumes internally).
    """
    layers = clean["layers"]
    if not layers:
        return {"graphs": []}
    nm0 = layers[0]["node_mask"]  # [B, N]
    counts = nm0.sum(dim=1).cpu().long().tolist()
    B = int(nm0.size(0))
    G = min(num_graphs, B)

    per_layer_attn = []
    for layer in layers:
        z = layer["logits"]
        m = pair_mask_from_layer(layer).to(device=z.device, dtype=torch.bool)
        H = int(z.size(1))
        if m.size(1) == 1 and H != 1:
            m = m.expand(-1, H, -1, -1)
        z_masked = torch.where(m, z, torch.full_like(z, -1.0e9))
        valid_row = m.any(dim=-1, keepdim=True)
        z_masked = torch.where(valid_row, z_masked, torch.zeros_like(z_masked))
        a = torch.softmax(z_masked, dim=-1)
        a = torch.where(m & valid_row, a, torch.zeros_like(a))
        per_layer_attn.append(a.detach().cpu())

    # Atom IDs per graph, family-aware.
    atoms_per_graph: List[List[int]] = []
    if isinstance(batch_cpu, GraphormerBatchAdapter):
        # x stored as [B, N, 1] with +1 shift baked into atom-IDs at collate.
        # Undo the shift for display so the labels match other models.
        x = batch_cpu.d["x"][:, :, 0]
        for b in range(G):
            n = counts[b]
            atoms_per_graph.append((x[b, :n].cpu() - 1).clamp(min=0).tolist())
    elif isinstance(batch_cpu, CSABatchAdapter):
        x = batch_cpu.b.x
        bi = batch_cpu.b.batch_index
        for b in range(G):
            atoms_per_graph.append(x[bi == b].cpu().tolist())
    elif isinstance(batch_cpu, V19BatchAdapter):
        x = batch_cpu.b.x
        bi = batch_cpu.b.batch_index
        for b in range(G):
            atoms_per_graph.append(x[bi == b].cpu().tolist())
    else:
        # PyG
        x_t = batch_cpu.x
        if x_t.dim() == 1:
            x_flat = x_t
        else:
            x_flat = x_t[:, 0]
        bi = batch_cpu.batch
        for b in range(G):
            atoms_per_graph.append(x_flat[bi == b].cpu().tolist())

    graphs = []
    for b in range(G):
        n = int(counts[b])
        if n == 0:
            continue
        # Stack [L, H, n, n].
        stacked = torch.stack(
            [layer_a[b, :, :n, :n] for layer_a in per_layer_attn], dim=0
        ).numpy()
        graphs.append({"n": n, "atoms": atoms_per_graph[b], "attn": stacked})
    return {"graphs": graphs}


def collect_metrics_for_model(spec, probe, loader, device, cfg,
                              num_snapshot_graphs: int = 5):
    """Run paper-faithful metrics. Per perm we do several controlled passes:
       (0) full graph relabeling -> relabel_equivariance sanity check.
       (1) x-only permutation -> positional_score, symbolic_score (paper).
       (2) PE-only permutation -> pe_invariance, pe_equivariance.
       (3) joint x+PE permutation (same sigma) -> legacy logit/value
           entanglement diagnostics plus centered mixed-attention metrics.
       (4) edge-label channel, pair-structure channel, and degree-preserving
           topology counterfactuals -> sensitivity scores.

    PE-perm and entanglement are skipped gracefully if the model batch carries
    no recognised PE channel; a one-line warning is printed.
    """
    rows = []
    rng = torch.Generator(device="cpu")
    rng.manual_seed(cfg.seed)
    t0 = time.time()
    pe_skipped = False
    edge_skipped = False
    pair_skipped = False
    topo_skipped = False
    snapshot = None
    for batch_idx, batch_cpu in enumerate(loader):
        if batch_idx >= cfg.metric_batches:
            break
        if batch_idx % max(1, cfg.verbose_every) == 0:
            print("=" * 80)
            print(f"[metrics:{spec.name}] batch {batch_idx + 1}/{cfg.metric_batches} "
                  f"| graphs={batch_cpu.num_graphs} nodes={batch_cpu.num_nodes} "
                  f"edges={batch_cpu.num_edges}")
        clean = probe.forward_collect(batch_cpu.clone().to(device))
        rows.extend(head_entropy_rows(spec.name, clean, batch_idx))
        rows.extend(bias_decomposition_rows(spec.name, clean, batch_idx))
        rows.extend(attention_ablation_rows(spec.name, clean, batch_idx))
        rows.extend(value_transport_counterfactual_rows(spec.name, clean, batch_idx))

        if batch_idx == 0:
            snapshot = _make_attention_snapshot(
                batch_cpu, clean, num_graphs=num_snapshot_graphs
            )

        x_variant_records = []
        pe_variant_records = []
        mixed_variant_records = []
        for perm_idx in range(cfg.num_perms):
            pb = make_node_permutation_bundle(batch_cpu, generator=rng)
            perm_pos = pb["perm_pos"]

            # (0) True graph relabeling. This should be near-perfect and acts
            # as a sanity check on both the models and the metric transport.
            relabel_variant = make_relabel_variant(batch_cpu, pb, spec.family)
            var_relabel = probe.forward_collect(relabel_variant.to(device))
            rows.extend(relabel_equivariance_rows(
                spec.name, clean, var_relabel, perm_pos, batch_idx, perm_idx,
                metric_space=cfg.metric_space,
            ))
            rows.extend(relabel_value_output_rows(
                spec.name, clean, var_relabel, perm_pos, batch_idx, perm_idx,
            ))
            del var_relabel, relabel_variant

            # (1) x-only permutation
            var_x = probe.forward_collect(
                make_x_permuted_variant(batch_cpu, pb).to(device)
            )
            x_variant_records.append((perm_idx, perm_pos, var_x))

            # (2) PE-only permutation, then (3) joint x+PE permutation.
            pe_variant = make_pe_permuted_variant(batch_cpu, pb, spec.family)
            if pe_variant is None:
                if not pe_skipped:
                    print(f"[metrics:{spec.name}] no PE channel found on batch; "
                          f"skipping PE-perm and entanglement metrics")
                    pe_skipped = True
            else:
                var_pe = probe.forward_collect(pe_variant.to(device))
                pe_variant_records.append((perm_idx, perm_pos, var_pe))
                joint_variant = make_x_and_pe_permuted_variant(
                    batch_cpu, pb, spec.family
                )
                # joint_variant cannot be None here because pe_variant succeeded
                # under the same family check.
                var_both = probe.forward_collect(joint_variant.to(device))
                mixed_variant_records.append((perm_idx, perm_pos, var_x, var_pe, var_both))
                rows.extend(entanglement_rows(
                    spec.name, clean, var_x, var_pe, var_both,
                    batch_idx, perm_idx,
                ))
                rows.extend(entanglement_value_output_rows(
                    spec.name, clean, var_x, var_pe, var_both,
                    batch_idx, perm_idx,
                ))
                del pe_variant, joint_variant

            # (4a) Fixed-topology edge-label/channel perturbation.
            edge_variant = make_edge_label_permuted_variant(
                batch_cpu, pb, spec.family
            )
            if edge_variant is None:
                if not edge_skipped:
                    print(f"[metrics:{spec.name}] no edge-label channel found; "
                          f"skipping edge_label_sensitivity")
                    edge_skipped = True
            else:
                var_edge = probe.forward_collect(edge_variant.to(device))
                rows.extend(sensitivity_rows(
                    spec.name, clean, var_edge, batch_idx, perm_idx,
                    metric=M_EDGE_LABEL_SENS,
                ))
                rows.extend(sensitivity_value_output_rows(
                    spec.name, clean, var_edge, batch_idx, perm_idx,
                    metric=M_EDGE_LABEL_SENS_VALUE,
                ))
                del var_edge, edge_variant

            # (4b) Attention-level pair-structure channel perturbation.
            pair_variant = make_pair_structure_permuted_variant(
                batch_cpu, pb, spec.family
            )
            if pair_variant is None:
                if not pair_skipped:
                    print(f"[metrics:{spec.name}] no pair-structure channel found; "
                          f"skipping pair_structure_sensitivity")
                    pair_skipped = True
            else:
                var_pair = probe.forward_collect(pair_variant.to(device))
                rows.extend(sensitivity_rows(
                    spec.name, clean, var_pair, batch_idx, perm_idx,
                    metric=M_PAIR_STRUCT_SENS,
                ))
                rows.extend(sensitivity_value_output_rows(
                    spec.name, clean, var_pair, batch_idx, perm_idx,
                    metric=M_PAIR_STRUCT_SENS_VALUE,
                ))
                del var_pair, pair_variant

            # (4c) Degree-preserving topology counterfactual. Families with
            # structural channels that cannot be recomputed exactly return None.
            topo_variant = make_degree_preserving_topology_variant(
                batch_cpu, pb, spec.family
            )
            if topo_variant is None:
                if not topo_skipped:
                    print(f"[metrics:{spec.name}] topology rewire unavailable "
                          f"or no valid swaps; skipping topology_rewire_sensitivity")
                    topo_skipped = True
            else:
                var_topo = probe.forward_collect(topo_variant.to(device))
                rows.extend(sensitivity_rows(
                    spec.name, clean, var_topo, batch_idx, perm_idx,
                    metric=M_TOPOLOGY_SENS, use_union_mask=True,
                ))
                rows.extend(sensitivity_value_output_rows(
                    spec.name, clean, var_topo, batch_idx, perm_idx,
                    metric=M_TOPOLOGY_SENS_VALUE, use_union_mask=True,
                ))
                del var_topo, topo_variant

            if (perm_idx + 1) % max(1, cfg.verbose_every * 16) == 0:
                print(f"[metrics:{spec.name}]   perm {perm_idx + 1}/{cfg.num_perms} "
                      f"| elapsed={time.time() - t0:.1f}s")
            if device.type == "cuda" and (perm_idx + 1) % 16 == 0:
                torch.cuda.empty_cache()

        rows.extend(alpha_weighted_plane_rows(
            spec.name, clean, x_variant_records, batch_idx,
            inv_metric=M_POSITIONAL, equi_metric=M_SYMBOLIC,
            cfg=cfg, centered=False,
        ))
        rows.extend(alpha_weighted_plane_rows(
            spec.name, clean, x_variant_records, batch_idx,
            inv_metric=M_POSITIONAL_CENTERED, equi_metric=M_SYMBOLIC_CENTERED,
            cfg=cfg, centered=True,
        ))
        rows.extend(alpha_weighted_value_output_plane_rows(
            spec.name, clean, x_variant_records, batch_idx,
            inv_metric=M_POSITIONAL_VALUE, equi_metric=M_SYMBOLIC_VALUE,
            cfg=cfg,
        ))
        if pe_variant_records:
            rows.extend(alpha_weighted_plane_rows(
                spec.name, clean, pe_variant_records, batch_idx,
                inv_metric=M_PE_INVARIANT, equi_metric=M_PE_EQUIVARIANT,
                cfg=cfg, centered=False,
            ))
            rows.extend(alpha_weighted_plane_rows(
                spec.name, clean, pe_variant_records, batch_idx,
                inv_metric=M_PE_INVARIANT_CENTERED, equi_metric=M_PE_EQUIVARIANT_CENTERED,
                cfg=cfg, centered=True,
            ))
            rows.extend(alpha_weighted_value_output_plane_rows(
                spec.name, clean, pe_variant_records, batch_idx,
                inv_metric=M_PE_INVARIANT_VALUE,
                equi_metric=M_PE_EQUIVARIANT_VALUE,
                cfg=cfg,
            ))
        if mixed_variant_records:
            rows.extend(alpha_weighted_mixed_attention_rows(
                spec.name, clean, mixed_variant_records, batch_idx, cfg
            ))

    df = pd.DataFrame(rows)
    meta = {
        "model": spec.name, "family": spec.family,
        "elapsed_s": float(time.time() - t0),
        "num_metric_rows": int(len(df)),
        "num_layers": probe.num_layers,
        "num_heads_by_layer": probe.num_heads_by_layer,
    }
    return df, meta, snapshot


# -----------------------------------------------------------------------------
# Aggregation and plotting
# -----------------------------------------------------------------------------


def summarise(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return pd.DataFrame()
    g = df.groupby(["model", "layer", "head", "metric"], as_index=False)["score"]
    s = g.agg(["mean", "std", "count"]).reset_index()
    s["se"] = s["std"] / np.sqrt(s["count"].clip(lower=1))
    return s


def _pivot(summary, model, metric):
    sub = summary[(summary["model"] == model) & (summary["metric"] == metric)]
    if sub.empty:
        return None
    p = sub.pivot(index="layer", columns="head", values="mean").sort_index()
    p = p.reindex(sorted(p.columns), axis=1)
    return p


def _heatmap(ax, mat, title, vmin, vmax, cmap):
    im = ax.imshow(mat.values, aspect="auto", cmap=cmap, vmin=vmin, vmax=vmax)
    ax.set_title(title)
    ax.set_xlabel("Head")
    ax.set_ylabel("Layer")
    ax.set_xticks(range(mat.shape[1]))
    ax.set_xticklabels(mat.columns)
    ax.set_yticks(range(mat.shape[0]))
    ax.set_yticklabels(mat.index)
    return im


def _plane_scatter(
    ax,
    joined,
    x_col,
    y_col,
    x_label,
    y_label,
    title,
    lo: float = 0.0,
    hi: float = 1.0,
):
    sc = ax.scatter(joined[x_col], joined[y_col],
                    c=joined["layer"], cmap="viridis", s=50,
                    edgecolors="black", linewidths=0.4)
    ref_y = [lo, hi] if lo < 0 else [hi, lo]
    ax.plot([lo, hi], ref_y, color="grey", linestyle="--", linewidth=0.8)
    if lo < 0:
        ax.axhline(0.0, color="#dddddd", linewidth=0.8)
        ax.axvline(0.0, color="#dddddd", linewidth=0.8)
    pad = 0.02 if lo >= 0 else 0.05
    ax.set_xlim(lo - pad, hi + pad)
    ax.set_ylim(lo - pad, hi + pad)
    ax.set_aspect("equal")
    ax.set_xlabel(x_label)
    ax.set_ylabel(y_label)
    ax.set_title(title)
    return sc


def make_plots(summary: pd.DataFrame, out_dir: Path) -> None:
    import matplotlib.pyplot as plt

    plots_dir = safe_mkdir(out_dir / "plots")
    if summary.empty:
        print("[plots] empty summary; skipping")
        return

    models = sorted(summary["model"].unique())

    # All scalar metrics with display titles, value range, colormap.
    metric_specs = [
        (M_POSITIONAL, "Positional score (invariance under x-perm)",
         0.0, 1.0, "Reds"),
        (M_SYMBOLIC, "Symbolic score (equivariance under x-perm)",
         0.0, 1.0, "Greens"),
        (M_PE_INVARIANT, "PE-invariance (head ignores structural encoding)",
         0.0, 1.0, "Purples"),
        (M_PE_EQUIVARIANT, "PE-equivariance (head depends only on PE channel)",
         0.0, 1.0, "Oranges"),
        (M_POSITIONAL_VALUE,
         "Value-output positional score (invariance under x-perm)",
         0.0, 1.0, "Reds"),
        (M_SYMBOLIC_VALUE,
         "Value-output symbolic score (equivariance under x-perm)",
         0.0, 1.0, "Greens"),
        (M_PE_INVARIANT_VALUE,
         "Value-output PE-invariance",
         0.0, 1.0, "Purples"),
        (M_PE_EQUIVARIANT_VALUE,
         "Value-output PE-equivariance",
         0.0, 1.0, "Oranges"),
        (M_POSITIONAL_CENTERED,
         "Centered positional score (attention residual invariance under x-perm)",
         -1.0, 1.0, "coolwarm"),
        (M_SYMBOLIC_CENTERED,
         "Centered symbolic score (attention residual equivariance under x-perm)",
         -1.0, 1.0, "coolwarm"),
        (M_PE_INVARIANT_CENTERED,
         "Centered PE-invariance (attention residual ignores structural encoding)",
         -1.0, 1.0, "coolwarm"),
        (M_PE_EQUIVARIANT_CENTERED,
         "Centered PE-equivariance (attention residual follows PE channel)",
         -1.0, 1.0, "coolwarm"),
        (M_INTERACTION_RESIDUAL_CENTERED,
         "Centered interaction residual norm (joint x+PE non-additivity)",
         0.0, 1.0, "magma"),
        (M_JOINT_EQUIVARIANCE_EXCESS_CENTERED,
         "Centered joint equivariance excess over best single-channel score",
         -1.0, 1.0, "coolwarm"),
        (M_ENTANGLEMENT,
         "Entanglement: 0 = additive in (x, PE), 0.5 = orthogonal, 1 = anti-correlated",
         0.0, 1.0, "PuRd"),
        (M_ENTANGLEMENT_VALUE,
         "Value-output entanglement: 0 = additive, 1 = anti-correlated",
         0.0, 1.0, "PuRd"),
        (M_ENTROPY, "Clean attention entropy (1 = uniform, 0 = one-hot)",
         0.0, 1.0, "Blues"),
        (M_RELABEL_EQUIVARIANT,
         "Relabel equivariance sanity check (1 = transported match)",
         0.0, 1.0, "Greys"),
        (M_RELABEL_EQUIVARIANT_VALUE,
         "Value-output relabel equivariance sanity check",
         0.0, 1.0, "Greys"),
        (M_EDGE_LABEL_SENS,
         "Edge-label sensitivity (0 = unchanged, 1 = flipped)",
         0.0, 1.0, "YlOrBr"),
        (M_PAIR_STRUCT_SENS,
         "Pair-structure sensitivity (0 = unchanged, 1 = flipped)",
         0.0, 1.0, "YlGnBu"),
        (M_TOPOLOGY_SENS,
         "Degree-preserving topology sensitivity (0 = unchanged, 1 = flipped)",
         0.0, 1.0, "magma"),
        (M_EDGE_LABEL_SENS_VALUE,
         "Value-output edge-label sensitivity",
         0.0, 1.0, "YlOrBr"),
        (M_PAIR_STRUCT_SENS_VALUE,
         "Value-output pair-structure sensitivity",
         0.0, 1.0, "YlGnBu"),
        (M_TOPOLOGY_SENS_VALUE,
         "Value-output topology sensitivity",
         0.0, 1.0, "magma"),
        (M_LOGIT_BIAS_VARIANCE_FRACTION,
         "Bias fraction of row-centred logit variance",
         0.0, 1.0, "viridis"),
        (M_LOGIT_BIAS_CONTENT_VAR_LOG10,
         "log10(bias/content row-centred logit variance)",
         -2.0, 2.0, "coolwarm"),
        (M_BIAS_ABLATION_ATTENTION_TV,
         "Attention TV after ablating explicit bias logits",
         0.0, 1.0, "magma"),
        (M_DOT_PRODUCT_ABLATION_ATTENTION_TV,
         "Attention TV after ablating dot-product logits",
         0.0, 1.0, "magma"),
        (M_BIAS_VALUE_TRANSPORT_EFFECT,
         "Value-output effect of bias-shaped attention (1 - cosine)",
         0.0, 2.0, "magma"),
        (M_STRUCT_VALUE_ADD_EFFECT,
         "Value-output effect of direct structural value add (1 - cosine)",
         0.0, 2.0, "magma"),
        (M_TOTAL_STRUCT_TRANSPORT_EFFECT,
         "Total structural transport effect (1 - cosine)",
         0.0, 2.0, "magma"),
        (M_BIAS_VALUE_TRANSPORT_RELATIVE_NORM,
         "Relative norm: bias-shaped value transport effect",
         0.0, 2.0, "magma"),
        (M_STRUCT_VALUE_ADD_RELATIVE_NORM,
         "Relative norm: direct structural value-add effect",
         0.0, 2.0, "magma"),
        (M_TOTAL_STRUCT_TRANSPORT_RELATIVE_NORM,
         "Relative norm: total structural transport effect",
         0.0, 2.0, "magma"),
    ]

    # Deprecated output cleanup: individual per-model score heatmaps are too
    # fragmented for comparing architectures. The side-by-side comparison
    # heatmaps below are now the canonical heatmap view.
    for m in models:
        for metric, _title, _vmin, _vmax, _cmap in metric_specs:
            stale = plots_dir / f"{m}__{metric}__heatmap.png"
            if stale.exists():
                stale.unlink()

    # Side-by-side comparison across all available models for each metric.
    if len(models) >= 2:
        for metric, title, vmin, vmax, cmap in metric_specs:
            mats = [(_pivot(summary, m, metric), m) for m in models]
            mats = [(p, m) for p, m in mats if p is not None]
            if len(mats) < 2:
                continue
            ncols = len(mats)
            widths = [max(4, 0.35 * p.shape[1] + 2) for p, _ in mats]
            fig, axes = plt.subplots(
                1, ncols,
                figsize=(sum(widths),
                         max(4, 0.3 * max(p.shape[0] for p, _ in mats) + 2)),
                gridspec_kw={"width_ratios": widths},
            )
            if ncols == 1:
                axes = [axes]
            ims = []
            for ax, (mat, mname) in zip(axes, mats):
                im = _heatmap(ax, mat, mname, vmin, vmax, cmap)
                ims.append(im)
            fig.suptitle(title)
            fig.colorbar(ims[-1], ax=axes, fraction=0.025, pad=0.02)
            fig.savefig(plots_dir / f"comparison__{metric}__heatmap.png",
                        dpi=150, bbox_inches="tight")
            plt.close(fig)

    # Plane scatters: individual per-model score planes plus one all-model
    # overlay per plane. Pairwise model-vs-model scatter comparisons are not
    # generated because they are too noisy for this analysis.
    plane_specs = [
        (M_POSITIONAL, M_SYMBOLIC,
         "Positional score (invariance under x-perm)",
         "Symbolic score (equivariance under x-perm)",
         "x-perm", "x_plane", 0.0, 1.0),
        (M_PE_INVARIANT, M_PE_EQUIVARIANT,
         "PE-invariance (head ignores PE)",
         "PE-equivariance (head depends only on PE)",
         "PE-perm", "pe_plane", 0.0, 1.0),
        (M_POSITIONAL_VALUE, M_SYMBOLIC_VALUE,
         "Value-output positional score",
         "Value-output symbolic score",
         "value-output x-perm", "x_plane_value_output", 0.0, 1.0),
        (M_PE_INVARIANT_VALUE, M_PE_EQUIVARIANT_VALUE,
         "Value-output PE-invariance",
         "Value-output PE-equivariance",
         "value-output PE-perm", "pe_plane_value_output", 0.0, 1.0),
        (M_POSITIONAL_CENTERED, M_SYMBOLIC_CENTERED,
         "Centered positional score",
         "Centered symbolic score",
         "centered x-perm", "x_plane_centered", -1.0, 1.0),
        (M_PE_INVARIANT_CENTERED, M_PE_EQUIVARIANT_CENTERED,
         "Centered PE-invariance",
         "Centered PE-equivariance",
         "centered PE-perm", "pe_plane_centered", -1.0, 1.0),
    ]

    for inv_m, equi_m, x_label, y_label, label, slug, lo, hi in plane_specs:
        joineds = []
        for m in models:
            sp = summary[(summary["model"] == m) & (summary["metric"] == inv_m)]
            ss = summary[(summary["model"] == m) & (summary["metric"] == equi_m)]
            if sp.empty or ss.empty:
                continue
            joined = sp.merge(ss, on=["model", "layer", "head"],
                              suffixes=("_x", "_y"))
            joineds.append(joined)

        for joined in joineds:
            m = joined["model"].iloc[0]
            fig, ax = plt.subplots(figsize=(6, 6))
            sc = _plane_scatter(ax, joined, "mean_x", "mean_y",
                                x_label, y_label,
                                f"{m}: {label} plane (per head)",
                                lo=lo, hi=hi)
            cbar = fig.colorbar(sc, ax=ax, fraction=0.04, pad=0.02)
            cbar.set_label("Layer")
            fig.tight_layout()
            fig.savefig(plots_dir / f"{m}__{slug}.png", dpi=150)
            plt.close(fig)

        if len(joineds) >= 2:
            fig, ax = plt.subplots(figsize=(7, 7))
            markers = ["o", "s", "^", "D", "v"]
            sc_last = None
            for marker, joined in zip(markers, joineds):
                m = joined["model"].iloc[0]
                sc_last = ax.scatter(joined["mean_x"], joined["mean_y"],
                                     c=joined["layer"], cmap="viridis",
                                     marker=marker, s=55, edgecolors="black",
                                     linewidths=0.4, label=m)
            ref_y = [lo, hi] if lo < 0 else [hi, lo]
            ax.plot([lo, hi], ref_y, color="grey", linestyle="--", linewidth=0.8)
            if lo < 0:
                ax.axhline(0.0, color="#dddddd", linewidth=0.8)
                ax.axvline(0.0, color="#dddddd", linewidth=0.8)
            pad = 0.02 if lo >= 0 else 0.05
            ax.set_xlim(lo - pad, hi + pad)
            ax.set_ylim(lo - pad, hi + pad)
            ax.set_aspect("equal")
            ax.set_xlabel(x_label)
            ax.set_ylabel(y_label)
            ax.set_title(f"{label} plane: model comparison")
            ax.legend(loc="lower left")
            if sc_last is not None:
                fig.colorbar(sc_last, ax=ax, fraction=0.04,
                             pad=0.02, label="Layer")
            fig.tight_layout()
            fig.savefig(plots_dir / f"comparison__{slug}.png", dpi=150)
            plt.close(fig)

    # Mixed-channel scatter: non-additive interaction size vs useful joint routing.
    mixed_joineds = []
    for m in models:
        sx = summary[(summary["model"] == m) & (summary["metric"] == M_INTERACTION_RESIDUAL_CENTERED)]
        sy = summary[(summary["model"] == m) & (summary["metric"] == M_JOINT_EQUIVARIANCE_EXCESS_CENTERED)]
        if sx.empty or sy.empty:
            continue
        mixed_joineds.append(sx.merge(sy, on=["model", "layer", "head"], suffixes=("_x", "_y")))
    if mixed_joineds:
        for joined in mixed_joineds:
            m = joined["model"].iloc[0]
            fig, ax = plt.subplots(figsize=(6.8, 5.8))
            sc = ax.scatter(
                joined["mean_x"], joined["mean_y"],
                c=joined["layer"], cmap="viridis", s=55,
                edgecolors="black", linewidths=0.4,
            )
            ax.axhline(0.0, color="#cccccc", linestyle="--", linewidth=0.8)
            ax.set_xlim(-0.02, 1.02)
            ax.set_ylim(-1.02, 1.02)
            ax.set_xlabel("centered interaction residual norm")
            ax.set_ylabel("centered joint equivariance excess")
            ax.set_title(f"{m}: mixed symbolic-structural metrics")
            ax.grid(alpha=0.3)
            fig.colorbar(sc, ax=ax, fraction=0.04, pad=0.02, label="Layer")
            fig.tight_layout()
            fig.savefig(plots_dir / f"{m}__mixed_interaction_vs_joint_excess.png", dpi=150)
            plt.close(fig)
        if len(mixed_joineds) >= 2:
            fig, ax = plt.subplots(figsize=(7.2, 6.2))
            markers = ["o", "s", "^", "D", "v"]
            sc_last = None
            for marker, joined in zip(markers, mixed_joineds):
                m = joined["model"].iloc[0]
                sc_last = ax.scatter(
                    joined["mean_x"], joined["mean_y"],
                    c=joined["layer"], cmap="viridis", marker=marker, s=55,
                    edgecolors="black", linewidths=0.4, label=m,
                )
            ax.axhline(0.0, color="#cccccc", linestyle="--", linewidth=0.8)
            ax.set_xlim(-0.02, 1.02)
            ax.set_ylim(-1.02, 1.02)
            ax.set_xlabel("centered interaction residual norm")
            ax.set_ylabel("centered joint equivariance excess")
            ax.set_title("Mixed symbolic-structural metrics: model comparison")
            ax.grid(alpha=0.3)
            ax.legend(loc="best", fontsize=9)
            if sc_last is not None:
                fig.colorbar(sc_last, ax=ax, fraction=0.04, pad=0.02, label="Layer")
            fig.tight_layout()
            fig.savefig(plots_dir / "comparison__mixed_interaction_vs_joint_excess.png", dpi=150)
            plt.close(fig)

    # Layer-wise mean +/- std curves: 2x3 grid (5 panels + legend slot)
    n_panels = len(metric_specs)
    ncols = 3
    nrows = (n_panels + ncols - 1) // ncols
    fig, axes = plt.subplots(nrows, ncols, figsize=(5 * ncols, 4 * nrows))
    axes_flat = axes.flatten() if nrows * ncols > 1 else [axes]
    for ax, (metric, title, vmin, vmax, _cmap) in zip(axes_flat, metric_specs):
        for m in models:
            sub = summary[(summary["model"] == m) & (summary["metric"] == metric)]
            if sub.empty:
                continue
            grp = sub.groupby("layer")["mean"].agg(["mean", "std"]).reset_index()
            ax.plot(grp["layer"], grp["mean"], label=m, marker="o")
            ax.fill_between(grp["layer"],
                            grp["mean"] - grp["std"].fillna(0),
                            grp["mean"] + grp["std"].fillna(0), alpha=0.2)
        ax.set_title(title, fontsize=10)
        ax.set_xlabel("Layer")
        ax.set_ylabel(metric)
        ax.set_ylim(vmin, vmax)
        ax.grid(alpha=0.3)
        ax.legend(loc="best", fontsize=8)
    for ax in axes_flat[n_panels:]:
        ax.axis("off")
    fig.tight_layout()
    fig.savefig(plots_dir / "layerwise_curves.png", dpi=150)
    plt.close(fig)

    # Channel-sensitivity scatter: x-sensitivity vs PE-sensitivity per head.
    # Sensitivity = 1 - invariance. A head in the bottom-left only uses edges;
    # top-right uses both x and PE substantially. Cleanly highlights how GPS
    # and GRIT distribute reliance across channels.
    sens_rows = []
    for m in models:
        sx = summary[(summary["model"] == m) & (summary["metric"] == M_POSITIONAL)]
        sp = summary[(summary["model"] == m) & (summary["metric"] == M_PE_INVARIANT)]
        if sx.empty or sp.empty:
            continue
        j = sx.merge(sp, on=["model", "layer", "head"], suffixes=("_x", "_pe"))
        j["x_sens"] = 1.0 - j["mean_x"]
        j["pe_sens"] = 1.0 - j["mean_pe"]
        sens_rows.append(j)
    if sens_rows:
        fig, ax = plt.subplots(figsize=(7, 7))
        markers = ["o", "s", "^", "D", "v"]
        sc_last = None
        for marker, j in zip(markers, sens_rows):
            m = j["model"].iloc[0]
            sc_last = ax.scatter(j["x_sens"], j["pe_sens"],
                                 c=j["layer"], cmap="viridis", marker=marker,
                                 s=55, edgecolors="black", linewidths=0.4,
                                 label=m)
        ax.set_xlim(-0.02, 1.02)
        ax.set_ylim(-0.02, 1.02)
        ax.set_aspect("equal")
        ax.set_xlabel("x-sensitivity (1 - positional_score)")
        ax.set_ylabel("PE-sensitivity (1 - pe_invariance)")
        ax.set_title("Channel sensitivity per head")
        ax.grid(alpha=0.3)
        ax.legend(loc="best", fontsize=9)
        if sc_last is not None:
            fig.colorbar(sc_last, ax=ax, fraction=0.04, pad=0.02, label="Layer")
        fig.tight_layout()
        fig.savefig(plots_dir / "comparison__channel_sensitivity.png", dpi=150)
        plt.close(fig)

    # Structural sensitivity planes for the new counterfactual metrics.
    struct_plane_specs = [
        (M_EDGE_LABEL_SENS, M_PAIR_STRUCT_SENS,
         "edge-label sensitivity", "pair-structure sensitivity",
         "edge_vs_pair_structure_sensitivity"),
        (M_PAIR_STRUCT_SENS, M_TOPOLOGY_SENS,
         "pair-structure sensitivity", "topology rewire sensitivity",
         "pair_structure_vs_topology_sensitivity"),
        (M_EDGE_LABEL_SENS_VALUE, M_PAIR_STRUCT_SENS_VALUE,
         "value-output edge-label sensitivity",
         "value-output pair-structure sensitivity",
         "value_output_edge_vs_pair_structure_sensitivity"),
        (M_PAIR_STRUCT_SENS_VALUE, M_TOPOLOGY_SENS_VALUE,
         "value-output pair-structure sensitivity",
         "value-output topology rewire sensitivity",
         "value_output_pair_structure_vs_topology_sensitivity"),
    ]
    for mx, my, xlab, ylab, slug in struct_plane_specs:
        joineds = []
        for m in models:
            sx = summary[(summary["model"] == m) & (summary["metric"] == mx)]
            sy = summary[(summary["model"] == m) & (summary["metric"] == my)]
            if sx.empty or sy.empty:
                continue
            joineds.append(sx.merge(sy, on=["model", "layer", "head"],
                                    suffixes=("_x", "_y")))
        if not joineds:
            continue
        fig, ax = plt.subplots(figsize=(7, 7))
        markers = ["o", "s", "^", "D", "v"]
        sc_last = None
        for marker, joined in zip(markers, joineds):
            m = joined["model"].iloc[0]
            sc_last = ax.scatter(joined["mean_x"], joined["mean_y"],
                                 c=joined["layer"], cmap="viridis",
                                 marker=marker, s=55, edgecolors="black",
                                 linewidths=0.4, label=m)
        ax.set_xlim(-0.02, 1.02)
        ax.set_ylim(-0.02, 1.02)
        ax.set_aspect("equal")
        ax.set_xlabel(xlab)
        ax.set_ylabel(ylab)
        ax.set_title(f"Structural counterfactuals: {xlab} vs {ylab}")
        ax.grid(alpha=0.3)
        ax.legend(loc="best", fontsize=9)
        if sc_last is not None:
            fig.colorbar(sc_last, ax=ax, fraction=0.04, pad=0.02, label="Layer")
        fig.tight_layout()
        fig.savefig(plots_dir / f"comparison__{slug}.png", dpi=150)
        plt.close(fig)

    # Bias/content decomposition: raw variance ratio on a log y-axis.
    ratio_sub = summary[summary["metric"] == M_LOGIT_BIAS_CONTENT_VAR_RATIO]
    if not ratio_sub.empty:
        fig, ax = plt.subplots(figsize=(8.0, 5.0))
        for m in models:
            sub = ratio_sub[ratio_sub["model"] == m]
            if sub.empty:
                continue
            grp = sub.groupby("layer")["mean"].agg(["mean", "std"]).reset_index()
            y = grp["mean"].clip(lower=1e-6)
            ax.plot(grp["layer"], y, marker="o", label=m)
            lower = (grp["mean"] - grp["std"].fillna(0)).clip(lower=1e-6)
            upper = (grp["mean"] + grp["std"].fillna(0)).clip(lower=1e-6)
            ax.fill_between(grp["layer"], lower, upper, alpha=0.18)
        ax.axhline(1.0, color="grey", linestyle="--", linewidth=0.9)
        ax.set_yscale("log")
        ax.set_xlabel("Layer")
        ax.set_ylabel("bias variance / content variance")
        ax.set_title("Logit decomposition scale by layer")
        ax.grid(alpha=0.3, which="both")
        ax.legend(loc="best", fontsize=9)
        fig.tight_layout()
        fig.savefig(plots_dir / "layerwise_bias_content_variance_ratio.png", dpi=150)
        plt.close(fig)

    print(f"[plots] saved plots to {plots_dir}")


def _quantile(q: float):
    def f(x):
        return float(np.quantile(x.to_numpy(dtype=float), q))
    f.__name__ = f"q{int(q * 100):02d}"
    return f


def make_graph_subset_analysis(metric_rows: pd.DataFrame, out_dir: Path) -> None:
    """Analyze graph-to-graph variation in baseline x-permutation scores.

    The alpha-weighted metric rows are already one row per
    graph/layer/head/metric after query averaging. This analysis asks whether
    heads that are only modestly specialised on average have high-symbolic or
    high-structural tails on graph subsets.
    """
    if metric_rows.empty or "graph_in_batch" not in metric_rows.columns:
        print("[graph-variation] no per-graph metric rows; skipping")
        return
    plots_dir = safe_mkdir(out_dir / "plots_graph_variation")
    metrics = [
        M_POSITIONAL,
        M_SYMBOLIC,
        M_POSITIONAL_CENTERED,
        M_SYMBOLIC_CENTERED,
    ]
    sub = metric_rows[
        metric_rows["metric"].isin(metrics)
        & metric_rows["graph_in_batch"].notna()
    ].copy()
    if sub.empty:
        print("[graph-variation] no baseline symbolic/positional graph rows; skipping")
        return
    sub["graph_uid"] = sub["batch"].astype(str) + ":" + sub["graph_in_batch"].astype(str)

    group_cols = ["model", "layer", "head", "metric"]
    g = sub.groupby(group_cols)["score"]
    variation = g.agg(
        mean="mean",
        std="std",
        count="count",
        min="min",
        q05=_quantile(0.05),
        q10=_quantile(0.10),
        q25=_quantile(0.25),
        median="median",
        q75=_quantile(0.75),
        q90=_quantile(0.90),
        q95=_quantile(0.95),
        max="max",
    ).reset_index()
    for threshold in (0.70, 0.80, 0.90):
        frac = g.apply(lambda x, t=threshold: float(np.mean(x.to_numpy(dtype=float) >= t)))
        variation[f"frac_ge_{str(threshold).replace('.', '_')}"] = variation.set_index(group_cols).index.map(frac)
    variation["tail_lift_q90"] = variation["q90"] - variation["mean"]
    variation["tail_lift_q95"] = variation["q95"] - variation["mean"]
    variation.to_csv(out_dir / "graph_metric_variation_summary.csv", index=False)

    base = sub[sub["metric"].isin([M_POSITIONAL, M_SYMBOLIC])].copy()
    idx = ["model", "batch", "graph_in_batch", "graph_uid", "layer", "head"]
    wide = base.pivot_table(index=idx, columns="metric", values="score", aggfunc="mean").reset_index()
    if M_POSITIONAL in wide.columns and M_SYMBOLIC in wide.columns:
        wide = wide.rename(columns={M_POSITIONAL: "positional_score", M_SYMBOLIC: "symbolic_score"})
        wide["structural_subset"] = (
            (wide["positional_score"] >= 0.80) & (wide["symbolic_score"] <= 0.65)
        ).astype(float)
        wide["symbolic_subset"] = (
            (wide["symbolic_score"] >= 0.80) & (wide["positional_score"] <= 0.65)
        ).astype(float)
        wide["mixed_subset"] = (
            (wide["symbolic_score"] >= 0.75) & (wide["positional_score"] >= 0.75)
        ).astype(float)
        wide["specialized_subset"] = (
            (wide["symbolic_score"] >= 0.80) | (wide["positional_score"] >= 0.80)
        ).astype(float)
        wide.to_csv(out_dir / "graph_xplane_per_graph.csv", index=False)

        plane = wide.groupby(["model", "layer", "head"]).agg(
            positional_mean=("positional_score", "mean"),
            positional_std=("positional_score", "std"),
            positional_q90=("positional_score", lambda x: float(np.quantile(x, 0.90))),
            positional_q95=("positional_score", lambda x: float(np.quantile(x, 0.95))),
            symbolic_mean=("symbolic_score", "mean"),
            symbolic_std=("symbolic_score", "std"),
            symbolic_q90=("symbolic_score", lambda x: float(np.quantile(x, 0.90))),
            symbolic_q95=("symbolic_score", lambda x: float(np.quantile(x, 0.95))),
            frac_structural_subset=("structural_subset", "mean"),
            frac_symbolic_subset=("symbolic_subset", "mean"),
            frac_mixed_subset=("mixed_subset", "mean"),
            frac_specialized_subset=("specialized_subset", "mean"),
            graph_count=("graph_uid", "count"),
        ).reset_index()
        plane["positional_tail_lift_q95"] = plane["positional_q95"] - plane["positional_mean"]
        plane["symbolic_tail_lift_q95"] = plane["symbolic_q95"] - plane["symbolic_mean"]
        plane["max_tail_lift_q95"] = plane[["positional_tail_lift_q95", "symbolic_tail_lift_q95"]].max(axis=1)
        plane.to_csv(out_dir / "graph_xplane_subset_summary.csv", index=False)
    else:
        wide = pd.DataFrame()
        plane = pd.DataFrame()

    import matplotlib.pyplot as plt

    # Heatmaps: graph-subset tail lift and fraction of high-scoring graphs.
    for model in sorted(variation["model"].unique()):
        for metric in metrics:
            msub = variation[(variation["model"] == model) & (variation["metric"] == metric)]
            if msub.empty:
                continue
            for field, title, cmap, vmax in [
                ("tail_lift_q95", "q95 - mean graph-subset lift", "magma", 0.5),
                ("frac_ge_0_8", "fraction of graphs with score >= 0.8", "viridis", 1.0),
            ]:
                mat = msub.pivot(index="layer", columns="head", values=field).sort_index()
                mat = mat.reindex(sorted(mat.columns), axis=1)
                fig, ax = plt.subplots(
                    figsize=(max(6, 0.4 * mat.shape[1] + 3), max(4, 0.3 * mat.shape[0] + 2))
                )
                im = _heatmap(ax, mat, f"{model}\n{metric}: {title}", 0.0, vmax, cmap)
                fig.colorbar(im, ax=ax, fraction=0.04, pad=0.02)
                fig.tight_layout()
                fig.savefig(plots_dir / f"{model}__{metric}__{field}.png", dpi=150)
                plt.close(fig)

    # Plane plot: average head behavior plus high-subset endpoint.
    if not plane.empty:
        for model in sorted(plane["model"].unique()):
            psub = plane[plane["model"] == model].copy()
            fig, ax = plt.subplots(figsize=(7.2, 7.0))
            for _, row in psub.iterrows():
                ax.plot(
                    [row["positional_mean"], row["positional_q95"]],
                    [row["symbolic_mean"], row["symbolic_q95"]],
                    color="#bbbbbb",
                    linewidth=0.7,
                    alpha=0.45,
                    zorder=1,
                )
            size = 35.0 + 180.0 * psub["frac_specialized_subset"].fillna(0.0).to_numpy()
            sc = ax.scatter(
                psub["positional_mean"],
                psub["symbolic_mean"],
                c=psub["layer"],
                cmap="viridis",
                s=size,
                edgecolors="black",
                linewidths=0.35,
                alpha=0.9,
                label="mean",
                zorder=2,
            )
            ax.scatter(
                psub["positional_q95"],
                psub["symbolic_q95"],
                c=psub["layer"],
                cmap="viridis",
                marker="x",
                s=45,
                linewidths=1.0,
                alpha=0.85,
                label="q95 endpoint",
                zorder=3,
            )
            ax.plot([0, 1], [1, 0], color="grey", linestyle="--", linewidth=0.8)
            ax.set_xlim(-0.02, 1.02)
            ax.set_ylim(-0.02, 1.02)
            ax.set_aspect("equal")
            ax.set_xlabel("positional_score")
            ax.set_ylabel("symbolic_score")
            ax.set_title(f"{model}: mean vs graph-subset q95 x-plane")
            ax.grid(alpha=0.3)
            ax.legend(loc="best", fontsize=8)
            fig.colorbar(sc, ax=ax, fraction=0.04, pad=0.02, label="Layer")
            fig.tight_layout()
            fig.savefig(plots_dir / f"{model}__xplane_mean_to_q95.png", dpi=150)
            plt.close(fig)

            top = psub.sort_values(
                ["frac_specialized_subset", "max_tail_lift_q95"],
                ascending=False,
            ).head(20)
            if not top.empty:
                labels = [f"L{int(r.layer)}H{int(r.head)}" for r in top.itertuples()]
                x = np.arange(len(top))
                fig, ax = plt.subplots(figsize=(max(8, 0.45 * len(top) + 3), 4.5))
                ax.bar(x - 0.2, top["frac_symbolic_subset"], width=0.2, label="symbolic subset")
                ax.bar(x, top["frac_structural_subset"], width=0.2, label="structural subset")
                ax.bar(x + 0.2, top["frac_mixed_subset"], width=0.2, label="mixed subset")
                ax.set_xticks(x)
                ax.set_xticklabels(labels, rotation=45, ha="right", fontsize=8)
                ax.set_ylim(0, 1.0)
                ax.set_ylabel("fraction of graphs")
                ax.set_title(f"{model}: top subset-specialised heads")
                ax.grid(axis="y", alpha=0.3)
                ax.legend(frameon=False, fontsize=8)
                fig.tight_layout()
                fig.savefig(plots_dir / f"{model}__top_subset_specialised_heads.png", dpi=150)
                plt.close(fig)

    print(f"[graph-variation] wrote CSVs and plots to {plots_dir}")


