CAUSAL_INTERVENTION_HEAD_OUTPUT = "head_output_zero"
CAUSAL_INTERVENTION_BIAS_ZERO = "bias_zero"
CAUSAL_INTERVENTION_CONTENT_ZERO = "content_zero"
CAUSAL_INTERVENTION_STRUCT_VALUE_ZERO = "struct_value_zero"


def _parse_csv_ints(raw: str, default: Sequence[int]) -> List[int]:
    vals = []
    for part in str(raw or "").split(","):
        part = part.strip()
        if not part:
            continue
        try:
            vals.append(max(1, int(part)))
        except ValueError:
            pass
    return sorted(set(vals or list(default)))


def _parse_csv_strings(raw: str, default: Sequence[str]) -> List[str]:
    vals = [p.strip() for p in str(raw or "").split(",") if p.strip()]
    return vals or list(default)


def _causal_seed(cfg: RunConfig) -> int:
    return int(cfg.causal_seed if cfg.causal_seed is not None else cfg.seed + 1009)


def _interventions_for_family(family: str, requested: Sequence[str]) -> List[str]:
    supported = {
        "graphgps": {CAUSAL_INTERVENTION_HEAD_OUTPUT},
        "graphormer": {
            CAUSAL_INTERVENTION_HEAD_OUTPUT,
            CAUSAL_INTERVENTION_BIAS_ZERO,
            CAUSAL_INTERVENTION_CONTENT_ZERO,
        },
        "grit": {
            CAUSAL_INTERVENTION_HEAD_OUTPUT,
            CAUSAL_INTERVENTION_BIAS_ZERO,
            CAUSAL_INTERVENTION_CONTENT_ZERO,
            CAUSAL_INTERVENTION_STRUCT_VALUE_ZERO,
        },
        "csa": {
            CAUSAL_INTERVENTION_HEAD_OUTPUT,
            CAUSAL_INTERVENTION_BIAS_ZERO,
            CAUSAL_INTERVENTION_CONTENT_ZERO,
            CAUSAL_INTERVENTION_STRUCT_VALUE_ZERO,
        },
        "v19": {
            CAUSAL_INTERVENTION_HEAD_OUTPUT,
            CAUSAL_INTERVENTION_BIAS_ZERO,
            CAUSAL_INTERVENTION_CONTENT_ZERO,
            CAUSAL_INTERVENTION_STRUCT_VALUE_ZERO,
        },
    }.get(family, {CAUSAL_INTERVENTION_HEAD_OUTPUT})
    return [x for x in requested if x in supported]


def _batch_targets(batch) -> torch.Tensor:
    if hasattr(batch, "y"):
        return batch.y.view(-1).float()
    if hasattr(batch, "d") and isinstance(batch.d, Mapping) and "y" in batch.d:
        return batch.d["y"].view(-1).float()
    if hasattr(batch, "b") and hasattr(batch.b, "y"):
        return batch.b.y.view(-1).float()
    raise AttributeError("Cannot infer target tensor from batch")


def _all_head_pairs_from_probe(num_heads_by_layer: Mapping[int, int]) -> List[Tuple[int, int]]:
    out = []
    for layer in sorted(num_heads_by_layer):
        for head in range(int(num_heads_by_layer[layer])):
            out.append((int(layer), int(head)))
    return out


def _head_pairs_to_ablation_plan(head_pairs: Sequence[Tuple[int, int]],
                                 intervention: str) -> Dict[str, Any]:
    by_layer: Dict[int, List[int]] = {}
    for layer, head in head_pairs:
        by_layer.setdefault(int(layer), []).append(int(head))
    return {
        "intervention": intervention,
        "ablate_global_heads": {int(k): sorted(set(v)) for k, v in by_layer.items()},
    }


def _layer_profile(head_pairs: Sequence[Tuple[int, int]]) -> Dict[int, int]:
    out: Dict[int, int] = {}
    for layer, _head in head_pairs:
        out[int(layer)] = out.get(int(layer), 0) + 1
    return out


def _head_label(layer: int, head: int) -> str:
    return f"L{int(layer)}H{int(head)}"


def _head_group_score(summary: pd.DataFrame,
                      high_metrics: Sequence[str],
                      low_metrics: Sequence[str] = ()) -> pd.DataFrame:
    """Return percentile-rank composite scores per (layer, head)."""
    if summary.empty:
        return pd.DataFrame(columns=["layer", "head", "score"])
    pieces = []
    metric_dirs = [(m, True) for m in high_metrics] + [(m, False) for m in low_metrics]
    for metric, high_is_good in metric_dirs:
        sub = summary[summary["metric"] == metric][["layer", "head", "mean"]].copy()
        if sub.empty:
            continue
        vals = sub["mean"].astype(float).replace([np.inf, -np.inf], np.nan)
        if vals.notna().sum() == 0:
            continue
        ranks = vals.rank(pct=True, method="average")
        sub["score_component"] = ranks if high_is_good else 1.0 - ranks
        sub["selector_metric"] = metric
        pieces.append(sub[["layer", "head", "score_component", "selector_metric"]])
    if not pieces:
        return pd.DataFrame(columns=["layer", "head", "score"])
    joined = pd.concat(pieces, ignore_index=True)
    out = joined.groupby(["layer", "head"], as_index=False).agg(
        score=("score_component", "mean"),
        selector_metrics=("selector_metric", lambda x: ",".join(sorted(set(map(str, x))))),
    )
    return out.sort_values(["score", "layer", "head"], ascending=[False, True, True])


def _select_pairs_from_score(score_df: pd.DataFrame, k: int,
                             descending: bool = True) -> List[Tuple[int, int]]:
    if score_df.empty:
        return []
    sub = score_df.sort_values(
        ["score", "layer", "head"],
        ascending=[not descending, True, True],
    ).head(int(k))
    return [(int(r.layer), int(r.head)) for r in sub.itertuples(index=False)]


def _build_metric_guided_head_groups(spec: ModelSpec,
                                     summary: pd.DataFrame,
                                     topk_values: Sequence[int],
                                     num_heads_by_layer: Mapping[int, int]) -> List[Dict[str, Any]]:
    model_summary = summary[summary["model"] == spec.name].copy()
    structural_metrics = [
        M_PE_EQUIVARIANT_CENTERED,
        M_PE_EQUIVARIANT,
        M_PAIR_STRUCT_SENS,
        M_TOPOLOGY_SENS,
        M_BIAS_ABLATION_ATTENTION_TV,
    ]
    value_structural_metrics = [
        M_PE_EQUIVARIANT_VALUE,
        M_PAIR_STRUCT_SENS_VALUE,
        M_TOPOLOGY_SENS_VALUE,
        M_STRUCT_VALUE_ADD_EFFECT,
        M_TOTAL_STRUCT_TRANSPORT_EFFECT,
    ]
    bias_metrics = [
        M_LOGIT_BIAS_VARIANCE_FRACTION,
        M_LOGIT_BIAS_CONTENT_VAR_LOG10,
        M_BIAS_ABLATION_ATTENTION_TV,
        M_BIAS_VALUE_TRANSPORT_EFFECT,
    ]
    mixed_metrics = [
        M_ENTANGLEMENT,
        M_ENTANGLEMENT_VALUE,
        M_INTERACTION_RESIDUAL_CENTERED,
        M_JOINT_EQUIVARIANCE_EXCESS_CENTERED,
    ]
    symbolic_metrics = [
        M_SYMBOLIC_CENTERED,
        M_SYMBOLIC_VALUE,
    ]

    score_defs = {
        "top_structural_heads": (
            _head_group_score(model_summary, structural_metrics),
            structural_metrics,
            True,
        ),
        "top_value_structural_heads": (
            _head_group_score(model_summary, value_structural_metrics),
            value_structural_metrics,
            True,
        ),
        "top_bias_dominated_heads": (
            _head_group_score(model_summary, bias_metrics),
            bias_metrics,
            True,
        ),
        "top_mixed_heads": (
            _head_group_score(model_summary, mixed_metrics),
            mixed_metrics,
            True,
        ),
        "top_symbolic_heads": (
            _head_group_score(model_summary, symbolic_metrics),
            symbolic_metrics,
            True,
        ),
        "bottom_metric_heads": (
            _head_group_score(model_summary, structural_metrics),
            structural_metrics,
            False,
        ),
    }

    if spec.family == "csa":
        late_metrics = [
            M_PE_EQUIVARIANT_VALUE,
            M_PAIR_STRUCT_SENS_VALUE,
            M_LOGIT_BIAS_VARIANCE_FRACTION,
            M_STRUCT_VALUE_ADD_EFFECT,
        ]
        late_score = _head_group_score(
            model_summary,
            late_metrics,
            low_metrics=[M_ENTROPY, M_POSITIONAL_CENTERED, M_SYMBOLIC_CENTERED],
        )
        if not late_score.empty:
            max_layer = max(num_heads_by_layer) if num_heads_by_layer else 0
            late_floor = int(math.floor(0.70 * max_layer))
            late_score = late_score[late_score["layer"] >= late_floor]
        score_defs["late_csa_low_symbolic_structural_heads"] = (
            late_score,
            late_metrics + [M_ENTROPY, M_POSITIONAL_CENTERED, M_SYMBOLIC_CENTERED],
            True,
        )

    records: List[Dict[str, Any]] = []
    seen = set()
    for group_name, (score_df, selector_metrics, descending) in score_defs.items():
        for k in topk_values:
            pairs = _select_pairs_from_score(score_df, k, descending=descending)
            if not pairs:
                continue
            key = (group_name, int(k), tuple(pairs))
            if key in seen:
                continue
            seen.add(key)
            records.append({
                "head_group": group_name,
                "k": len(pairs),
                "requested_k": int(k),
                "head_pairs": pairs,
                "selector_metrics": [m for m in selector_metrics if m in set(model_summary["metric"])],
                "target_group": ", ".join(_head_label(l, h) for l, h in pairs),
                "layer_profile": _layer_profile(pairs),
            })
    return records


def _sample_global_heads(all_heads: Sequence[Tuple[int, int]], k: int,
                         rng: random.Random) -> List[Tuple[int, int]]:
    return rng.sample(list(all_heads), k=min(int(k), len(all_heads)))


def _sample_layer_matched_heads(target_heads: Sequence[Tuple[int, int]],
                                num_heads_by_layer: Mapping[int, int],
                                rng: random.Random) -> List[Tuple[int, int]]:
    target_set = set((int(l), int(h)) for l, h in target_heads)
    out: List[Tuple[int, int]] = []
    for layer, count in _layer_profile(target_heads).items():
        layer_heads = [(int(layer), h) for h in range(int(num_heads_by_layer[int(layer)]))]
        candidates = [hp for hp in layer_heads if hp not in target_set]
        if len(candidates) < count:
            candidates = layer_heads
        out.extend(rng.sample(candidates, k=min(int(count), len(candidates))))
    if len(out) < len(target_heads):
        all_heads = _all_head_pairs_from_probe(num_heads_by_layer)
        leftovers = [hp for hp in all_heads if hp not in out]
        out.extend(rng.sample(leftovers, k=min(len(target_heads) - len(out), len(leftovers))))
    return out[:len(target_heads)]


def _variant_id(model: str, intervention: str, head_group: str, k: int,
                variant_type: str, null_type: str = "target",
                trial: Optional[int] = None) -> str:
    suffix = "" if trial is None else f":trial{int(trial)}"
    return f"{model}:{intervention}:{head_group}:k{k}:{variant_type}:{null_type}{suffix}"


def _evaluate_causal_variant(spec: ModelSpec,
                             probe: AttentionProbeManager,
                             loader,
                             device: torch.device,
                             cfg: RunConfig,
                             eval_split: str,
                             ablation_plan: Dict[str, Any],
                             meta: Dict[str, Any]) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for batch_idx, batch_cpu in enumerate(loader):
        if batch_idx >= int(cfg.causal_batches):
            break
        # Some GraphGym models mutate PyG Batch fields in-place during forward
        # (for example, replacing integer atom indices with embedded floats).
        # Use fresh clones for clean, ablated, and target extraction so repeated
        # causal passes never feed a mutated batch back into an embedding layer.
        clean_batch = batch_cpu.clone().to(device)
        ablated_batch = batch_cpu.clone().to(device)
        target_batch = batch_cpu.clone().to(device)
        clean = probe.forward_collect(clean_batch, collect_layers=False)
        ablated = probe.forward_collect(
            ablated_batch, ablation_plan=ablation_plan, collect_layers=False
        )
        y = _batch_targets(target_batch).detach().cpu().view(-1).float()
        pred0 = clean["pred"].detach().cpu().view(-1).float()
        pred1 = ablated["pred"].detach().cpu().view(-1).float()
        n = min(int(y.numel()), int(pred0.numel()), int(pred1.numel()))
        for g in range(n):
            clean_err = abs(float(pred0[g]) - float(y[g]))
            ab_err = abs(float(pred1[g]) - float(y[g]))
            rows.append({
                "model": spec.name,
                "family": spec.family,
                "split": eval_split,
                "batch": int(batch_idx),
                "graph_in_batch": int(g),
                "graph_uid": f"{batch_idx}:{g}",
                "intervention": meta["intervention"],
                "head_group": meta["head_group"],
                "variant_type": meta["variant_type"],
                "null_type": meta.get("null_type", "target"),
                "trial": meta.get("trial", np.nan),
                "matched_to_variant_id": meta.get("matched_to_variant_id", ""),
                "variant_id": meta["variant_id"],
                "k": int(meta.get("k", 0)),
                "requested_k": int(meta.get("requested_k", meta.get("k", 0))),
                "layer_profile": json.dumps(meta.get("layer_profile", {}), sort_keys=True),
                "target_group": meta.get("target_group", ""),
                "head_pairs_json": json.dumps(meta.get("head_pairs", [])),
                "clean_pred": float(pred0[g]),
                "ablated_pred": float(pred1[g]),
                "target": float(y[g]),
                "clean_abs_error": clean_err,
                "ablated_abs_error": ab_err,
                "delta_abs_error": ab_err - clean_err,
                "abs_pred_delta": abs(float(pred1[g]) - float(pred0[g])),
                "signed_pred_delta": float(pred1[g]) - float(pred0[g]),
            })
    return pd.DataFrame(rows)


def _bootstrap_ci(vals: np.ndarray, rng: np.random.Generator,
                  samples: int) -> Tuple[float, float]:
    vals = np.asarray(vals, dtype=float)
    vals = vals[np.isfinite(vals)]
    if vals.size == 0:
        return float("nan"), float("nan")
    if vals.size == 1 or samples <= 0:
        return float(vals.mean()), float(vals.mean())
    idx = rng.integers(0, vals.size, size=(int(samples), vals.size))
    means = vals[idx].mean(axis=1)
    return float(np.quantile(means, 0.025)), float(np.quantile(means, 0.975))


def _sign_flip_p_value(diffs: np.ndarray, rng: np.random.Generator,
                       samples: int) -> float:
    diffs = np.asarray(diffs, dtype=float)
    diffs = diffs[np.isfinite(diffs)]
    if diffs.size == 0:
        return float("nan")
    observed = float(diffs.mean())
    if samples <= 0:
        return float("nan")
    signs = rng.choice(np.array([-1.0, 1.0]), size=(int(samples), diffs.size))
    null_means = (signs * diffs[None, :]).mean(axis=1)
    return float((1.0 + np.sum(null_means >= observed)) / (len(null_means) + 1.0))


def _bh_q_values(p_values: Sequence[float]) -> List[float]:
    p = np.asarray([np.nan if v is None else float(v) for v in p_values], dtype=float)
    q = np.full_like(p, np.nan, dtype=float)
    valid = np.isfinite(p)
    if not valid.any():
        return q.tolist()
    idx = np.where(valid)[0]
    order = idx[np.argsort(p[idx])]
    ranked = p[order]
    m = float(len(ranked))
    adj = ranked * m / np.arange(1, len(ranked) + 1)
    adj = np.minimum.accumulate(adj[::-1])[::-1]
    q[order] = np.clip(adj, 0.0, 1.0)
    return q.tolist()


def summarise_causal_rows(rows_df: pd.DataFrame, cfg: RunConfig) -> pd.DataFrame:
    if rows_df.empty:
        return pd.DataFrame()
    rng = np.random.default_rng(_causal_seed(cfg) + 17)
    id_cols = [
        "model", "family", "split", "intervention", "head_group",
        "variant_type", "null_type", "variant_id", "matched_to_variant_id",
        "k", "requested_k", "trial", "layer_profile", "target_group",
    ]
    summary_rows: List[Dict[str, Any]] = []
    for key, sub in rows_df.groupby(id_cols, dropna=False):
        rec = dict(zip(id_cols, key))
        delta = sub["delta_abs_error"].to_numpy(dtype=float)
        pred_delta = sub["abs_pred_delta"].to_numpy(dtype=float)
        ci_lo, ci_hi = _bootstrap_ci(delta, rng, cfg.causal_bootstrap_samples)
        p_lo, p_hi = _bootstrap_ci(pred_delta, rng, cfg.causal_bootstrap_samples)
        rec.update({
            "n_graphs": int(len(sub)),
            "mae_clean": float(sub["clean_abs_error"].mean()),
            "mae_ablated": float(sub["ablated_abs_error"].mean()),
            "mean_delta_abs_error": float(np.mean(delta)) if delta.size else np.nan,
            "ci95_delta_abs_error_low": ci_lo,
            "ci95_delta_abs_error_high": ci_hi,
            "mean_abs_pred_delta": float(np.mean(pred_delta)) if pred_delta.size else np.nan,
            "ci95_abs_pred_delta_low": p_lo,
            "ci95_abs_pred_delta_high": p_hi,
        })
        summary_rows.append(rec)

    summary = pd.DataFrame(summary_rows)
    target_mask = summary["variant_type"].isin(["metric_guided_head_set", "single_head"])
    for idx, row in summary[target_mask].iterrows():
        target_id = row["variant_id"]
        target_rows = rows_df[rows_df["variant_id"] == target_id].copy()
        for null_type in ["global_matched", "layer_matched"]:
            random_rows = rows_df[
                (rows_df["matched_to_variant_id"] == target_id)
                & (rows_df["null_type"] == null_type)
            ].copy()
            if random_rows.empty:
                continue
            trial_means = random_rows.groupby("trial")["delta_abs_error"].mean()
            trial_pred = random_rows.groupby("trial")["abs_pred_delta"].mean()
            target_delta = float(target_rows["delta_abs_error"].mean())
            target_pred = float(target_rows["abs_pred_delta"].mean())
            summary.loc[idx, f"random_{null_type}_mean_delta_abs_error"] = float(trial_means.mean())
            summary.loc[idx, f"random_{null_type}_std_delta_abs_error"] = float(trial_means.std(ddof=1))
            summary.loc[idx, f"empirical_p_delta_abs_error_{null_type}"] = float(
                (1.0 + np.sum(trial_means.to_numpy(dtype=float) >= target_delta))
                / (len(trial_means) + 1.0)
            )
            summary.loc[idx, f"excess_delta_abs_error_vs_{null_type}"] = (
                target_delta - float(trial_means.mean())
            )
            summary.loc[idx, f"random_{null_type}_mean_abs_pred_delta"] = float(trial_pred.mean())
            summary.loc[idx, f"empirical_p_abs_pred_delta_{null_type}"] = float(
                (1.0 + np.sum(trial_pred.to_numpy(dtype=float) >= target_pred))
                / (len(trial_pred) + 1.0)
            )
            if null_type == "layer_matched":
                target_by_graph = target_rows.groupby("graph_uid")["delta_abs_error"].mean()
                random_by_graph = random_rows.groupby("graph_uid")["delta_abs_error"].mean()
                common = target_by_graph.index.intersection(random_by_graph.index)
                diffs = (
                    target_by_graph.loc[common].to_numpy(dtype=float)
                    - random_by_graph.loc[common].to_numpy(dtype=float)
                )
                lo, hi = _bootstrap_ci(diffs, rng, cfg.causal_bootstrap_samples)
                summary.loc[idx, "paired_excess_delta_abs_error_layer_matched"] = (
                    float(np.mean(diffs)) if diffs.size else np.nan
                )
                summary.loc[idx, "paired_excess_delta_abs_error_ci95_low"] = lo
                summary.loc[idx, "paired_excess_delta_abs_error_ci95_high"] = hi
                summary.loc[idx, "paired_signflip_p_delta_abs_error_layer_matched"] = (
                    _sign_flip_p_value(diffs, rng, cfg.causal_permutation_samples)
                )

    p_col = "paired_signflip_p_delta_abs_error_layer_matched"
    if p_col in summary.columns:
        summary["q_value_layer_matched_delta_abs_error"] = _bh_q_values(summary[p_col].tolist())
    return summary


def make_causal_subset_summary(rows_df: pd.DataFrame,
                               metric_rows: pd.DataFrame,
                               target_records: Sequence[Dict[str, Any]],
                               cfg: RunConfig,
                               metric_split: str,
                               eval_split: str) -> pd.DataFrame:
    if rows_df.empty or metric_rows.empty or metric_split != eval_split:
        return pd.DataFrame()
    if not {"batch", "graph_in_batch", "metric", "layer", "head", "score"}.issubset(metric_rows.columns):
        return pd.DataFrame()
    metric_rows = metric_rows.copy()
    metric_rows = metric_rows[metric_rows["graph_in_batch"].notna()]
    if metric_rows.empty:
        return pd.DataFrame()
    metric_rows["graph_uid"] = (
        metric_rows["batch"].astype(int).astype(str)
        + ":"
        + metric_rows["graph_in_batch"].astype(int).astype(str)
    )
    rec_by_id = {r["variant_id"]: r for r in target_records}
    out_rows: List[Dict[str, Any]] = []
    for variant_id, rec in rec_by_id.items():
        selector_metrics = rec.get("selector_metrics") or []
        head_pairs = set((int(l), int(h)) for l, h in rec.get("head_pairs", []))
        if not selector_metrics or not head_pairs:
            continue
        sub = metric_rows[
            (metric_rows["model"] == rec["model"])
            & (metric_rows["metric"].isin(selector_metrics))
        ].copy()
        if sub.empty:
            continue
        sub = sub[
            [((int(r.layer), int(r.head)) in head_pairs) for r in sub.itertuples()]
        ]
        if sub.empty:
            continue
        graph_scores = sub.groupby("graph_uid")["score"].mean()
        if graph_scores.empty:
            continue
        threshold = float(graph_scores.quantile(float(cfg.causal_subset_quantile)))
        high_graphs = set(graph_scores[graph_scores >= threshold].index)
        causal = rows_df[rows_df["variant_id"] == variant_id].copy()
        if causal.empty:
            continue
        causal["subset"] = np.where(
            causal["graph_uid"].isin(high_graphs),
            f"top_{int(100 * (1 - cfg.causal_subset_quantile))}pct_metric_subset",
            "remaining_graphs",
        )
        for subset_name, ssub in causal.groupby("subset"):
            out_rows.append({
                "model": rec["model"],
                "split": eval_split,
                "variant_id": variant_id,
                "intervention": rec["intervention"],
                "head_group": rec["head_group"],
                "k": rec["k"],
                "subset": subset_name,
                "metric_subset_threshold": threshold,
                "n_graphs": int(len(ssub)),
                "mean_delta_abs_error": float(ssub["delta_abs_error"].mean()),
                "mean_abs_pred_delta": float(ssub["abs_pred_delta"].mean()),
                "selector_metrics": ",".join(selector_metrics),
            })
    return pd.DataFrame(out_rows)


def _series_or_nan(df: pd.DataFrame, col: str) -> pd.Series:
    if col in df.columns:
        return pd.to_numeric(df[col], errors="coerce")
    return pd.Series(np.nan, index=df.index, dtype=float)


def _format_p_value(value: float) -> str:
    if not np.isfinite(value):
        return "NA"
    if value < 1e-4:
        return "<1e-4"
    return f"{value:.3g}"


def _short_causal_group_label(group: str) -> str:
    text = str(group)
    text = text.replace("_heads", "")
    text = text.replace("top_", "top ")
    text = text.replace("bottom_", "bottom ")
    text = text.replace("_", " ")
    return text


def causal_evidence_dashboard_frame(summary_df: pd.DataFrame,
                                    max_rows: int = 30,
                                    include_model: bool = False) -> pd.DataFrame:
    """Rank metric-guided causal tests in the evidence scale used for plots."""
    if summary_df is None or summary_df.empty:
        return pd.DataFrame()
    target = summary_df[summary_df["variant_type"] == "metric_guided_head_set"].copy()
    if target.empty:
        return pd.DataFrame()

    paired = _series_or_nan(target, "paired_excess_delta_abs_error_layer_matched")
    fallback = _series_or_nan(target, "excess_delta_abs_error_vs_layer_matched")
    raw = _series_or_nan(target, "mean_delta_abs_error")
    target["evidence_effect"] = paired.where(paired.notna(), fallback).where(
        lambda s: s.notna(), raw
    )
    lo = _series_or_nan(target, "paired_excess_delta_abs_error_ci95_low")
    hi = _series_or_nan(target, "paired_excess_delta_abs_error_ci95_high")
    target["evidence_ci_low"] = lo
    target["evidence_ci_high"] = hi
    target["evidence_p"] = _series_or_nan(
        target, "paired_signflip_p_delta_abs_error_layer_matched"
    ).where(
        lambda s: s.notna(),
        _series_or_nan(target, "empirical_p_delta_abs_error_layer_matched"),
    )
    target["evidence_q"] = _series_or_nan(target, "q_value_layer_matched_delta_abs_error")
    target["random_layer_matched_mean"] = _series_or_nan(
        target, "random_layer_matched_mean_delta_abs_error"
    )
    target["evidence_sort"] = target["evidence_effect"].fillna(-np.inf)
    target = target.sort_values(
        ["evidence_sort", "mean_delta_abs_error"],
        ascending=[False, False],
    ).head(int(max_rows)).copy()
    labels = []
    for row in target.itertuples(index=False):
        bits = []
        if include_model:
            bits.append(str(getattr(row, "model")))
        bits.append(str(getattr(row, "intervention")))
        bits.append(f"{_short_causal_group_label(getattr(row, 'head_group'))} k={int(getattr(row, 'k'))}")
        labels.append(" | ".join(bits))
    target["dashboard_label"] = labels
    return target


def plot_causal_evidence_dashboard(summary_df: pd.DataFrame,
                                   out_dir: Path,
                                   title: str,
                                   filename_prefix: str,
                                   max_rows: int = 30,
                                   include_model: bool = False) -> pd.DataFrame:
    import matplotlib.pyplot as plt

    dashboard = causal_evidence_dashboard_frame(
        summary_df, max_rows=max_rows, include_model=include_model
    )
    if dashboard.empty:
        return dashboard
    plots_dir = safe_mkdir(out_dir / "plots_causal_ablation")
    dashboard.to_csv(out_dir / f"{filename_prefix}_causal_evidence_dashboard_rows.csv",
                     index=False)

    plot_df = dashboard.iloc[::-1].reset_index(drop=True)
    y = np.arange(len(plot_df))
    effect = plot_df["evidence_effect"].to_numpy(dtype=float)
    ci_low = plot_df["evidence_ci_low"].to_numpy(dtype=float)
    ci_high = plot_df["evidence_ci_high"].to_numpy(dtype=float)
    q_vals = plot_df["evidence_q"].to_numpy(dtype=float)
    p_vals = plot_df["evidence_p"].to_numpy(dtype=float)

    colors = []
    for effect_i, p_i, q_i in zip(effect, p_vals, q_vals):
        if np.isfinite(q_i) and q_i < 0.05 and effect_i > 0:
            colors.append("#1b7f3a")
        elif np.isfinite(p_i) and p_i < 0.05 and effect_i > 0:
            colors.append("#2f6fbb")
        elif effect_i > 0:
            colors.append("#9aa0a6")
        else:
            colors.append("#d08c8c")

    height = max(5.5, 0.34 * len(plot_df) + 1.8)
    fig, (ax, tax) = plt.subplots(
        1, 2,
        figsize=(13.5, height),
        gridspec_kw={"width_ratios": [4.6, 1.15]},
        sharey=True,
    )
    ax.barh(y, effect, color=colors, alpha=0.92)
    finite_ci = np.isfinite(ci_low) & np.isfinite(ci_high) & np.isfinite(effect)
    if finite_ci.any():
        left = np.maximum(effect[finite_ci] - ci_low[finite_ci], 0.0)
        right = np.maximum(ci_high[finite_ci] - effect[finite_ci], 0.0)
        ax.errorbar(
            effect[finite_ci], y[finite_ci],
            xerr=np.vstack([left, right]),
            fmt="none", ecolor="black", elinewidth=1.0, capsize=2.5,
        )
    ax.axvline(0.0, color="black", linewidth=0.9)
    ax.set_yticks(y)
    ax.set_yticklabels(plot_df["dashboard_label"], fontsize=8)
    ax.set_xlabel("paired excess delta_abs_error vs layer-matched random")
    ax.set_title(title)
    ax.grid(axis="x", alpha=0.25)

    tax.set_xlim(0.0, 1.0)
    tax.set_xticks([])
    tax.set_yticks(y)
    tax.tick_params(left=False, labelleft=False)
    for spine in tax.spines.values():
        spine.set_visible(False)
    tax.set_title("p / q", fontsize=10)
    for i, (p_i, q_i) in enumerate(zip(p_vals, q_vals)):
        tax.text(
            0.0, i,
            f"p={_format_p_value(p_i)}\nq={_format_p_value(q_i)}",
            va="center", ha="left", fontsize=8,
        )

    legend_handles = [
        plt.Line2D([0], [0], color="#1b7f3a", lw=6, label="q < 0.05, positive"),
        plt.Line2D([0], [0], color="#2f6fbb", lw=6, label="p < 0.05, positive"),
        plt.Line2D([0], [0], color="#9aa0a6", lw=6, label="positive"),
        plt.Line2D([0], [0], color="#d08c8c", lw=6, label="non-positive"),
    ]
    ax.legend(handles=legend_handles, loc="lower right", fontsize=8, frameon=True)
    fig.tight_layout()
    fig.savefig(plots_dir / f"{filename_prefix}_causal_evidence_dashboard.png", dpi=170)
    plt.close(fig)
    return dashboard


def plot_causal_outputs(rows_df: pd.DataFrame,
                        summary_df: pd.DataFrame,
                        subset_df: pd.DataFrame,
                        metric_summary: pd.DataFrame,
                        out_dir: Path) -> None:
    if rows_df.empty or summary_df.empty:
        return
    import matplotlib.pyplot as plt

    plots_dir = safe_mkdir(out_dir / "plots_causal_ablation")
    model_name = str(summary_df["model"].iloc[0]) if "model" in summary_df.columns else "model"
    plot_causal_evidence_dashboard(
        summary_df,
        out_dir,
        title=f"{model_name}: causal evidence vs layer-matched random",
        filename_prefix=f"{model_name}",
        max_rows=30,
        include_model=False,
    )
    targets = summary_df[summary_df["variant_type"] == "metric_guided_head_set"].copy()
    if not targets.empty:
        # Random-null histograms for the strongest few targeted effects.
        top_targets = targets.sort_values("mean_delta_abs_error", ascending=False).head(12)
        for _, row in top_targets.iterrows():
            target_id = row["variant_id"]
            for null_type in ["global_matched", "layer_matched"]:
                random_rows = rows_df[
                    (rows_df["matched_to_variant_id"] == target_id)
                    & (rows_df["null_type"] == null_type)
                ]
                if random_rows.empty:
                    continue
                vals = random_rows.groupby("trial")["delta_abs_error"].mean().to_numpy(dtype=float)
                target = float(row["mean_delta_abs_error"])
                fig, ax = plt.subplots(figsize=(6.4, 4.2))
                ax.hist(vals, bins=min(30, max(8, len(vals) // 4)), alpha=0.82)
                ax.axvline(target, color="black", linewidth=2, label="targeted")
                ax.axvline(np.mean(vals), color="grey", linestyle="--", linewidth=1.5, label="random mean")
                ax.set_title(f"{row['head_group']} / {row['intervention']}\nvs {null_type}")
                ax.set_xlabel("mean delta_abs_error")
                ax.set_ylabel("random trials")
                ax.legend(fontsize=8)
                fig.tight_layout()
                safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", target_id + "_" + null_type)
                fig.savefig(plots_dir / f"null_hist_{safe_name}.png", dpi=150)
                plt.close(fig)

        # Dose-response curves by intervention/group.
        for intervention, isub in targets.groupby("intervention"):
            fig, ax = plt.subplots(figsize=(9.0, 5.3))
            for group, gsub in isub.groupby("head_group"):
                gsub = gsub.sort_values("k")
                ax.plot(gsub["k"], gsub["mean_delta_abs_error"], marker="o", label=group)
            ax.axhline(0.0, color="grey", linewidth=0.9)
            ax.set_xlabel("top-k heads ablated")
            ax.set_ylabel("mean delta_abs_error")
            ax.set_title(f"Metric-guided top-k dose response: {intervention}")
            ax.grid(alpha=0.3)
            ax.legend(fontsize=7, ncol=2)
            fig.tight_layout()
            fig.savefig(plots_dir / f"topk_dose_response_{intervention}.png", dpi=150)
            plt.close(fig)

        # Per-graph distributions for head-output intervention.
        dist = rows_df[
            (rows_df["variant_type"] == "metric_guided_head_set")
            & (rows_df["intervention"] == CAUSAL_INTERVENTION_HEAD_OUTPUT)
        ].copy()
        if not dist.empty:
            labels, data = [], []
            for (group, k), sub in dist.groupby(["head_group", "k"]):
                if len(labels) >= 24:
                    break
                labels.append(f"{group}\nk={int(k)}")
                data.append(sub["delta_abs_error"].to_numpy(dtype=float))
            if data:
                fig, ax = plt.subplots(figsize=(max(10, 0.55 * len(data)), 5.0))
                ax.boxplot(data, labels=labels, showfliers=False)
                ax.axhline(0.0, color="grey", linewidth=0.9)
                ax.set_ylabel("per-graph delta_abs_error")
                ax.set_title("Per-graph causal effects under head-output ablation")
                ax.tick_params(axis="x", labelrotation=45, labelsize=7)
                fig.tight_layout()
                fig.savefig(plots_dir / "per_graph_delta_distributions_head_output.png", dpi=150)
                plt.close(fig)

    if subset_df is not None and not subset_df.empty:
        fig, ax = plt.subplots(figsize=(max(9, 0.45 * len(subset_df)), 5.2))
        sub = subset_df.copy().sort_values(["intervention", "head_group", "k", "subset"])
        sub["label"] = sub["head_group"] + "\nk=" + sub["k"].astype(str) + "\n" + sub["subset"]
        x = np.arange(len(sub))
        ax.bar(x, sub["mean_delta_abs_error"].to_numpy(dtype=float))
        ax.axhline(0.0, color="grey", linewidth=0.9)
        ax.set_xticks(x)
        ax.set_xticklabels(sub["label"], rotation=55, ha="right", fontsize=7)
        ax.set_ylabel("mean delta_abs_error")
        ax.set_title("Subset vs full-dataset causal effects")
        fig.tight_layout()
        fig.savefig(plots_dir / "subset_effect_comparison.png", dpi=150)
        plt.close(fig)

    single = summary_df[summary_df["variant_type"] == "single_head"].copy()
    if not single.empty and not metric_summary.empty:
        metric_cols = [
            M_PE_EQUIVARIANT_VALUE,
            M_PAIR_STRUCT_SENS_VALUE,
            M_LOGIT_BIAS_VARIANCE_FRACTION,
            M_SYMBOLIC_CENTERED,
            M_ENTROPY,
        ]
        metric_wide = metric_summary[
            metric_summary["metric"].isin(metric_cols)
        ].pivot_table(index=["model", "layer", "head"], columns="metric", values="mean").reset_index()
        single["layer"] = pd.to_numeric(
            single["head_group"].str.extract(r"L(\d+)H\d+")[0],
            errors="coerce",
        )
        single["head"] = pd.to_numeric(
            single["head_group"].str.extract(r"L\d+H(\d+)")[0],
            errors="coerce",
        )
        metric_wide["layer"] = pd.to_numeric(metric_wide["layer"], errors="coerce")
        metric_wide["head"] = pd.to_numeric(metric_wide["head"], errors="coerce")
        merged = single.merge(metric_wide, on=["model", "layer", "head"], how="left")
        merged.to_csv(out_dir / "single_head_metric_causal_alignment.csv", index=False)
        for metric in metric_cols:
            if metric not in merged.columns:
                continue
            valid = merged[metric].notna() & merged["mean_delta_abs_error"].notna()
            if valid.sum() < 2:
                continue
            fig, ax = plt.subplots(figsize=(6.2, 5.0))
            ax.scatter(merged.loc[valid, metric], merged.loc[valid, "mean_delta_abs_error"],
                       c=merged.loc[valid, "layer"], cmap="viridis", s=70)
            ax.axhline(0.0, color="grey", linewidth=0.9)
            ax.set_xlabel(metric)
            ax.set_ylabel("single-head mean delta_abs_error")
            ax.set_title(f"Metric vs single-head causal effect\n{metric}")
            fig.tight_layout()
            safe_metric = re.sub(r"[^A-Za-z0-9_.-]+", "_", metric)
            fig.savefig(plots_dir / f"single_head_scatter_{safe_metric}.png", dpi=150)
            plt.close(fig)


def run_causal_ablation_suite(spec: ModelSpec,
                              cfg: RunConfig,
                              loaders,
                              probe: AttentionProbeManager,
                              device: torch.device,
                              model_dir: Path,
                              metric_rows: pd.DataFrame,
                              metric_summary: pd.DataFrame) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    if not cfg.run_causal_ablations:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()
    eval_split = cfg.causal_split or cfg.split
    loader = split_loader(loaders, eval_split)
    topk_values = _parse_csv_ints(cfg.causal_topk, default=[1, 2, 4])
    requested_interventions = _parse_csv_strings(
        cfg.causal_interventions,
        default=[
            CAUSAL_INTERVENTION_HEAD_OUTPUT,
            CAUSAL_INTERVENTION_BIAS_ZERO,
            CAUSAL_INTERVENTION_CONTENT_ZERO,
            CAUSAL_INTERVENTION_STRUCT_VALUE_ZERO,
        ],
    )
    interventions = _interventions_for_family(spec.family, requested_interventions)
    all_heads = _all_head_pairs_from_probe(probe.num_heads_by_layer)
    if not all_heads or not interventions:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    print(f"[causal:{spec.name}] split={eval_split} batches={cfg.causal_batches} "
          f"topk={topk_values} random_trials={cfg.causal_random_trials} "
          f"interventions={interventions}")
    causal_dir = safe_mkdir(model_dir / "causal_ablation")
    group_defs = _build_metric_guided_head_groups(
        spec, metric_summary, topk_values, probe.num_heads_by_layer
    )
    rng = random.Random(_causal_seed(cfg))
    rows: List[pd.DataFrame] = []
    target_records: List[Dict[str, Any]] = []

    for intervention in interventions:
        # Architectural sanity baseline: ablate all global heads for the primary
        # intervention. This catches broken hooks and gives scale context.
        if intervention == CAUSAL_INTERVENTION_HEAD_OUTPUT:
            variant_id = _variant_id(
                spec.name, intervention, "all_global_heads", len(all_heads),
                "channel_or_path_baseline",
            )
            meta = {
                "model": spec.name,
                "intervention": intervention,
                "head_group": "all_global_heads",
                "variant_type": "channel_or_path_baseline",
                "variant_id": variant_id,
                "k": len(all_heads),
                "requested_k": len(all_heads),
                "head_pairs": all_heads,
                "target_group": ", ".join(_head_label(l, h) for l, h in all_heads),
                "layer_profile": _layer_profile(all_heads),
            }
            rows.append(_evaluate_causal_variant(
                spec, probe, loader, device, cfg, eval_split,
                _head_pairs_to_ablation_plan(all_heads, intervention),
                meta,
            ))

        for group in group_defs:
            head_pairs = group["head_pairs"]
            if not head_pairs:
                continue
            variant_id = _variant_id(
                spec.name, intervention, group["head_group"], group["k"],
                "metric_guided_head_set",
            )
            meta = {
                **group,
                "model": spec.name,
                "intervention": intervention,
                "variant_type": "metric_guided_head_set",
                "variant_id": variant_id,
            }
            target_records.append(meta.copy())
            rows.append(_evaluate_causal_variant(
                spec, probe, loader, device, cfg, eval_split,
                _head_pairs_to_ablation_plan(head_pairs, intervention),
                meta,
            ))

            for trial in range(max(0, int(cfg.causal_random_trials))):
                for null_type, sampled in [
                    ("global_matched", _sample_global_heads(all_heads, group["k"], rng)),
                    ("layer_matched", _sample_layer_matched_heads(
                        head_pairs, probe.num_heads_by_layer, rng
                    )),
                ]:
                    random_id = _variant_id(
                        spec.name, intervention, group["head_group"], group["k"],
                        f"random_{null_type}_head_set", null_type, trial,
                    )
                    rmeta = {
                        **group,
                        "model": spec.name,
                        "intervention": intervention,
                        "variant_type": f"random_{null_type}_head_set",
                        "null_type": null_type,
                        "trial": int(trial),
                        "matched_to_variant_id": variant_id,
                        "variant_id": random_id,
                        "head_pairs": sampled,
                        "target_group": ", ".join(_head_label(l, h) for l, h in sampled),
                        "layer_profile": _layer_profile(sampled),
                    }
                    rows.append(_evaluate_causal_variant(
                        spec, probe, loader, device, cfg, eval_split,
                        _head_pairs_to_ablation_plan(sampled, intervention),
                        rmeta,
                    ))

    if cfg.causal_single_head and CAUSAL_INTERVENTION_HEAD_OUTPUT in interventions:
        for layer, head in all_heads:
            head_pairs = [(layer, head)]
            group_name = _head_label(layer, head)
            variant_id = _variant_id(
                spec.name, CAUSAL_INTERVENTION_HEAD_OUTPUT, group_name, 1,
                "single_head",
            )
            meta = {
                "model": spec.name,
                "intervention": CAUSAL_INTERVENTION_HEAD_OUTPUT,
                "head_group": group_name,
                "variant_type": "single_head",
                "variant_id": variant_id,
                "k": 1,
                "requested_k": 1,
                "head_pairs": head_pairs,
                "target_group": group_name,
                "layer_profile": _layer_profile(head_pairs),
            }
            rows.append(_evaluate_causal_variant(
                spec, probe, loader, device, cfg, eval_split,
                _head_pairs_to_ablation_plan(head_pairs, CAUSAL_INTERVENTION_HEAD_OUTPUT),
                meta,
            ))

    rows_df = pd.concat([r for r in rows if r is not None and not r.empty],
                        ignore_index=True) if rows else pd.DataFrame()
    summary_df = summarise_causal_rows(rows_df, cfg)
    subset_df = make_causal_subset_summary(
        rows_df, metric_rows, target_records, cfg, cfg.split, eval_split
    )
    rows_df.to_csv(causal_dir / "causal_ablation_rows.csv", index=False)
    summary_df.to_csv(causal_dir / "causal_ablation_summary.csv", index=False)
    if not subset_df.empty:
        subset_df.to_csv(causal_dir / "causal_ablation_subset_summary.csv", index=False)
    pd.DataFrame(target_records).to_csv(causal_dir / "causal_head_group_definitions.csv", index=False)
    plot_causal_outputs(rows_df, summary_df, subset_df, metric_summary, causal_dir)
    print(f"[causal:{spec.name}] wrote {len(rows_df)} rows to {causal_dir}")
    return rows_df, summary_df, subset_df


# -----------------------------------------------------------------------------
# Per-model driver and main
# -----------------------------------------------------------------------------


@torch.no_grad()
def smoke_test(spec, model, probe, loader, device):
    try:
        batch = next(iter(loader))
    except StopIteration:
        raise RuntimeError(f"{spec.name}: loader is empty")
    out = probe.forward_collect(batch.clone().to(device))
    if "pred" not in out or out["pred"].numel() == 0:
        raise RuntimeError(f"{spec.name}: no prediction tensor")
    if not out.get("layers"):
        raise RuntimeError(f"{spec.name}: probe collected no logits")
    print(f"[smoke:{spec.name}] OK | pred_shape={tuple(out['pred'].shape)} "
          f"| layers={len(out['layers'])} | heads={probe.num_heads_by_layer}")


def run_one_model(spec, cfg, device, out_dir):
    cfg_obj, loaders, model = configure_model(spec, cfg, device)
    ckpt = find_checkpoint(spec.run_root, spec.ckpt_path)
    ckpt_meta = load_checkpoint(model, ckpt, device)
    loader = split_loader(loaders, cfg.split)
    probe = AttentionProbeManager(model, spec.family)
    try:
        smoke_test(spec, model, probe, loader, device)
        df, meta, snapshot = collect_metrics_for_model(
            spec, probe, loader, device, cfg
        )
        meta.update(ckpt_meta)
        model_dir = safe_mkdir(out_dir / spec.name)
        df.to_csv(model_dir / "metric_rows.csv", index=False)
        summary = summarise(df)
        summary.to_csv(model_dir / "metric_summary.csv", index=False)
        causal_rows, causal_summary, causal_subset = run_causal_ablation_suite(
            spec, cfg, loaders, probe, device, model_dir, df, summary
        )
    finally:
        probe.close()
        del model
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    return df, summary, meta, snapshot, causal_rows, causal_summary, causal_subset


def run_all_models_main() -> None:
    suppress_known_runtime_warnings()
    cfg = parse_args()
    set_seed(cfg.seed)
    mount_drive_if_needed(cfg.auto_mount_drive)
    ensure_runtime_dependencies(cfg)
    out_dir = safe_mkdir(cfg.out_dir)
    device = torch.device(cfg.device if (cfg.device != "cuda"
                                         or torch.cuda.is_available()) else "cpu")
    print(f"[run] device={device}")
    print(f"[run] outputs={out_dir}")
    print(f"[run] sampling: batch_size={cfg.batch_size} "
          f"metric_batches={cfg.metric_batches} num_perms={cfg.num_perms} "
          f"metric_space={cfg.metric_space} alpha_tau={cfg.metric_alpha_tau}")

    all_rows, all_summary, metas = [], [], []
    all_causal_rows, all_causal_summary, all_causal_subset = [], [], []
    for spec in cfg.models:
        print("\n" + "#" * 80)
        print(f"[run] {spec.name}")
        result = run_one_model(spec, cfg, device, out_dir)
        df, summary, meta = result[:3]
        all_rows.append(df)
        all_summary.append(summary)
        metas.append(meta)
        if cfg.run_causal_ablations:
            causal_rows, causal_summary, causal_subset = result[4:7]
            if causal_rows is not None and not causal_rows.empty:
                all_causal_rows.append(causal_rows)
            if causal_summary is not None and not causal_summary.empty:
                all_causal_summary.append(causal_summary)
            if causal_subset is not None and not causal_subset.empty:
                all_causal_subset.append(causal_subset)

    combined_rows = pd.concat(all_rows, ignore_index=True) if all_rows else pd.DataFrame()
    combined_summary = (pd.concat(all_summary, ignore_index=True)
                        if all_summary else pd.DataFrame())
    combined_rows.to_csv(out_dir / "combined_metric_rows.csv", index=False)
    combined_summary.to_csv(out_dir / "combined_metric_summary.csv", index=False)
    if cfg.run_causal_ablations:
        combined_causal_rows = (
            pd.concat(all_causal_rows, ignore_index=True)
            if all_causal_rows else pd.DataFrame()
        )
        combined_causal_summary = (
            pd.concat(all_causal_summary, ignore_index=True)
            if all_causal_summary else pd.DataFrame()
        )
        combined_causal_subset = (
            pd.concat(all_causal_subset, ignore_index=True)
            if all_causal_subset else pd.DataFrame()
        )
        combined_causal_rows.to_csv(out_dir / "combined_causal_ablation_rows.csv", index=False)
        combined_causal_summary.to_csv(out_dir / "combined_causal_ablation_summary.csv", index=False)
        if not combined_causal_subset.empty:
            combined_causal_subset.to_csv(out_dir / "combined_causal_ablation_subset_summary.csv", index=False)
        if not combined_causal_summary.empty:
            plot_causal_evidence_dashboard(
                combined_causal_summary,
                out_dir,
                title="Combined causal evidence vs layer-matched random",
                filename_prefix="combined",
                max_rows=45,
                include_model=True,
            )
    with (out_dir / "model_metadata.json").open("w", encoding="utf-8") as f:
        json.dump(metas, f, indent=2)

    print("\n[plots] writing plots...")
    make_plots(combined_summary, out_dir)
    make_graph_subset_analysis(combined_rows, out_dir)
    print(f"\n[done] wrote outputs to {out_dir}")


def main() -> None:
    run_all_models_main()

