@dataclass
class ZincGPIConfig:
    out_dir: str = "/content/drive/MyDrive/zinc_gpi_analysis"
    split: str = "test"
    models: str = "graphormer,grit"
    max_molecules: int = 300
    partners_per_source: int = 16
    batch_size: int = 1
    source_batch_size: int = 256
    num_workers: int = 0
    seed: int = 123
    device: str = "cuda" if torch.cuda.is_available() else "cpu"
    target: str = "last_value"
    far_floor_hops: int = 4
    bootstrap_samples: int = 500
    focal_examples: int = 4
    force_recompute: bool = False
    auto_mount_drive: bool = True
    auto_clone_repos: bool = True
    skip_install: bool = False
    force_install: bool = False
    pyg_version: str = "2.2.0"
    verbose_every: int = 10


def parse_gpi_args() -> ZincGPIConfig:
    p = argparse.ArgumentParser(
        description="Standalone Colab GPI source-map analysis for trained ZINC graph transformers."
    )
    p.add_argument("--out-dir", type=str, default=ZincGPIConfig.out_dir)
    p.add_argument("--split", type=str, choices=["train", "val", "test"], default=ZincGPIConfig.split)
    p.add_argument("--models", type=str, default=ZincGPIConfig.models,
                   help="Comma-separated aliases/names: graphormer, grit, graphgps, csa, v19, all.")
    p.add_argument("--max-molecules", type=int, default=ZincGPIConfig.max_molecules)
    p.add_argument("--partners-per-source", type=int, default=ZincGPIConfig.partners_per_source)
    p.add_argument("--source-batch-size", type=int, default=ZincGPIConfig.source_batch_size)
    p.add_argument("--num-workers", type=int, default=ZincGPIConfig.num_workers)
    p.add_argument("--seed", type=int, default=ZincGPIConfig.seed)
    p.add_argument("--device", type=str, default=ZincGPIConfig.device)
    p.add_argument("--target", type=str, choices=["last_value"], default=ZincGPIConfig.target)
    p.add_argument("--far-floor-hops", type=int, default=ZincGPIConfig.far_floor_hops)
    p.add_argument("--bootstrap-samples", type=int, default=ZincGPIConfig.bootstrap_samples)
    p.add_argument("--focal-examples", type=int, default=ZincGPIConfig.focal_examples)
    p.add_argument("--force-recompute", action="store_true")
    p.add_argument("--no-auto-mount-drive", dest="auto_mount_drive", action="store_false")
    p.add_argument("--auto-clone-repos", action="store_true", default=True)
    p.add_argument("--no-auto-clone-repos", dest="auto_clone_repos", action="store_false")
    p.add_argument("--skip-install", action="store_true")
    p.add_argument("--force-install", action="store_true")
    p.add_argument("--pyg-version", type=str, default=ZincGPIConfig.pyg_version)
    p.add_argument("--verbose-every", type=int, default=ZincGPIConfig.verbose_every)
    # Exact path overrides from the source Colab loader script.
    p.add_argument("--graphgps-repo-dir", type=str, default=GRAPHGPS_REPO_DIR)
    p.add_argument("--graphgps-run-root", type=str, default=GRAPHGPS_RUN_ROOT)
    p.add_argument("--graphgps-data-dir", type=str, default=GRAPHGPS_DATA_DIR)
    p.add_argument("--graphgps-ckpt", type=str, default=GRAPHGPS_CKPT)
    p.add_argument("--grit-repo-dir", type=str, default=GRIT_REPO_DIR)
    p.add_argument("--grit-run-root", type=str, default=GRIT_RUN_ROOT)
    p.add_argument("--grit-data-dir", type=str, default=GRIT_DATA_DIR)
    p.add_argument("--grit-ckpt", type=str, default=GRIT_CKPT)
    p.add_argument("--graphormer-run-root", type=str, default=GRAPHORMER_RUN_ROOT)
    p.add_argument("--graphormer-data-dir", type=str, default=GRAPHORMER_DATA_DIR)
    p.add_argument("--graphormer-cache-dir", type=str, default=GRAPHORMER_CACHE_DIR)
    p.add_argument("--graphormer-ckpt", type=str, default=GRAPHORMER_CKPT)
    p.add_argument("--csa-run-root", type=str, default=CSA_RUN_ROOT)
    p.add_argument("--csa-data-dir", type=str, default=CSA_DATA_DIR)
    p.add_argument("--csa-cache-path", type=str, default=CSA_CACHE_PATH)
    p.add_argument("--csa-ckpt", type=str, default=CSA_CKPT)
    p.add_argument("--v19-run-root", type=str, default=V19_RUN_ROOT)
    p.add_argument("--v19-data-dir", type=str, default=V19_DATA_DIR)
    p.add_argument("--v19-ckpt", type=str, default=V19_CKPT)
    args, unknown = p.parse_known_args()
    if unknown:
        print(f"[args] Ignoring kernel args: {unknown}")
    cfg = ZincGPIConfig(
        out_dir=args.out_dir,
        split=args.split,
        models=args.models,
        max_molecules=args.max_molecules,
        partners_per_source=args.partners_per_source,
        source_batch_size=args.source_batch_size,
        num_workers=args.num_workers,
        seed=args.seed,
        device=args.device,
        target=args.target,
        far_floor_hops=args.far_floor_hops,
        bootstrap_samples=args.bootstrap_samples,
        focal_examples=args.focal_examples,
        force_recompute=args.force_recompute,
        auto_mount_drive=args.auto_mount_drive,
        auto_clone_repos=args.auto_clone_repos,
        skip_install=args.skip_install,
        force_install=args.force_install,
        pyg_version=args.pyg_version,
        verbose_every=args.verbose_every,
    )
    cfg._path_args = args  # type: ignore[attr-defined]
    return cfg


def build_gpi_run_config(gpi_cfg: ZincGPIConfig) -> RunConfig:
    args = gpi_cfg._path_args  # type: ignore[attr-defined]
    run_cfg = RunConfig(
        split=gpi_cfg.split,
        out_dir=gpi_cfg.out_dir,
        batch_size=1,
        metric_batches=1,
        num_perms=1,
        seed=gpi_cfg.seed,
        num_workers=gpi_cfg.num_workers,
        device=gpi_cfg.device,
        auto_mount_drive=gpi_cfg.auto_mount_drive,
        auto_clone_repos=gpi_cfg.auto_clone_repos,
        skip_install=gpi_cfg.skip_install,
        force_install=gpi_cfg.force_install,
        pyg_version=gpi_cfg.pyg_version,
        verbose_every=gpi_cfg.verbose_every,
        run_causal_ablations=False,
    )
    run_cfg.models = [
        ModelSpec(name="v19", family="v19",
                  repo_dir=V19_REPO_DIR, repo_url=V19_REPO,
                  commit=V19_COMMIT, cfg_relpath=V19_CFG,
                  run_root=args.v19_run_root, data_dir=args.v19_data_dir,
                  ckpt_path=args.v19_ckpt,
                  name_tag="LatentPairMemory.ValueActive"),
        ModelSpec(name="graphgps_gps_rwse", family="graphgps",
                  repo_dir=args.graphgps_repo_dir, repo_url=GRAPHGPS_REPO,
                  commit=GRAPHGPS_COMMIT, cfg_relpath=GRAPHGPS_CFG,
                  run_root=args.graphgps_run_root, data_dir=args.graphgps_data_dir,
                  ckpt_path=args.graphgps_ckpt,
                  name_tag="ColabDrive.official.GPSwRWSE"),
        ModelSpec(name="grit_rrwp", family="grit",
                  repo_dir=args.grit_repo_dir, repo_url=GRIT_REPO,
                  commit=GRIT_COMMIT, cfg_relpath=GRIT_CFG,
                  run_root=args.grit_run_root, data_dir=args.grit_data_dir,
                  ckpt_path=args.grit_ckpt,
                  name_tag="ColabDrive.official.GRITwRRWP"),
        ModelSpec(name="graphormer_slim", family="graphormer",
                  repo_dir=GRAPHORMER_REPO_DIR, repo_url=GRAPHORMER_REPO,
                  commit=GRAPHORMER_COMMIT, cfg_relpath=GRAPHORMER_CFG,
                  run_root=args.graphormer_run_root,
                  data_dir=args.graphormer_data_dir,
                  ckpt_path=args.graphormer_ckpt,
                  name_tag="Standalone.GraphormerSLIM"),
        ModelSpec(name="csa_sym", family="csa",
                  repo_dir=CSA_REPO_DIR, repo_url=CSA_REPO,
                  commit=CSA_COMMIT, cfg_relpath=CSA_CFG,
                  run_root=args.csa_run_root, data_dir=args.csa_data_dir,
                  ckpt_path=args.csa_ckpt,
                  name_tag="StaticAnchor.SymBiasValue"),
    ]
    run_cfg._graphormer_cache_dir = args.graphormer_cache_dir
    run_cfg._csa_cache_path = args.csa_cache_path
    return run_cfg


def select_gpi_specs(run_cfg: RunConfig, models_arg: str) -> List[ModelSpec]:
    alias = {}
    for spec in run_cfg.models:
        alias[spec.name] = spec
        alias[spec.family] = spec
    alias.update({
        "graphormer": alias["graphormer"],
        "grit": alias["grit"],
        "graphgps": alias["graphgps"],
        "gps": alias["graphgps"],
    })
    names = [x.strip() for x in models_arg.split(",") if x.strip()]
    if not names or "all" in names:
        return list(run_cfg.models)
    specs = []
    for name in names:
        if name not in alias:
            raise KeyError(f"Unknown model alias {name!r}; available={sorted(alias)}")
        spec = alias[name]
        if spec.name not in {s.name for s in specs}:
            specs.append(spec)
    return specs


def gpi_num_nodes(batch) -> int:
    if isinstance(batch, GraphormerBatchAdapter):
        return int(batch.d["node_mask"][0].sum().item())
    if isinstance(batch, (CSABatchAdapter, V19BatchAdapter)):
        return int(batch.counts[0].item())
    if hasattr(batch, "ptr"):
        return int((batch.ptr[1] - batch.ptr[0]).item())
    if hasattr(batch, "num_nodes"):
        return int(batch.num_nodes)
    raise TypeError(type(batch))


def gpi_node_features(batch, n: int) -> torch.Tensor:
    if isinstance(batch, GraphormerBatchAdapter):
        return batch.d["x"][0, :n].reshape(n, -1).float()
    if isinstance(batch, CSABatchAdapter):
        return batch.b.x[:n].reshape(n, -1).float()
    if isinstance(batch, V19BatchAdapter):
        return batch.b.x[:n].reshape(n, -1).float()
    return batch.x[:n].reshape(n, -1).float()


def gpi_distances(batch, n: int) -> np.ndarray:
    if isinstance(batch, GraphormerBatchAdapter):
        sp = batch.d["spatial_pos"][0, :n, :n].detach().cpu().numpy().astype(float)
        dist = sp - 1.0
        dist[sp <= 0] = np.inf
        np.fill_diagonal(dist, 0.0)
        return dist
    if isinstance(batch, CSABatchAdapter):
        spd = batch.b.spd[0, :n, :n].detach().cpu().numpy().astype(float)
        spd[spd < 0] = np.inf
        np.fill_diagonal(spd, 0.0)
        return spd
    if isinstance(batch, V19BatchAdapter):
        spd = batch.b.spd[0, :n, :n].detach().cpu().numpy().astype(float)
        spd[spd < 0] = np.inf
        np.fill_diagonal(spd, 0.0)
        return spd
    import networkx as _nx
    edge_index = batch.edge_index.detach().cpu()
    g = _nx.Graph()
    g.add_nodes_from(range(n))
    for u, v in edge_index.t().tolist():
        if int(u) < n and int(v) < n:
            g.add_edge(int(u), int(v))
    dist = np.full((n, n), np.inf, dtype=float)
    for source, lengths in _nx.all_pairs_shortest_path_length(g):
        for target, d in lengths.items():
            dist[int(source), int(target)] = float(d)
    return dist


def gpi_graph_edges(batch, n: int) -> List[Tuple[int, int]]:
    if isinstance(batch, GraphormerBatchAdapter):
        dist = gpi_distances(batch, n)
        return [(i, j) for i in range(n) for j in range(i + 1, n) if dist[i, j] == 1]
    if isinstance(batch, CSABatchAdapter):
        dist = gpi_distances(batch, n)
        return [(i, j) for i in range(n) for j in range(i + 1, n) if dist[i, j] == 1]
    if isinstance(batch, V19BatchAdapter):
        dist = gpi_distances(batch, n)
        return [(i, j) for i in range(n) for j in range(i + 1, n) if dist[i, j] == 1]
    edges = set()
    for u, v in batch.edge_index.detach().cpu().t().tolist():
        if int(u) < n and int(v) < n and int(u) != int(v):
            edges.add(tuple(sorted((int(u), int(v)))))
    return sorted(edges)


def sample_swap_records(x: torch.Tensor, partners_per_source: int,
                        rng: np.random.Generator) -> List[Tuple[int, int, float]]:
    n = int(x.shape[0])
    records: List[Tuple[int, int, float]] = []
    for source in range(n):
        candidates = [p for p in range(n) if p != source]
        non_identical = [
            p for p in candidates
            if float(torch.norm(x[source] - x[p]).item()) > 1.0e-12
        ]
        pool = non_identical if non_identical else candidates
        if not pool:
            continue
        partners = rng.choice(pool, size=int(partners_per_source), replace=(len(pool) < partners_per_source))
        for partner in partners.tolist():
            norm = float(torch.norm(x[source] - x[int(partner)]).item())
            records.append((source, int(partner), max(norm, 1.0e-12)))
    return records


def make_swapped_batch(batch, records: Sequence[Tuple[int, int, float]]):
    if isinstance(batch, GraphormerBatchAdapter):
        q = len(records)
        new_d: Dict[str, torch.Tensor] = {}
        for key, value in batch.d.items():
            if torch.is_tensor(value) and value.dim() > 0 and int(value.size(0)) == 1:
                reps = [q] + [1] * (value.dim() - 1)
                new_d[key] = value.repeat(*reps).clone()
            elif torch.is_tensor(value):
                new_d[key] = value.clone()
            else:
                new_d[key] = value
        x = new_d["x"]
        for row, (source, partner, _norm) in enumerate(records):
            tmp = x[row, source].clone()
            x[row, source] = x[row, partner]
            x[row, partner] = tmp
        return GraphormerBatchAdapter(new_d)
    if isinstance(batch, CSABatchAdapter):
        q = len(records)
        b = batch.b
        n = int(batch.counts[0].item())
        edge_count = int(b.edge_index.size(1))
        x = b.x[:n].repeat(q).clone()
        for row, (source, partner, _norm) in enumerate(records):
            offset = row * n
            tmp = x[offset + source].clone()
            x[offset + source] = x[offset + partner]
            x[offset + partner] = tmp
        offsets = (torch.arange(q, dtype=b.edge_index.dtype).view(q, 1, 1) * n)
        edge_index = (b.edge_index[:, :edge_count].unsqueeze(0) + offsets).permute(1, 0, 2).reshape(2, q * edge_count)
        edge_attr = b.edge_attr[:edge_count].repeat(q)
        rwse = b.rwse[:n].repeat(q, 1)
        degree = b.degree[:n].repeat(q)
        batch_index = torch.arange(q).repeat_interleave(n)
        node_pos = torch.arange(n).repeat(q)
        fields = {
            "x": x,
            "edge_index": edge_index,
            "edge_attr": edge_attr,
            "y": b.y[:1].repeat(q),
            "rwse": rwse,
            "pair_xi": b.pair_xi[:1, :n, :n].repeat(q, 1, 1, 1),
            "degree": degree,
            "batch_index": batch_index,
            "node_pos": node_pos,
            "node_mask": b.node_mask[:1, :n].repeat(q, 1),
            "pair_mask": b.pair_mask[:1, :n, :n].repeat(q, 1, 1),
            "num_graphs": q,
            "max_nodes": n,
        }
        return CSABatchAdapter(StaticAnchorBatch(**fields))
    if isinstance(batch, V19BatchAdapter):
        q = len(records)
        b = batch.b
        n = int(batch.counts[0].item())
        edge_count = int(b.edge_index.size(1))
        x = b.x[:n].repeat(q).clone()
        for row, (source, partner, _norm) in enumerate(records):
            offset = row * n
            tmp = x[offset + source].clone()
            x[offset + source] = x[offset + partner]
            x[offset + partner] = tmp
        offsets = (torch.arange(q, dtype=b.edge_index.dtype).view(q, 1, 1) * n)
        edge_index = (b.edge_index[:, :edge_count].unsqueeze(0) + offsets).permute(1, 0, 2).reshape(2, q * edge_count)
        edge_attr = b.edge_attr[:edge_count].repeat(q)
        rwse = b.rwse[:n].repeat(q, 1)
        degree = b.degree[:n].repeat(q)
        degree_log = b.degree_log[:n].repeat(q)
        batch_index = torch.arange(q).repeat_interleave(n)
        node_pos = torch.arange(n).repeat(q)
        fields = {
            "x": x,
            "edge_index": edge_index,
            "edge_attr": edge_attr,
            "y": b.y[:1].repeat(q),
            "rwse": rwse,
            "pair_xi": b.pair_xi[:1, :n, :n].repeat(q, 1, 1, 1),
            "degree": degree,
            "degree_log": degree_log,
            "batch_index": batch_index,
            "node_pos": node_pos,
            "node_mask": b.node_mask[:1, :n].repeat(q, 1),
            "pair_mask": b.pair_mask[:1, :n, :n].repeat(q, 1, 1),
            "num_graphs": q,
            "max_nodes": n,
        }
        return V19BatchAdapter(V19VariantABatch(**fields))
    from torch_geometric.data import Batch as PyGBatch
    data = batch.to_data_list()[0]
    variants = []
    for source, partner, _norm in records:
        d = data.clone()
        x = d.x.clone()
        tmp = x[source].clone()
        x[source] = x[partner]
        x[partner] = tmp
        d.x = x
        variants.append(d)
    return PyGBatch.from_data_list(variants)


def target_from_collect(collected: Mapping[str, Any], n: int) -> tuple[torch.Tensor, torch.Tensor]:
    layers = collected.get("layers") or []
    if not layers:
        raise RuntimeError("No attention/value layers collected; cannot compute node-level GPI target.")
    layer = layers[-1]
    value = layer["value_output"].detach().cpu().float()
    node_mask = layer["node_mask"].detach().cpu().bool()
    if value.dim() != 4:
        raise RuntimeError(f"Expected value_output [B,H,N,D], got {tuple(value.shape)}")
    target = value.permute(0, 2, 1, 3).reshape(value.size(0), value.size(2), -1)
    return target[:, :n, :], node_mask[:, :n]


def attention_from_layer(layer: Mapping[str, Any]) -> np.ndarray:
    logits = layer["logits"].detach().cpu().float()
    mask = layer.get("logit_mask")
    if mask is None:
        mask = torch.isfinite(logits).all(dim=1, keepdim=True)
    mask = mask.detach().cpu().bool()
    logits = logits.masked_fill(~mask, float("-inf"))
    attn = torch.softmax(logits, dim=-1)
    attn = torch.where(torch.isfinite(attn), attn, torch.zeros_like(attn))
    return attn.mean(dim=1)[0].numpy()


def attention_rollout_from_layers(layers: Sequence[Mapping[str, Any]], n: int) -> np.ndarray:
    rollout = np.eye(n, dtype=float)
    for layer in layers:
        a = attention_from_layer(layer)[:n, :n]
        a = np.where(np.isfinite(a), a, 0.0)
        a = 0.5 * a + 0.5 * np.eye(n, dtype=float)
        row_sum = a.sum(axis=1, keepdims=True)
        a = a / np.maximum(row_sum, 1.0e-12)
        rollout = a @ rollout
    return rollout


def floor_correct_source_map_zinc(raw: np.ndarray, dist: np.ndarray, far_floor_hops: int) -> np.ndarray:
    raw2 = np.asarray(raw, dtype=float) ** 2
    corrected = np.zeros_like(raw2)
    n = raw2.shape[0]
    for receiver in range(n):
        valid = np.isfinite(dist[receiver]) & (np.arange(n) != receiver)
        far = valid & (dist[receiver] >= float(far_floor_hops))
        floor_mask = far if far.any() else valid
        floor = float(np.min(raw2[receiver, floor_mask])) if floor_mask.any() else 0.0
        corrected[receiver, valid] = np.maximum(raw2[receiver, valid] - floor, 0.0)
    return corrected


def share_normalize(mat: np.ndarray, dist: np.ndarray) -> np.ndarray:
    valid = np.isfinite(dist) & (dist > 0)
    out = np.zeros_like(mat, dtype=float)
    total = float(np.asarray(mat)[valid].sum())
    if total > 0:
        out[valid] = np.asarray(mat, dtype=float)[valid] / total
    return out


def attention_share(attn: np.ndarray, dist: np.ndarray) -> np.ndarray:
    a = np.asarray(attn, dtype=float).copy()
    valid = np.isfinite(dist) & (dist > 0)
    a[~valid] = 0.0
    return share_normalize(np.maximum(a, 0.0), dist)


def compute_one_graph_gpi(spec: ModelSpec, probe: AttentionProbeManager, batch_cpu,
                          device: torch.device, graph_idx: int,
                          cfg: ZincGPIConfig, rng: np.random.Generator) -> Dict[str, Any]:
    n = gpi_num_nodes(batch_cpu)
    x = gpi_node_features(batch_cpu, n)
    dist = gpi_distances(batch_cpu, n)
    records = sample_swap_records(x, cfg.partners_per_source, rng)
    if not records:
        raise RuntimeError(f"{spec.name} graph {graph_idx}: no valid swap records")
    clean = probe.forward_collect(batch_cpu.clone().to(device))
    clean_target, node_mask = target_from_collect(clean, n)
    raw = np.zeros((n, n), dtype=float)
    counts = np.zeros(n, dtype=float)
    for start in range(0, len(records), int(cfg.source_batch_size)):
        chunk = records[start:start + int(cfg.source_batch_size)]
        swapped = make_swapped_batch(batch_cpu, chunk).to(device)
        pert = probe.forward_collect(swapped)
        pert_target, _ = target_from_collect(pert, n)
        delta = pert_target - clean_target
        norms = torch.linalg.norm(delta, dim=-1).numpy()
        for row, (source, _partner, xnorm) in enumerate(chunk):
            raw[:, source] += (norms[row] / max(float(xnorm), 1.0e-12)) ** 2
            counts[source] += 1.0
    raw = np.sqrt(raw / np.maximum(counts[None, :], 1.0))
    corrected = floor_correct_source_map_zinc(raw, dist, cfg.far_floor_hops)
    source_share = share_normalize(corrected, dist)
    layers = clean.get("layers") or []
    last_attn = attention_from_layer(layers[-1])[:n, :n]
    rollout = attention_rollout_from_layers(layers, n)
    last_share = attention_share(last_attn, dist)
    rollout_share = attention_share(rollout, dist)
    return {
        "graph_idx": int(graph_idx),
        "model": spec.name,
        "family": spec.family,
        "n": int(n),
        "distances": dist,
        "raw_source_map": raw,
        "source_map": corrected,
        "source_share": source_share,
        "last_attention_share": last_share,
        "rollout_attention_share": rollout_share,
        "edges": gpi_graph_edges(batch_cpu, n),
        "atom_features": x.numpy(),
    }


def run_gpi_for_model(spec: ModelSpec, run_cfg: RunConfig, gpi_cfg: ZincGPIConfig,
                      device: torch.device, out_dir: Path) -> List[Dict[str, Any]]:
    model_dir = safe_mkdir(out_dir / spec.name)
    cache = model_dir / (
        f"gpi_cache_{gpi_cfg.split}_n{gpi_cfg.max_molecules}_"
        f"k{gpi_cfg.partners_per_source}_seed{gpi_cfg.seed}_{gpi_cfg.target}.pt"
    )
    if cache.exists() and not gpi_cfg.force_recompute:
        print(f"[gpi:{spec.name}] loading cache {cache}")
        return safe_torch_load(cache, map_location="cpu")
    cfg_obj, loaders, model = configure_model(spec, run_cfg, device)
    ckpt = find_checkpoint(spec.run_root, spec.ckpt_path)
    load_checkpoint(model, ckpt, device)
    loader = split_loader(loaders, gpi_cfg.split)
    probe = AttentionProbeManager(model, spec.family)
    records: List[Dict[str, Any]] = []
    rng = np.random.default_rng(int(gpi_cfg.seed) + 10007)
    try:
        for graph_idx, batch in enumerate(loader):
            if graph_idx >= int(gpi_cfg.max_molecules):
                break
            rec = compute_one_graph_gpi(spec, probe, batch, device, graph_idx, gpi_cfg, rng)
            records.append(rec)
            if (graph_idx + 1) % max(int(gpi_cfg.verbose_every), 1) == 0:
                print(f"[gpi:{spec.name}] {graph_idx + 1}/{gpi_cfg.max_molecules} graphs")
    finally:
        probe.close()
        del model
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    torch.save(records, cache)
    print(f"[gpi:{spec.name}] wrote cache {cache}")
    return records


def distance_bins_from_records(records: Sequence[Dict[str, Any]], matrix_key: str) -> pd.DataFrame:
    rows = []
    for rec in records:
        mat = np.asarray(rec[matrix_key], dtype=float)
        dist = np.asarray(rec["distances"], dtype=float)
        valid = np.isfinite(dist) & (dist > 0)
        for d in sorted(set(dist[valid].astype(int).tolist())):
            mask = valid & (dist == float(d))
            rows.append({
                "model": rec["model"],
                "graph_idx": int(rec["graph_idx"]),
                "n": int(rec["n"]),
                "distance": int(d),
                "mass_share": float(mat[mask].sum()),
                "pair_count": int(mask.sum()),
                "matrix": matrix_key,
            })
    return pd.DataFrame(rows)


def bootstrap_profile(df: pd.DataFrame, *, samples: int, seed: int) -> pd.DataFrame:
    if df.empty:
        return df
    rng = np.random.default_rng(int(seed))
    rows = []
    for (model, matrix, distance), group in df.groupby(["model", "matrix", "distance"]):
        graph_ids = group["graph_idx"].drop_duplicates().to_numpy()
        values_by_graph = group.set_index("graph_idx")["mass_share"].to_dict()
        vals = np.array([float(values_by_graph[g]) for g in graph_ids], dtype=float)
        mean = float(vals.mean()) if vals.size else float("nan")
        if vals.size and samples > 0:
            boots = []
            for _ in range(int(samples)):
                idx = rng.integers(0, vals.size, size=vals.size)
                boots.append(float(vals[idx].mean()))
            lo, hi = np.quantile(boots, [0.025, 0.975]).tolist()
        else:
            lo = hi = mean
        rows.append({
            "model": model,
            "matrix": matrix,
            "distance": int(distance),
            "mean": mean,
            "ci_low": float(lo),
            "ci_high": float(hi),
            "graphs": int(vals.size),
            "pair_count": int(group["pair_count"].sum()),
        })
    return pd.DataFrame(rows).sort_values(["matrix", "model", "distance"])


def _spearman(x: np.ndarray, y: np.ndarray) -> float:
    try:
        from scipy.stats import spearmanr
        val = spearmanr(x, y).correlation
        return float(val) if np.isfinite(val) else float("nan")
    except Exception:
        return float(pd.Series(x).corr(pd.Series(y), method="spearman"))


def attention_faithfulness_rows(records: Sequence[Dict[str, Any]]) -> pd.DataFrame:
    rows = []
    for rec in records:
        source = np.asarray(rec["source_share"], dtype=float)
        dist = np.asarray(rec["distances"], dtype=float)
        valid_base = np.isfinite(dist) & (dist > 0)
        for attn_key in ["last_attention_share", "rollout_attention_share"]:
            attn = np.asarray(rec[attn_key], dtype=float)
            corrs = []
            for receiver in range(int(rec["n"])):
                valid = valid_base[receiver]
                if valid.sum() >= 3 and np.std(source[receiver, valid]) > 0 and np.std(attn[receiver, valid]) > 0:
                    corrs.append(_spearman(source[receiver, valid], attn[receiver, valid]))
            rows.append({
                "model": rec["model"],
                "graph_idx": int(rec["graph_idx"]),
                "attention": attn_key,
                "receiver_spearman_mean": float(np.nanmean(corrs)) if corrs else float("nan"),
            })
    return pd.DataFrame(rows)


def import_plotting():
    import matplotlib
    if not os.environ.get("DISPLAY"):
        matplotlib.use("Agg", force=True)
    import matplotlib.pyplot as plt
    return plt


def plot_distance_profile(summary: pd.DataFrame, out_dir: Path) -> None:
    plt = import_plotting()
    df = summary[summary["matrix"] == "source_share"].copy()
    if df.empty:
        return
    fig, ax = plt.subplots(figsize=(6.7, 4.1))
    colors = {
        "graphormer_slim": "#4f78b5",
        "grit_rrwp": "#c2473f",
        "graphgps_gps_rwse": "#3b8b5f",
        "csa_sym": "#8f63b8",
        "v19": "#555555",
    }
    for model, g in df.groupby("model"):
        g = g.sort_values("distance")
        color = colors.get(model, None)
        ax.plot(g["distance"], g["mean"], marker="o", linewidth=2.1, color=color, label=model)
        ax.fill_between(g["distance"], g["ci_low"], g["ci_high"], color=color, alpha=0.14)
    ax.set_title("ZINC GPI: Functional Dependence by Molecular Distance")
    ax.set_xlabel("hop distance between receiver and source atom")
    ax.set_ylabel("share of baseline-corrected source-map mass")
    ax.grid(axis="y", color="#dddddd", linewidth=0.6)
    ax.legend(frameon=False)
    fig.tight_layout()
    path = safe_mkdir(out_dir / "figures") / "zinc_gpi_distance_profile.pdf"
    fig.savefig(path, bbox_inches="tight")
    plt.close(fig)
    print(f"[plot] wrote {path}")


def plot_attention_overlay(summary: pd.DataFrame, out_dir: Path) -> None:
    plt = import_plotting()
    keep = summary[summary["matrix"].isin(["source_share", "last_attention_share", "rollout_attention_share"])].copy()
    if keep.empty:
        return
    models = list(keep["model"].drop_duplicates())
    fig, axes = plt.subplots(1, len(models), figsize=(5.2 * len(models), 3.9), squeeze=False)
    label_map = {
        "source_share": "GPI source map",
        "last_attention_share": "last-layer attention",
        "rollout_attention_share": "attention rollout",
    }
    style = {
        "source_share": ("#111111", "-"),
        "last_attention_share": ("#c2473f", "--"),
        "rollout_attention_share": ("#4f78b5", ":"),
    }
    for ax, model in zip(axes[0], models):
        sub = keep[keep["model"] == model]
        for matrix, g in sub.groupby("matrix"):
            g = g.sort_values("distance")
            color, ls = style[matrix]
            ax.plot(g["distance"], g["mean"], marker="o", linewidth=2.0,
                    color=color, linestyle=ls, label=label_map[matrix])
        ax.set_title(model)
        ax.set_xlabel("hop distance")
        ax.grid(axis="y", color="#dddddd", linewidth=0.6)
    axes[0, 0].set_ylabel("mass share")
    axes[0, -1].legend(frameon=False, fontsize=8)
    fig.suptitle("Attention Attribution vs GPI Functional Dependence", y=1.02)
    fig.tight_layout()
    path = safe_mkdir(out_dir / "figures") / "zinc_gpi_attention_vs_source_distance.pdf"
    fig.savefig(path, bbox_inches="tight")
    plt.close(fig)
    print(f"[plot] wrote {path}")


def plot_attention_scatter(records_by_model: Mapping[str, Sequence[Dict[str, Any]]], out_dir: Path,
                           max_points: int = 8000) -> None:
    plt = import_plotting()
    rng = np.random.default_rng(2027)
    models = list(records_by_model)
    fig, axes = plt.subplots(1, len(models), figsize=(5.0 * len(models), 4.0), squeeze=False)
    for ax, model in zip(axes[0], models):
        xs, ys, cs = [], [], []
        for rec in records_by_model[model]:
            source = np.asarray(rec["source_share"], dtype=float)
            attn = np.asarray(rec["rollout_attention_share"], dtype=float)
            dist = np.asarray(rec["distances"], dtype=float)
            valid = np.isfinite(dist) & (dist > 0)
            xs.extend(attn[valid].tolist())
            ys.extend(source[valid].tolist())
            cs.extend(dist[valid].tolist())
        if len(xs) > max_points:
            idx = rng.choice(len(xs), size=max_points, replace=False)
            xs = np.asarray(xs)[idx]
            ys = np.asarray(ys)[idx]
            cs = np.asarray(cs)[idx]
        sc = ax.scatter(xs, ys, c=cs, s=7, alpha=0.35, cmap="viridis", linewidths=0)
        ax.set_title(model)
        ax.set_xlabel("attention rollout mass")
        ax.grid(color="#eeeeee", linewidth=0.5)
    axes[0, 0].set_ylabel("GPI source-map mass")
    cbar = fig.colorbar(sc, ax=axes.ravel().tolist(), shrink=0.82)
    cbar.set_label("hop distance")
    fig.suptitle("Attention Is Tested Against Causal Source Maps", y=1.02)
    fig.tight_layout()
    path = safe_mkdir(out_dir / "figures") / "zinc_gpi_attention_source_scatter.pdf"
    fig.savefig(path, bbox_inches="tight")
    plt.close(fig)
    print(f"[plot] wrote {path}")


def plot_focal_maps(records_by_model: Mapping[str, Sequence[Dict[str, Any]]], out_dir: Path,
                    examples: int) -> None:
    if examples <= 0 or not records_by_model:
        return
    plt = import_plotting()
    import networkx as _nx
    models = list(records_by_model)
    shared_graphs = set(int(r["graph_idx"]) for r in records_by_model[models[0]])
    for model in models[1:]:
        shared_graphs &= set(int(r["graph_idx"]) for r in records_by_model[model])
    graph_ids = sorted(shared_graphs)[:int(examples)]
    if not graph_ids:
        return
    lookup = {
        model: {int(r["graph_idx"]): r for r in records}
        for model, records in records_by_model.items()
    }
    fig, axes = plt.subplots(len(models), len(graph_ids),
                             figsize=(3.3 * len(graph_ids), 3.0 * len(models)),
                             squeeze=False)
    for row, model in enumerate(models):
        for col, gid in enumerate(graph_ids):
            rec = lookup[model][gid]
            n = int(rec["n"])
            g = _nx.Graph()
            g.add_nodes_from(range(n))
            g.add_edges_from(rec["edges"])
            if g.number_of_edges() == 0:
                continue
            degree = dict(g.degree())
            focal = max(degree, key=degree.get)
            influence = np.asarray(rec["source_share"], dtype=float)[focal].copy()
            vmax = float(max(influence.max(), 1.0e-12))
            pos = _nx.spring_layout(g, seed=gid, iterations=80)
            ax = axes[row, col]
            _nx.draw_networkx_edges(g, pos, ax=ax, width=0.8, alpha=0.45, edge_color="#777777")
            _nx.draw_networkx_nodes(
                g, pos, ax=ax,
                node_color=influence,
                cmap="magma",
                vmin=0.0,
                vmax=vmax,
                node_size=90,
                linewidths=[1.8 if node == focal else 0.3 for node in g.nodes],
                edgecolors=["#111111" if node == focal else "#ffffff" for node in g.nodes],
            )
            ax.set_axis_off()
            if row == 0:
                ax.set_title(f"molecule {gid}")
            if col == 0:
                ax.text(-0.05, 0.5, model, rotation=90, va="center", ha="right",
                        transform=ax.transAxes, fontsize=10)
    fig.suptitle("Focal-Atom GPI Source Maps", y=1.02)
    fig.tight_layout()
    path = safe_mkdir(out_dir / "figures") / "zinc_gpi_focal_source_maps.pdf"
    fig.savefig(path, bbox_inches="tight")
    plt.close(fig)
    print(f"[plot] wrote {path}")


def write_gpi_method_notes(out_dir: Path) -> None:
    notes = {
        "target_used": (
            "Node-level source maps use the last attention layer's per-head value output "
            "as the receiver representation. The protocol asks for final pre-pool h_i; "
            "this is the closest uniform target exposed by the existing Graphormer/GRIT "
            "probe path without architecture-specific readout hooks."
        ),
        "attention_rollout": (
            "Rollout is computed from mean-head attention with a 0.5 residual mixture per layer. "
            "Last-layer attention is reported separately."
        ),
        "sparsification_backstop": (
            "Not run in this first standalone script. Graphormer's graph token and GRIT's "
            "RRWP edge semantics make a fair k-hop attention mask architecture-specific; "
            "this should be implemented as a separate controlled pass if needed."
        ),
        "normalisation": (
            "All GPI maps use RMS content swaps, feature-distance normalisation, per-receiver "
            "far-floor baseline correction, and per-molecule share normalisation."
        ),
    }
    with (safe_mkdir(out_dir) / "methodology_notes.json").open("w", encoding="utf-8") as handle:
        json.dump(notes, handle, indent=2)


def run_zinc_gpi_main() -> None:
    suppress_known_runtime_warnings()
    gpi_cfg = parse_gpi_args()
    set_seed(gpi_cfg.seed)
    mount_drive_if_needed(gpi_cfg.auto_mount_drive)
    run_cfg = build_gpi_run_config(gpi_cfg)
    ensure_runtime_dependencies(run_cfg)
    out_dir = safe_mkdir(gpi_cfg.out_dir)
    write_gpi_method_notes(out_dir)
    device = torch.device(gpi_cfg.device if (gpi_cfg.device != "cuda" or torch.cuda.is_available()) else "cpu")
    specs = select_gpi_specs(run_cfg, gpi_cfg.models)
    print(f"[gpi] device={device} split={gpi_cfg.split} models={[s.name for s in specs]}")
    print(f"[gpi] outputs={out_dir}")
    records_by_model: Dict[str, List[Dict[str, Any]]] = {}
    all_profile_rows = []
    all_faithfulness = []
    for spec in specs:
        print("\n" + "#" * 80)
        print(f"[gpi] running {spec.name}")
        records = run_gpi_for_model(spec, run_cfg, gpi_cfg, device, out_dir)
        records_by_model[spec.name] = records
        for key in ["source_share", "last_attention_share", "rollout_attention_share"]:
            all_profile_rows.append(distance_bins_from_records(records, key))
        all_faithfulness.append(attention_faithfulness_rows(records))
    profile_rows = pd.concat(all_profile_rows, ignore_index=True) if all_profile_rows else pd.DataFrame()
    profile_rows.to_csv(out_dir / "zinc_gpi_distance_profile_rows.csv", index=False)
    profile_summary = bootstrap_profile(
        profile_rows,
        samples=int(gpi_cfg.bootstrap_samples),
        seed=int(gpi_cfg.seed) + 409,
    )
    profile_summary.to_csv(out_dir / "zinc_gpi_distance_profile_summary.csv", index=False)
    faith = pd.concat(all_faithfulness, ignore_index=True) if all_faithfulness else pd.DataFrame()
    faith.to_csv(out_dir / "zinc_gpi_attention_faithfulness_rows.csv", index=False)
    if not faith.empty:
        faith_summary = (
            faith.groupby(["model", "attention"], as_index=False)
            .agg(receiver_spearman_mean=("receiver_spearman_mean", "mean"),
                 graphs=("graph_idx", "nunique"))
        )
        faith_summary.to_csv(out_dir / "zinc_gpi_attention_faithfulness_summary.csv", index=False)
    plot_distance_profile(profile_summary, out_dir)
    plot_attention_overlay(profile_summary, out_dir)
    plot_attention_scatter(records_by_model, out_dir)
    plot_focal_maps(records_by_model, out_dir, gpi_cfg.focal_examples)
    print(f"\n[done] ZINC GPI outputs at {out_dir}")


if __name__ == "__main__":
    run_zinc_gpi_main()
